import { GoogleGenAI, Type } from "@google/genai";
import { Tonality } from '../types';

// NOTE: In a real environment, this should be accessed safely.
// We are assuming process.env.API_KEY is available as per instructions.
const apiKey = process.env.API_KEY; 

const ai = apiKey ? new GoogleGenAI({ apiKey }) : null;

export interface AnalysisResult {
  tonality: Tonality;
  syllables: number;
  expandedDescription: string;
  categorySuggestion: string;
}

export const analyzeTerm = async (root: string, meaning: string): Promise<AnalysisResult | null> => {
  if (!ai) {
    console.error("Gemini API Key missing");
    return null;
  }

  try {
    const prompt = `
      Analyze the following fictional or conlang term:
      Root Word: "${root}"
      Basic Meaning: "${meaning}"

      Tasks:
      1. Determine the emotional tonality (Positive, Neutral, Negative/Conflict, Transformative, Mixed).
      2. Count the syllables in the Root Word roughly based on phonetics.
      3. Write a short, poetic, 1-sentence expanded description or nuance for this term.
      4. Suggest the best category from this list: [Emociones y Estados Internos, Conexiones y Relaciones, Sensaciones y Percepciones, Transformaciones y Ciclos, Naturaleza y Elementos, Estados Abstractos y Consciencia, Dinámicas del Cosmos, Impulsos, Acción y Tiempo, Sombras, Crisis y Entorno, Luz y Claridad].

      Return JSON.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-lite-latest', // Fast model for UI responsiveness
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tonality: { type: Type.STRING, enum: Object.values(Tonality) },
            syllables: { type: Type.INTEGER },
            expandedDescription: { type: Type.STRING },
            categorySuggestion: { type: Type.STRING }
          }
        }
      }
    });

    const text = response.text;
    if (!text) return null;

    return JSON.parse(text) as AnalysisResult;

  } catch (error) {
    console.error("Error analyzing term with Gemini:", error);
    return null;
  }
};

import { Term, Tonality } from '../types';

export const calculateLetterDistribution = (terms: Term[]) => {
  const counts: Record<string, number> = {};
  terms.forEach(term => {
    const cleanRoot = term.root.toLowerCase().replace(/[^a-z]/g, '');
    for (const char of cleanRoot) {
      counts[char] = (counts[char] || 0) + 1;
    }
  });

  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1]) // Sort descending
    .slice(0, 10) // Top 10
    .map(([name, value]) => ({ name: name.toUpperCase(), value }));
};

export const calculateVowelConsonantRatio = (terms: Term[]) => {
  let vowels = 0;
  let consonants = 0;
  const vowelList = ['a', 'e', 'i', 'o', 'u'];

  terms.forEach(term => {
    const cleanRoot = term.root.toLowerCase().replace(/[^a-z]/g, '');
    for (const char of cleanRoot) {
      if (vowelList.includes(char)) vowels++;
      else consonants++;
    }
  });

  const total = vowels + consonants;
  if (total === 0) return [];

  return [
    { name: 'Vocales', value: vowels, color: '#8884d8' },
    { name: 'Consonantes', value: consonants, color: '#82ca9d' }
  ];
};

export const calculateWordLengthDist = (terms: Term[]) => {
  const dist: Record<number, number> = {};
  terms.forEach(term => {
    const len = term.root.length;
    dist[len] = (dist[len] || 0) + 1;
  });

  return Object.entries(dist)
    .map(([len, count]) => ({ name: `${len} letras`, value: count }))
    .sort((a, b) => parseInt(a.name) - parseInt(b.name));
};

export const calculateTonalityDist = (terms: Term[]) => {
  const dist: Record<string, number> = {};
  Object.values(Tonality).forEach(t => dist[t] = 0);

  terms.forEach(term => {
    dist[term.tonality] = (dist[term.tonality] || 0) + 1;
  });

  // Color mapping for tonalities
  const colors: Record<string, string> = {
    [Tonality.POSITIVE]: '#4ade80', // green
    [Tonality.NEUTRAL]: '#94a3b8', // slate
    [Tonality.NEGATIVE]: '#f87171', // red
    [Tonality.TRANSFORMATIVE]: '#c084fc', // purple
    [Tonality.MIXED]: '#fbbf24' // amber
  };

  return Object.entries(dist).map(([name, value]) => ({
    name,
    value,
    color: colors[name] || '#ccc'
  })).filter(x => x.value > 0);
};

export const calculateCategoryDist = (terms: Term[]) => {
   const dist: Record<string, number> = {};
   terms.forEach(term => {
     dist[term.category] = (dist[term.category] || 0) + 1;
   });

   return Object.entries(dist)
    .map(([name, value]) => ({ name, value }))
    .sort((a, b) => b.value - a.value);
};

