import React, { useMemo } from 'react';
import { Term } from '../types';
import { 
  calculateLetterDistribution, 
  calculateVowelConsonantRatio, 
  calculateWordLengthDist,
  calculateTonalityDist,
  calculateCategoryDist
} from '../utils/statistics';
import { 
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell, 
  PieChart, Pie, Legend, AreaChart, Area, CartesianGrid 
} from 'recharts';

interface Props {
  terms: Term[];
}

const StatsDashboard: React.FC<Props> = ({ terms }) => {
  const letterDist = useMemo(() => calculateLetterDistribution(terms), [terms]);
  const vcRatio = useMemo(() => calculateVowelConsonantRatio(terms), [terms]);
  const lengthDist = useMemo(() => calculateWordLengthDist(terms), [terms]);
  const tonalityDist = useMemo(() => calculateTonalityDist(terms), [terms]);
  const categoryDist = useMemo(() => calculateCategoryDist(terms), [terms]);

  const totalTerms = terms.length;
  const avgLength = useMemo(() => {
    if (totalTerms === 0) return 0;
    const totalChars = terms.reduce((acc, t) => acc + t.root.length, 0);
    return (totalChars / totalTerms).toFixed(2);
  }, [terms, totalTerms]);

  return (
    <div className="p-6 grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6 animate-fade-in">

      {/* KPI Cards */}
      <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-3 gap-4 mb-4">
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
          <h3 className="text-slate-400 text-sm font-medium">Total Radicales</h3>
          <p className="text-4xl font-bold text-white mt-2">{totalTerms}</p>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
          <h3 className="text-slate-400 text-sm font-medium">Longitud Promedio</h3>
          <p className="text-4xl font-bold text-indigo-400 mt-2">{avgLength} <span className="text-lg text-slate-500">letras</span></p>
        </div>
        <div className="bg-slate-800 p-6 rounded-xl border border-slate-700">
          <h3 className="text-slate-400 text-sm font-medium">Categorías Activas</h3>
          <p className="text-4xl font-bold text-purple-400 mt-2">{categoryDist.length}</p>
        </div>
      </div>

      {/* Tonalidad Chart */}
      <div className="bg-slate-800 p-6 rounded-xl border border-slate-700 min-h-[300px]">
        <h3 className="text-white font-semibold mb-6">Distribución de Tonalidad</h3>
