          <div className="relative">
            <Filter className="absolute left-3 top-3 text-slate-500" size={18} />
            <select 
              value={categoryFilter} 
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="bg-slate-900 border border-slate-700 rounded-lg pl-10 pr-8 py-2.5 text-slate-300 outline-none appearance-none cursor-pointer hover:bg-slate-800 w-full sm:w-auto"
            >
