          <p className="text-slate-400">Añade nuevos términos al glosario. Usa la IA para expandir significados y analizar tonalidad.</p>
        </div>

        <div className="p-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">Raíz (Palabra)</label>
                <input 
                  type="text" 
                  value={root}
                  onChange={e => setRoot(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none text-lg font-bold"
                  placeholder="Ej: Kael"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-400 mb-2">Significado Base</label>
                <input 
                  type="text" 
                  value={meaning}
                  onChange={e => setMeaning(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                  placeholder="Ej: Micro-salto evolutivo"
                />
              </div>
            </div>

            {/* AI Action Area */}
            <div className="bg-indigo-900/20 border border-indigo-500/30 rounded-xl p-4 flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                  <Sparkles size={20} />
                </div>
                <div className="text-sm">
                  <p className="text-indigo-200 font-medium">Análisis Inteligente</p>
                  <p className="text-indigo-400/60">Auto-detectar tonalidad, sílabas y matiz poético.</p>
                </div>
              </div>
              <button 
                type="button"
                onClick={handleAnalyze}
                disabled={isAnalyzing || !root}
