import React, { useState, useMemo } from 'react';
import { Type, Spline, Activity } from 'lucide-react';

type GridMode = 'algante' | 'comun';
type CurveType = 'linear' | 'smooth';

// Grid configurations based on images
// x = col index, y = row index
interface LetterPos { x: number; y: number; char: string }

const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper to flatten grid and find coordinates
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      // If char appears multiple times (like K in Comun), this takes the last one.
      // To support first found, we check existence.
      if (!map.has(char)) {
        map.set(char, { x, y });
      }
    });
  });
  return map;
};

const Taelim: React.FC = () => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [curveType, setCurveType] = useState<CurveType>('linear');

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  // SVG Dimensions & Scaling
  const width = 600;
  const height = 500;
  const padding = 60;

  const cellWidth = (width - padding * 2) / (cols - 1);
  const cellHeight = (height - padding * 2) / (rows - 1);

  const getCoord = (x: number, y: number) => ({
    cx: padding + x * cellWidth,
    cy: padding + y * cellHeight
  });

  // Calculate path points
  const activePoints = text.toUpperCase().split('').map(char => {
    const pos = gridMap.get(char);
    if (!pos) return null;
    return getCoord(pos.x, pos.y);
  }).filter((p): p is {cx: number, cy: number} => p !== null);

  // Path Generation Logic
  const generatePath = (points: {cx: number, cy: number}[]) => {
    if (points.length === 0) return '';
    if (points.length === 1) return `M ${points[0].cx} ${points[0].cy} L ${points[0].cx} ${points[0].cy}`; // Dot

    if (curveType === 'linear') {
      return points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.cx} ${p.cy}`).join(' ');
    } else {
      // Catmull-Rom to Cubic Bezier conversion for smoothness through points
      let d = `M ${points[0].cx} ${points[0].cy}`;

      for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i === 0 ? 0 : i - 1];
        const p1 = points[i];
        const p2 = points[i + 1];
        const p3 = points[i + 2 < points.length ? i + 2 : i + 1];

        const cp1x = p1.cx + (p2.cx - p0.cx) / 6;
        const cp1y = p1.cy + (p2.cy - p0.cy) / 6;

        const cp2x = p2.cx - (p3.cx - p1.cx) / 6;
        const cp2y = p2.cy - (p3.cy - p1.cy) / 6;

        d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.cx} ${p2.cy}`;
      }
      return d;
    }
  };

  const pathData = generatePath(activePoints);

  return (
    <div className="max-w-6xl mx-auto p-6 animate-fade-in">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* Controls Panel */}
        <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 h-fit">
          <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-700">
            <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
              <Type size={24} />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">Tael'im</h2>
              <p className="text-slate-400 text-sm">Tejedor de Símbolos</p>
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-slate-400 mb-2">Radical / Palabra</label>
              <input 
                type="text" 
                value={text}
                onChange={(e) => setText(e.target.value)}
                className="w-full bg-slate-900 border border-slate-600 rounded-lg px-4 py-3 text-white focus:ring-2 focus:ring-indigo-500 outline-none text-xl font-bold tracking-widest uppercase"
                placeholder="Escribe aquí..."
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-400 mb-2">Dialecto (Retícula)</label>
              <div className="grid grid-cols-2 gap-2">
                <button 
                  onClick={() => setMode('algante')}
                  className={`py-2 px-4 rounded-lg border transition-all ${mode === 'algante' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-900 border-slate-700 text-slate-400 hover:bg-slate-800'}`}
                >
                  Algante
                </button>
                <button 
                  onClick={() => setMode('comun')}
                  className={`py-2 px-4 rounded-lg border transition-all ${mode === 'comun' ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-900 border-slate-700 text-slate-400 hover:bg-slate-800'}`}
                >
                  Común
                </button>
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-400 mb-2">Estilo de Trazado</label>
              <div className="flex gap-2">
                <button 
                  onClick={() => setCurveType('linear')}
                  className={`flex-1 py-2 px-4 rounded-lg border flex items-center justify-center gap-2 transition-all ${curveType === 'linear' ? 'bg-emerald-600 border-emerald-500 text-white' : 'bg-slate-900 border-slate-700 text-slate-400 hover:bg-slate-800'}`}
                >
                  <Activity size={16} /> Recta
                </button>
                <button 
                  onClick={() => setCurveType('smooth')}
                  className={`flex-1 py-2 px-4 rounded-lg border flex items-center justify-center gap-2 transition-all ${curveType === 'smooth' ? 'bg-purple-600 border-purple-500 text-white' : 'bg-slate-900 border-slate-700 text-slate-400 hover:bg-slate-800'}`}
                >
                  <Spline size={16} /> Suave
                </button>
              </div>
            </div>

            <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700/50">
               <h4 className="text-sm font-semibold text-slate-300 mb-2">Estadísticas del Símbolo</h4>
               <div className="flex justify-between text-sm text-slate-500">
                 <span>Nodos conectados:</span>
                 <span className="text-white">{activePoints.length}</span>
               </div>
               <div className="flex justify-between text-sm text-slate-500 mt-1">
                 <span>Complejidad:</span>
                 <span className="text-white">{(activePoints.length * (curveType === 'smooth' ? 1.5 : 1)).toFixed(1)}</span>
               </div>
            </div>
          </div>
        </div>

        {/* Visualization Canvas */}
        <div className="lg:col-span-2 bg-slate-950 rounded-2xl border border-slate-800 shadow-2xl relative overflow-hidden flex items-center justify-center p-4">

          {/* Background Gradient Effect */}
          <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900/20 via-slate-950 to-slate-950 pointer-events-none"></div>

          <svg width="100%" height="100%" viewBox={`0 0 ${width} ${height}`} className="max-w-[600px] aspect-[6/5]">
            <defs>
              <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="4" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>

            {/* Grid Connections (Faint lines) */}
            <g opacity="0.1">
               {/* Horizontal lines */}
               {currentGrid.map((row, y) => {
                 const start = getCoord(0, y);
                 const end = getCoord(cols - 1, y);
                 return <line key={`h-${y}`} x1={start.cx} y1={start.cy} x2={end.cx} y2={end.cy} stroke="white" strokeWidth="1" />;
               })}
               {/* Vertical lines */}
               {currentGrid[0].map((_, x) => {
                 const start = getCoord(x, 0);
                 const end = getCoord(x, rows - 1);
                 return <line key={`v-${x}`} x1={start.cx} y1={start.cy} x2={end.cx} y2={end.cy} stroke="white" strokeWidth="1" />;
               })}
            </g>

            {/* The Active Path */}
            {activePoints.length > 0 && (
              <path 
                d={pathData} 
                fill="none" 
                stroke={mode === 'algante' ? '#818cf8' : '#34d399'} 
                strokeWidth="4" 
                strokeLinecap="round" 
                strokeLinejoin="round"
                filter="url(#glow)"
                className="animate-[draw_1s_ease-out_forwards]"
              />
            )}

            {/* Nodes */}
            {currentGrid.map((row, y) => (
              row.map((char, x) => {
                const { cx, cy } = getCoord(x, y);
                const isActive = text.toUpperCase().includes(char);
                // Check if this specific instance is the one being used is hard due to duplicates, 
                // but we can highlight simply if the char is in the word.

                return (
                  <g key={`${x}-${y}`}>
                    <circle 
                      cx={cx} 
                      cy={cy} 
                      r={isActive ? 18 : 6} 
                      fill={isActive ? '#1e293b' : '#334155'}
                      stroke={isActive ? (mode === 'algante' ? '#818cf8' : '#34d399') : 'transparent'}
                      strokeWidth={2}
                      className="transition-all duration-300"
                    />
                    <text 
                      x={cx} 
                      y={cy} 
                      dy="0.35em" 
                      textAnchor="middle" 
                      fill={isActive ? 'white' : '#64748b'}
                      fontSize={isActive ? 16 : 10}
                      fontWeight="bold"
                      className="transition-all duration-300 select-none pointer-events-none"
                    >
                      {char}
                    </text>
                  </g>
                );
              })
            ))}
          </svg>
        </div>
      </div>
    </div>
  );
};

