import React, { useState, useMemo, useRef } from 'react';
import { Type, Activity, Spline, Cpu, Zap, Download, ZoomIn, ZoomOut, RefreshCw, Sliders } from 'lucide-react';

type GridMode = 'algante' | 'comun';
type StrokeStyle = 'linear' | 'smooth' | 'orthogonal' | 'chaos';

// Grid configurations
interface LetterPos { x: number; y: number; char: string }

const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Get all positions for a character (handles duplicates)
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) {
        map.set(char, []);
      }
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

const Taelim: React.FC = () => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [strokeStyle, setStrokeStyle] = useState<StrokeStyle>('linear');
  const [strokeWidth, setStrokeWidth] = useState(4);
  const [zoom, setZoom] = useState(1);
  const svgRef = useRef<SVGSVGElement>(null);

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  // Canvas Config
  const baseWidth = 800;
  const baseHeight = 600;
  const padding = 80;

  const cellWidth = (baseWidth - padding * 2) / (cols - 1);
  const cellHeight = (baseHeight - padding * 2) / (rows - 1);

  const getCoord = (x: number, y: number) => ({
    cx: padding + x * cellWidth,
    cy: padding + y * cellHeight
  });

  // Calculate Path Points with Nearest Neighbor Logic
  const activePoints = useMemo(() => {
    const chars = text.toUpperCase().replace(/[^A-Z]/g, '').split('');
    const points: {cx: number, cy: number, char: string}[] = [];

    let lastPos: {x: number, y: number} | null = null;

    chars.forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;

      let chosenPos = possiblePositions[0];

      // Logic: Find the instance of the letter closest to the previous letter
      // This creates a more natural "flow" or weaving motion.
      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) {
            minDist = dist;
            chosenPos = pos;
          }
        });
      }

      const coord = getCoord(chosenPos.x, chosenPos.y);

      // Add chaos/noise if mode is chaos
      if (strokeStyle === 'chaos') {
         const noise = () => (Math.random() - 0.5) * 15;
         coord.cx += noise();
         coord.cy += noise();
      }

      points.push({ ...coord, char });
      lastPos = chosenPos;
    });

    return points;
  }, [text, gridMap, strokeStyle]); // Re-calc if chaos changes to regenerate noise

  // Path Generators
  const generatePath = (points: {cx: number, cy: number}[]) => {
    if (points.length === 0) return '';
    if (points.length === 1) return `M ${points[0].cx} ${points[0].cy} L ${points[0].cx + 1} ${points[0].cy}`;

    let d = `M ${points[0].cx} ${points[0].cy}`;

    if (strokeStyle === 'linear' || strokeStyle === 'chaos') {
      for (let i = 1; i < points.length; i++) {
        d += ` L ${points[i].cx} ${points[i].cy}`;
      }
    } else if (strokeStyle === 'orthogonal') {
      for (let i = 1; i < points.length; i++) {
        const prev = points[i-1];
        const curr = points[i];
        // Mid-point orthogonal turn
        const midX = prev.cx + (curr.cx - prev.cx) / 2;
        d += ` L ${midX} ${prev.cy} L ${midX} ${curr.cy} L ${curr.cx} ${curr.cy}`;
      }
    } else if (strokeStyle === 'smooth') {
      // Catmull-Rom logic
      for (let i = 0; i < points.length - 1; i++) {
        const p0 = points[i === 0 ? 0 : i - 1];
        const p1 = points[i];
        const p2 = points[i + 1];
        const p3 = points[i + 2 < points.length ? i + 2 : i + 1];

        const cp1x = p1.cx + (p2.cx - p0.cx) / 6;
        const cp1y = p1.cy + (p2.cy - p0.cy) / 6;
        const cp2x = p2.cx - (p3.cx - p1.cx) / 6;
        const cp2y = p2.cy - (p3.cy - p1.cy) / 6;

        d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.cx} ${p2.cy}`;
      }
    }

    return d;
  };

  const pathData = generatePath(activePoints);

  // Handlers
  const handleDownload = () => {
    if (!svgRef.current) return;

    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    // Set explicit size for high res export
    canvas.width = baseWidth;
    canvas.height = baseHeight;

    img.onload = () => {
      if(ctx) {
        // Draw dark background
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = `Taelim_${text || 'Símbolo'}_${mode}.png`;
        downloadLink.href = pngFile;
        downloadLink.click();
      }
    };

    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const resetView = () => {
    setZoom(1);
    setText('');
  };

  return (
    <div className="max-w-7xl mx-auto p-6 animate-fade-in">
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 h-full">

        {/* --- CONTROLS PANEL --- */}
        <div className="xl:col-span-1 space-y-6">
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-xl">
            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-700">
              <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                <Type size={24} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Tael'im</h2>
                <p className="text-slate-400 text-xs uppercase tracking-widest">Panel de Control</p>
              </div>
            </div>

            <div className="space-y-6">
              {/* Input */}
              <div className="relative group">
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Radical</label>
                <input 
                  type="text" 
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  className="w-full bg-slate-900 border-2 border-slate-700 rounded-xl px-4 py-4 text-white focus:border-indigo-500 focus:shadow-[0_0_20px_rgba(99,102,241,0.3)] outline-none text-2xl font-bold tracking-[0.2em] uppercase transition-all placeholder:text-slate-700"
                  placeholder="PALABRA"
                />
                <div className="absolute right-4 top-[38px] text-slate-600">
                   {text.length}
                </div>
              </div>

              {/* Grid Selector */}
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Dialecto (Grid)</label>
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => setMode('algante')}
                    className={`py-3 px-4 rounded-xl border-2 font-medium transition-all ${mode === 'algante' ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300 shadow-inner' : 'bg-slate-900 border-slate-800 text-slate-500 hover:border-slate-600'}`}
                  >
                    Algante
                  </button>
                  <button 
                    onClick={() => setMode('comun')}
                    className={`py-3 px-4 rounded-xl border-2 font-medium transition-all ${mode === 'comun' ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300 shadow-inner' : 'bg-slate-900 border-slate-800 text-slate-500 hover:border-slate-600'}`}
                  >
                    Común
                  </button>
                </div>
              </div>

              {/* Stroke Style */}
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Estilo de Trazo</label>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { id: 'linear', icon: Activity, label: 'Recta' },
                    { id: 'smooth', icon: Spline, label: 'Fluida' },
                    { id: 'orthogonal', icon: Cpu, label: 'Circuit' },
                    { id: 'chaos', icon: Zap, label: 'Caos' }
                  ].map((s) => (
                    <button 
                      key={s.id}
                      onClick={() => setStrokeStyle(s.id as StrokeStyle)}
                      className={`flex items-center gap-2 py-2 px-3 rounded-lg border text-sm transition-all
                        ${strokeStyle === s.id 
                          ? 'bg-slate-700 border-white text-white' 
                          : 'bg-slate-900 border-slate-800 text-slate-400 hover:bg-slate-800'}
                      `}
                    >
                      <s.icon size={14} />
                      {s.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Stroke Width Slider */}
              <div>
                <div className="flex justify-between mb-2">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-wider">Grosor</label>
                  <span className="text-xs text-slate-400">{strokeWidth}px</span>
                </div>
                <div className="flex items-center gap-3">
                  <Sliders size={16} className="text-slate-600" />
                  <input 
                    type="range" 
                    min="1" 
                    max="12" 
                    value={strokeWidth} 
                    onChange={(e) => setStrokeWidth(Number(e.target.value))}
                    className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                  />
                </div>
              </div>

            </div>
          </div>

          {/* Stats Box */}
          <div className="bg-slate-900/50 p-6 rounded-2xl border border-slate-800">
             <h4 className="text-xs font-bold text-slate-500 uppercase tracking-wider mb-4">Datos del Glifo</h4>
             <div className="space-y-2">
               <div className="flex justify-between text-sm">
                 <span className="text-slate-400">Nodos activos</span>
                 <span className="text-white font-mono">{activePoints.length}</span>
               </div>
               <div className="flex justify-between text-sm">
                 <span className="text-slate-400">Distancia est.</span>
                 <span className="text-white font-mono">
                    {activePoints.length > 1 ? (activePoints.length * 1.5).toFixed(1) + 'u' : '0u'}
                 </span>
               </div>
             </div>
          </div>
        </div>

        {/* --- VISUALIZATION CANVAS --- */}
        <div className="xl:col-span-3 h-[600px] bg-slate-950 rounded-2xl border border-slate-800 shadow-2xl relative overflow-hidden group">

          {/* Toolbar Overlay */}
          <div className="absolute top-4 right-4 flex gap-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 hover:text-white border border-slate-700" title="Alejar">
                <ZoomOut size={20} />
             </button>
             <button onClick={() => setZoom(z => Math.min(2.5, z + 0.1))} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 hover:text-white border border-slate-700" title="Acercar">
                <ZoomIn size={20} />
             </button>
             <button onClick={resetView} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 hover:text-white border border-slate-700" title="Resetear">
                <RefreshCw size={20} />
             </button>
             <div className="w-px h-8 bg-slate-700 mx-1"></div>
             <button onClick={handleDownload} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 shadow-lg shadow-indigo-900/50 flex items-center gap-2 px-3 font-medium transition-all" title="Descargar PNG">
                <Download size={20} />
                <span>Exportar</span>
             </button>
          </div>

          {/* Background Gradient */}
          <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-950/30 via-slate-950 to-slate-950 pointer-events-none"></div>

          {/* Scroll/Pan Container */}
          <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar">
            <div 
              style={{ 
                transform: `scale(${zoom})`, 
                transformOrigin: 'center center',
                transition: 'transform 0.2s ease-out'
              }}
              className="p-10"
            >
              <svg 
                ref={svgRef}
                width={baseWidth} 
                height={baseHeight} 
                viewBox={`0 0 ${baseWidth} ${baseHeight}`} 
                className="overflow-visible"
              >
                <defs>
                  {/* Enhanced Glow Filters */}
                  <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation="3.5" result="coloredBlur" />
                    <feMerge>
                      <feMergeNode in="coloredBlur" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                  <filter id="intense-glow" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation="8" result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                  </filter>
                </defs>

                {/* --- GRID LAYER --- */}
                <g className="transition-opacity duration-500">
                  {currentGrid.map((row, y) => (
                    row.map((char, x) => {
                      const { cx, cy } = getCoord(x, y);
                      const isActive = activePoints.some(p => p.char === char);
                      const isStart = activePoints.length > 0 && activePoints[0].char === char && activePoints[0].cx === cx && activePoints[0].cy === cy;
                      const isEnd = activePoints.length > 0 && activePoints[activePoints.length - 1].char === char && activePoints[activePoints.length - 1].cx === cx && activePoints[activePoints.length - 1].cy === cy;

                      return (
                        <g key={`${x}-${y}-${char}`}>
                          {/* Connection Lines (Faint Grid) */}
                          {x < cols - 1 && (
                            <line 
                              x1={cx} y1={cy} 
                              x2={getCoord(x + 1, y).cx} y2={getCoord(x + 1, y).cy} 
                              stroke="#334155" strokeWidth="1" opacity="0.2" 
                            />
                          )}
                          {y < rows - 1 && (
                            <line 
                              x1={cx} y1={cy} 
                              x2={getCoord(x, y + 1).cx} y2={getCoord(x, y + 1).cy} 
                              stroke="#334155" strokeWidth="1" opacity="0.2" 
                            />
                          )}

                          {/* Node Circle */}
                          <circle 
                            cx={cx} 
                            cy={cy} 
                            r={isActive ? 24 : 4} 
                            fill={isActive ? '#1e293b' : '#334155'}
                            stroke={isActive ? (mode === 'algante' ? '#818cf8' : '#34d399') : 'transparent'}
                            strokeWidth={isActive ? 2 : 0}
                            className="transition-all duration-300"
                            opacity={isActive ? 1 : 0.5}
                          />

                          {/* Start/End Indicators */}
                          {isStart && <circle cx={cx} cy={cy} r={32} stroke="white" strokeWidth="1" fill="none" opacity="0.3" strokeDasharray="4 4" />}
                          {isEnd && <circle cx={cx} cy={cy} r={32} stroke="white" strokeWidth="2" fill="none" opacity="0.5" />}

                          {/* Character Text */}
                          <text 
                            x={cx} 
                            y={cy} 
                            dy="0.35em" 
                            textAnchor="middle" 
                            fill={isActive ? 'white' : '#475569'}
                            fontSize={isActive ? 20 : 12}
                            fontWeight={isActive ? 'bold' : 'normal'}
                            className="transition-all duration-300 select-none pointer-events-none"
                            style={{ textShadow: isActive ? '0 0 10px rgba(255,255,255,0.5)' : 'none' }}
                          >
                            {char}
                          </text>
                        </g>
                      );
                    })
                  ))}
                </g>

                {/* --- PATH LAYER --- */}
                {activePoints.length > 0 && (
                  <>
                    {/* Outer Glow Stroke */}
                    <path 
                      d={pathData} 
                      fill="none" 
                      stroke={mode === 'algante' ? '#6366f1' : '#10b981'} 
                      strokeWidth={strokeWidth * 3} 
                      strokeLinecap="round" 
                      strokeLinejoin="round"
                      opacity="0.2"
                      filter="url(#intense-glow)"
                    />
                    {/* Main Core Stroke */}
                    <path 
                      d={pathData} 
                      fill="none" 
                      stroke={mode === 'algante' ? '#a5b4fc' : '#6ee7b7'} 
                      strokeWidth={strokeWidth} 
                      strokeLinecap="round" 
                      strokeLinejoin="round"
                      filter="url(#neon-glow)"
                      className="animate-[draw_1.5s_ease-out_forwards]"
                      strokeDasharray={strokeStyle === 'orthogonal' ? 'none' : 'none'} // Reset dash if needed
                    />
                  </>
                )}
              </svg>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

