import React, { useState, useMemo, useRef } from 'react';
import { Type, Activity, Spline, Layers, PenTool, Download, ZoomIn, ZoomOut, RefreshCw, Sliders, Dice5, Sun } from 'lucide-react';
import { Term } from '../types';

type GridMode = 'algante' | 'comun';
type StrokeStyle = 'linear' | 'smooth' | 'double' | 'sketch';

interface Props {
  terms?: Term[];
}

// Grid configurations
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Get all positions for a character (handles duplicates)
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) {
        map.set(char, []);
      }
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

const Taelim: React.FC<Props> = ({ terms = [] }) => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [strokeStyle, setStrokeStyle] = useState<StrokeStyle>('smooth');

  // Visual Parameters
  const [strokeWidth, setStrokeWidth] = useState(3);
  const [tension, setTension] = useState(6); // For Smooth curves (higher = straighter, lower = loopier)
  const [offset, setOffset] = useState(6); // For Double/Sketch
  const [glowIntensity, setGlowIntensity] = useState(8); 
  const [zoom, setZoom] = useState(1);

  const svgRef = useRef<SVGSVGElement>(null);

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  // Canvas Config
  const baseWidth = 800;
  const baseHeight = 600;
  const padding = 100;

  const cellWidth = (baseWidth - padding * 2) / (cols - 1);
  const cellHeight = (baseHeight - padding * 2) / (rows - 1);

  const getCoord = (x: number, y: number) => ({
    cx: padding + x * cellWidth,
    cy: padding + y * cellHeight
  });

  // Calculate Path Points with Nearest Neighbor Logic
  const activePoints = useMemo(() => {
    const chars = text.toUpperCase().replace(/[^A-Z]/g, '').split('');
    const points: {cx: number, cy: number, char: string}[] = [];

    let lastPos: {x: number, y: number} | null = null;

    chars.forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;

      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) {
            minDist = dist;
            chosenPos = pos;
          }
        });
      }

      points.push({ ...getCoord(chosenPos.x, chosenPos.y), char });
      lastPos = chosenPos;
    });

    return points;
  }, [text, gridMap]); 

  // Path Generators
  const generatePath = (points: {cx: number, cy: number}[], xOffset = 0, yOffset = 0) => {
    if (points.length === 0) return '';
    const pts = points.map(p => ({ cx: p.cx + xOffset, cy: p.cy + yOffset }));

    if (pts.length === 1) return `M ${pts[0].cx} ${pts[0].cy} L ${pts[0].cx + 1} ${pts[0].cy}`;

    let d = `M ${pts[0].cx} ${pts[0].cy}`;

    if (strokeStyle === 'linear') {
      for (let i = 1; i < pts.length; i++) {
        d += ` L ${pts[i].cx} ${pts[i].cy}`;
      }
    } else if (strokeStyle === 'smooth' || strokeStyle === 'double' || strokeStyle === 'sketch') {
      // Catmull-Rom with variable tension
      // Tension divisor: 6 is standard. Lower (e.g. 3) is very round. Higher (e.g. 12) is tight.
      const t = tension; 

      for (let i = 0; i < pts.length - 1; i++) {
        const p0 = pts[i === 0 ? 0 : i - 1];
        const p1 = pts[i];
        const p2 = pts[i + 1];
        const p3 = pts[i + 2 < pts.length ? i + 2 : i + 1];

        const cp1x = p1.cx + (p2.cx - p0.cx) / t;
        const cp1y = p1.cy + (p2.cy - p0.cy) / t;
        const cp2x = p2.cx - (p3.cx - p1.cx) / t;
        const cp2y = p2.cy - (p3.cy - p1.cy) / t;

        d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.cx} ${p2.cy}`;
      }
    }

    return d;
  };

  // Handlers
  const handleRandomWord = () => {
    if (terms.length > 0) {
      const randomTerm = terms[Math.floor(Math.random() * terms.length)];
      setText(randomTerm.root);
    }
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();
    canvas.width = baseWidth;
    canvas.height = baseHeight;

    img.onload = () => {
      if(ctx) {
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0);
        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = `Taelim_${text || 'Símbolo'}_${strokeStyle}.png`;
        downloadLink.href = pngFile;
        downloadLink.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const resetView = () => {
    setZoom(1);
    setText('');
  };

  return (
    <div className="max-w-7xl mx-auto p-6 animate-fade-in">
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 h-full">

        {/* --- CONTROLS PANEL --- */}
        <div className="xl:col-span-1 space-y-6">
          <div className="bg-slate-800 p-6 rounded-2xl border border-slate-700 shadow-xl">
            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-700">
              <div className="p-2 bg-indigo-500/20 rounded-lg text-indigo-400">
                <Type size={24} />
              </div>
              <div>
                <h2 className="text-xl font-bold text-white">Tael'im</h2>
                <p className="text-slate-400 text-xs uppercase tracking-widest">Panel de Control</p>
              </div>
            </div>

            <div className="space-y-6">
              {/* Input */}
              <div className="relative group">
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Radical</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    className="w-full bg-slate-900 border-2 border-slate-700 rounded-xl px-4 py-3 text-white focus:border-indigo-500 outline-none text-xl font-bold tracking-[0.2em] uppercase"
                    placeholder="PALABRA"
                  />
                  <button 
                    onClick={handleRandomWord}
                    className="p-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl transition-colors"
                    title="Palabra Aleatoria"
                  >
                    <Dice5 size={24} />
                  </button>
                </div>
              </div>

              {/* Stroke Style */}
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Estilo de Caligrafía</label>
                <div className="grid grid-cols-2 gap-2">
                  {[
                    { id: 'linear', icon: Activity, label: 'Recta' },
                    { id: 'smooth', icon: Spline, label: 'Curva' },
                    { id: 'double', icon: Layers, label: 'Doble' },
                    { id: 'sketch', icon: PenTool, label: 'Boceto' }
                  ].map((s) => (
                    <button 
                      key={s.id}
                      onClick={() => setStrokeStyle(s.id as StrokeStyle)}
                      className={`flex items-center gap-2 py-2 px-3 rounded-lg border text-sm transition-all
                        ${strokeStyle === s.id 
                          ? 'bg-slate-700 border-white text-white shadow-lg' 
                          : 'bg-slate-900 border-slate-800 text-slate-400 hover:bg-slate-800'}
                      `}
                    >
                      <s.icon size={14} />
                      {s.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Dynamic Sliders */}
              <div className="bg-slate-900/50 p-4 rounded-xl border border-slate-700/50 space-y-4">

                {/* Global: Stroke Width */}
                <div>
                  <div className="flex justify-between mb-1">
                     <span className="text-xs text-slate-400">Grosor</span>
                     <span className="text-xs text-white">{strokeWidth}px</span>
                  </div>
                  <input type="range" min="1" max="10" value={strokeWidth} onChange={(e) => setStrokeWidth(Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
                </div>

                {/* Global: Glow */}
                <div>
                  <div className="flex justify-between mb-1">
                     <span className="text-xs text-slate-400">Resplandor (Glow)</span>
                     <span className="text-xs text-white">{(glowIntensity/2).toFixed(1)}</span>
                  </div>
                  <input type="range" min="0" max="20" value={glowIntensity} onChange={(e) => setGlowIntensity(Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
                </div>

                {/* Conditional: Tension (Smooth) */}
                {['smooth', 'double', 'sketch'].includes(strokeStyle) && (
                  <div>
                    <div className="flex justify-between mb-1">
                       <span className="text-xs text-slate-400">Tensión Curva</span>
                       <span className="text-xs text-white">{tension}</span>
                    </div>
                    <input type="range" min="2" max="15" step="0.5" value={tension} onChange={(e) => setTension(Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                  </div>
                )}

                {/* Conditional: Offset (Double/Sketch) */}
                {['double', 'sketch'].includes(strokeStyle) && (
                   <div>
                   <div className="flex justify-between mb-1">
                      <span className="text-xs text-slate-400">{strokeStyle === 'double' ? 'Separación' : 'Dispersión'}</span>
                      <span className="text-xs text-white">{offset}px</span>
                   </div>
                   <input type="range" min="1" max="20" value={offset} onChange={(e) => setOffset(Number(e.target.value))} className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-emerald-500" />
                 </div>
                )}

              </div>

              {/* Grid Selector */}
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase mb-2 block tracking-wider">Dialecto</label>
                <div className="grid grid-cols-2 gap-3">
                  <button onClick={() => setMode('algante')} className={`py-2 px-4 rounded-lg border text-sm transition-all ${mode === 'algante' ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300' : 'bg-slate-900 border-slate-800 text-slate-500'}`}>Algante</button>
                  <button onClick={() => setMode('comun')} className={`py-2 px-4 rounded-lg border text-sm transition-all ${mode === 'comun' ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300' : 'bg-slate-900 border-slate-800 text-slate-500'}`}>Común</button>
                </div>
              </div>

            </div>
          </div>
        </div>

        {/* --- VISUALIZATION CANVAS --- */}
        <div className="xl:col-span-3 h-[600px] bg-slate-950 rounded-2xl border border-slate-800 shadow-2xl relative overflow-hidden group">

          {/* Toolbar */}
          <div className="absolute top-4 right-4 flex gap-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 border border-slate-700"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.5, z + 0.1))} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 border border-slate-700"><ZoomIn size={18} /></button>
             <button onClick={resetView} className="p-2 bg-slate-800 text-slate-300 rounded-lg hover:bg-slate-700 border border-slate-700"><RefreshCw size={18} /></button>
             <div className="w-px h-8 bg-slate-700 mx-1"></div>
             <button onClick={handleDownload} className="p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 shadow-lg flex items-center gap-2 px-3 text-sm font-medium"><Download size={18} /> Exportar</button>
          </div>

          <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,_var(--tw-gradient-stops))] from-indigo-950/30 via-slate-950 to-slate-950 pointer-events-none"></div>

          <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar">
            <div style={{ transform: `scale(${zoom})`, transformOrigin: 'center center', transition: 'transform 0.2s ease-out' }} className="p-10">
              <svg ref={svgRef} width={baseWidth} height={baseHeight} viewBox={`0 0 ${baseWidth} ${baseHeight}`} className="overflow-visible">
                <defs>
                  <filter id="glow-filter" x="-50%" y="-50%" width="200%" height="200%">
                    <feGaussianBlur stdDeviation={glowIntensity} result="blur" />
                    <feComposite in="SourceGraphic" in2="blur" operator="over" />
                  </filter>
                </defs>

                {/* --- GRID LAYER --- */}
                <g className="transition-opacity duration-500">
                  {currentGrid.map((row, y) => (
                    row.map((char, x) => {
                      const { cx, cy } = getCoord(x, y);
                      const isActive = activePoints.some(p => p.char === char);
                      const isStart = activePoints.length > 0 && activePoints[0].char === char && activePoints[0].cx === cx && activePoints[0].cy === cy;
                      const isEnd = activePoints.length > 0 && activePoints[activePoints.length - 1].char === char && activePoints[activePoints.length - 1].cx === cx && activePoints[activePoints.length - 1].cy === cy;

                      return (
                        <g key={`${x}-${y}-${char}`}>
                          {/* Faint Grid Lines */}
                          {(x < cols - 1) && <line x1={cx} y1={cy} x2={getCoord(x + 1, y).cx} y2={getCoord(x + 1, y).cy} stroke="#334155" strokeWidth="1" opacity="0.15" />}
                          {(y < rows - 1) && <line x1={cx} y1={cy} x2={getCoord(x, y + 1).cx} y2={getCoord(x, y + 1).cy} stroke="#334155" strokeWidth="1" opacity="0.15" />}

                          {/* Node */}
                          <circle cx={cx} cy={cy} r={isActive ? 22 : 3} fill={isActive ? '#1e293b' : '#334155'} stroke={isActive ? (mode === 'algante' ? '#818cf8' : '#34d399') : 'transparent'} strokeWidth={isActive ? 2 : 0} className="transition-all duration-300" opacity={isActive ? 1 : 0.4} />

                          {/* Markers */}
                          {isStart && <circle cx={cx} cy={cy} r={30} stroke="white" strokeWidth="1" fill="none" opacity="0.4" strokeDasharray="3 3" />}
                          {isEnd && <circle cx={cx} cy={cy} r={30} stroke="white" strokeWidth="2" fill="none" opacity="0.6" />}

                          <text x={cx} y={cy} dy="0.35em" textAnchor="middle" fill={isActive ? 'white' : '#475569'} fontSize={isActive ? 18 : 10} fontWeight={isActive ? 'bold' : 'normal'} className="transition-all duration-300 select-none pointer-events-none" style={{ textShadow: isActive ? '0 0 10px rgba(255,255,255,0.5)' : 'none' }}>
                            {char}
                          </text>
                        </g>
                      );
                    })
                  ))}
                </g>

                {/* --- PATH LAYER --- */}
                {activePoints.length > 0 && (
                  <g filter="url(#glow-filter)">
                    {strokeStyle === 'double' ? (
                       <>
                         <path d={generatePath(activePoints, -offset/2, -offset/2)} fill="none" stroke={mode === 'algante' ? '#818cf8' : '#34d399'} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" opacity="0.9" />
                         <path d={generatePath(activePoints, offset/2, offset/2)} fill="none" stroke={mode === 'algante' ? '#818cf8' : '#34d399'} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" opacity="0.9" />
                       </>
                    ) : strokeStyle === 'sketch' ? (
                        <>
                          <path d={generatePath(activePoints, -offset, -offset)} fill="none" stroke={mode === 'algante' ? '#818cf8' : '#34d399'} strokeWidth={1} strokeLinecap="round" opacity="0.4" />
                          <path d={generatePath(activePoints, offset, offset/2)} fill="none" stroke={mode === 'algante' ? '#818cf8' : '#34d399'} strokeWidth={1} strokeLinecap="round" opacity="0.4" />
                          <path d={generatePath(activePoints, 0, 0)} fill="none" stroke={mode === 'algante' ? '#a5b4fc' : '#6ee7b7'} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />
                        </>
                    ) : (
                        // Linear & Smooth (Single line)
                        <path d={generatePath(activePoints)} fill="none" stroke={mode === 'algante' ? '#a5b4fc' : '#6ee7b7'} strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />
                    )}
                  </g>
                )}
              </svg>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Taelim;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Type, Activity, Spline, PenTool, Download, ZoomIn, ZoomOut, RefreshCw, Dice5, Hexagon, Zap, Feather } from 'lucide-react';
import { Term } from '../types';

type GridMode = 'algante' | 'comun';
type RenderEngine = 'plasma' | 'tech' | 'pluma' | 'nexo';

interface Props {
  terms?: Term[];
}

// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [] }) => {
  // Estado Principal
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);

  // Parámetros de Caligrafía
  const [strokeWidth, setStrokeWidth] = useState(4);
  const [paramA, setParamA] = useState(50); // Genérico A (ej: Tensión / Ángulo)
  const [paramB, setParamB] = useState(20); // Genérico B (ej: Wobble / Offset)
  const [glow, setGlow] = useState(6);

  const svgRef = useRef<SVGSVGElement>(null);

  // --- LÓGICA DEL GRID (PROPORCIÓN 1:1) ---
  const CELL_SIZE = 100; // Tamaño fijo del cuadrado en unidades SVG
  const PADDING = 80;

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  // El viewBox se adapta al contenido para mantener cuadrados perfectos
  const viewWidth = (cols - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (rows - 1) * CELL_SIZE + (PADDING * 2);

  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // Reset params al cambiar de motor
  useEffect(() => {
    if (engine === 'plasma') { setParamA(50); setParamB(0); } // Tension, Wobble
    if (engine === 'tech') { setParamA(0); setParamB(0); }   // Chamfer, Dash
    if (engine === 'pluma') { setParamA(45); setParamB(20); } // Angle, Width
    if (engine === 'nexo') { setParamA(30); setParamB(50); } // Spread, Jitter
  }, [engine]);

  // --- CÁLCULO DE PUNTOS (Vecino más cercano) ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const chars = cleanText.split('');
    const points: {x: number, y: number, char: string}[] = [];

    let lastPos: {x: number, y: number} | null = null;

    chars.forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;

      let chosenPos = possiblePositions[0];

      // Buscar la instancia más cercana a la letra anterior
      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          // Distancia Euclídea
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) {
            minDist = dist;
            chosenPos = pos;
          }
        });
      }

      // Convertir a coordenadas SVG absolutas
      points.push({ 
        x: PADDING + chosenPos.x * CELL_SIZE, 
        y: PADDING + chosenPos.y * CELL_SIZE, 
        char 
      });
      lastPos = chosenPos;
    });

    return points;
  }, [text, gridMap, PADDING, CELL_SIZE]); 


  // --- MOTORES DE RENDERIZADO (PATH GENERATORS) ---

  const generatePath = () => {
    if (activePoints.length < 2) return null;

    // 1. MOTOR PLASMA (Curvas Bézier con Ondulación)
    if (engine === 'plasma') {
      const tension = 1 + (paramA / 10); // 1 (suave) a 11 (recto)
      const wobble = paramB / 2; // Amplitud de ruido

      let d = `M ${activePoints[0].x} ${activePoints[0].y}`;

      for (let i = 0; i < activePoints.length - 1; i++) {
        const p0 = activePoints[i === 0 ? 0 : i - 1];
        const p1 = activePoints[i];
        const p2 = activePoints[i + 1];
        const p3 = activePoints[i + 2 < activePoints.length ? i + 2 : i + 1];

        // Catmull-Rom controls
        let cp1x = p1.x + (p2.x - p0.x) / tension;
        let cp1y = p1.y + (p2.y - p0.y) / tension;
        let cp2x = p2.x - (p3.x - p1.x) / tension;
        let cp2y = p2.y - (p3.y - p1.y) / tension;

        // Añadir "Wobble" (ruido determinista basado en índice)
        if (wobble > 0) {
           cp1x += Math.sin(i * 3) * wobble;
           cp1y += Math.cos(i * 3) * wobble;
           cp2x += Math.cos(i * 5) * wobble;
           cp2y += Math.sin(i * 5) * wobble;
        }

        d += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p2.x} ${p2.y}`;
      }
      return <path d={d} fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />;
    }

    // 2. MOTOR TECH (Rectas con Chaflán)
    if (engine === 'tech') {
      const chamfer = paramA; // Radio del chaflán
      const dashed = paramB > 50; 

      let d = `M ${activePoints[0].x} ${activePoints[0].y}`;

      // Lógica simple para líneas rectas, el chamfer se haría mejor con ArcTo pero L es más robusto para SVG simple
      // Simulamos "Tech" dibujando líneas directas pero añadiendo decoraciones en los nodos
      activePoints.slice(1).forEach(p => {
        d += ` L ${p.x} ${p.y}`;
      });

      return (
        <>
          <path 
            d={d} 
            fill="none" 
            stroke="currentColor" 
            strokeWidth={strokeWidth} 
            strokeLinecap="square" 
            strokeLinejoin={chamfer > 20 ? 'round' : 'miter'}
            strokeDasharray={dashed ? `${strokeWidth * 2} ${strokeWidth * 3}` : 'none'}
            opacity={0.8}
          />
          {/* Nodos Tech Decorativos */}
          {activePoints.map((p, i) => (
             <rect 
               key={i} 
               x={p.x - (strokeWidth + chamfer/5)/2} 
               y={p.y - (strokeWidth + chamfer/5)/2} 
               width={strokeWidth + chamfer/5} 
               height={strokeWidth + chamfer/5} 
               fill="currentColor" 
             />
          ))}
        </>
      );
    }

    // 3. MOTOR PLUMA (Caligrafía de plumilla plana)
    if (engine === 'pluma') {
      const angleRad = (paramA * Math.PI) / 180;
      const width = Math.max(2, paramB); // Ancho de la plumilla
      const layers = 6; // Cantidad de líneas para simular el relleno

      const paths = [];
      // Dibujamos varias líneas paralelas offseteadas por el ángulo
      for (let i = 0; i < layers; i++) {
        const offset = (i / (layers - 1)) * width - (width / 2);
        const offsetX = Math.cos(angleRad) * offset;
        const offsetY = Math.sin(angleRad) * offset;

        let d = `M ${activePoints[0].x + offsetX} ${activePoints[0].y + offsetY}`;
        // Usamos una curva suave básica para la pluma
        for (let j = 0; j < activePoints.length - 1; j++) {
           const p1 = activePoints[j];
           const p2 = activePoints[j+1];
           // Bezier simple cuadrática para fluidez
           const mx = (p1.x + p2.x) / 2;
           const my = (p1.y + p2.y) / 2;
           d += ` Q ${p1.x + offsetX} ${p1.y + offsetY}, ${mx + offsetX} ${my + offsetY} T ${p2.x + offsetX} ${p2.y + offsetY}`;
        }

        paths.push(
          <path 
            key={i} 
            d={d} 
            fill="none" 
            stroke="currentColor" 
            strokeWidth={strokeWidth / 2} 
            opacity={0.7 + (i/layers)*0.3} // Gradiente de opacidad en la tinta
          />
        );
      }
      return <g>{paths}</g>;
    }

    // 4. MOTOR NEXO (Etéreo/Partículas)
    if (engine === 'nexo') {
      const spread = paramA / 2;
      const jitter = paramB > 50;

      let dMain = `M ${activePoints[0].x} ${activePoints[0].y}`;
      activePoints.slice(1).forEach(p => dMain += ` L ${p.x} ${p.y}`);

      return (
        <g>
          {/* Núcleo */}
          <path d={dMain} fill="none" stroke="currentColor" strokeWidth={2} opacity="0.5" />

          {/* Ecos Orbitales */}
          {[1, -1].map((dir, idx) => {
             let dEcho = `M ${activePoints[0].x} ${activePoints[0].y}`;
             activePoints.slice(1).forEach((p, i) => {
               // Offset perpendicular simple o ruido
               const noiseX = jitter ? (Math.random() - 0.5) * spread : 0;
               const noiseY = jitter ? (Math.random() - 0.5) * spread : 0;
               const offX = dir * spread + noiseX;
               const offY = dir * spread + noiseY;
               dEcho += ` L ${p.x + offX} ${p.y + offY}`;
             });
             return <path key={idx} d={dEcho} fill="none" stroke="currentColor" strokeWidth={1} opacity="0.6" strokeDasharray="4 4" />;
          })}

          {/* Nodos brillantes */}
          {activePoints.map((p, i) => (
            <circle key={i} cx={p.x} cy={p.y} r={strokeWidth + 2} fill="white" opacity="0.9" />
          ))}
        </g>
      );
    }

    return null;
  };


  // --- HANDLERS ---
  const handleRandomWord = () => {
    if (terms.length > 0) {
      const randomTerm = terms[Math.floor(Math.random() * terms.length)];
      setText(randomTerm.root);
    }
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    // Alto render para descarga
    canvas.width = viewWidth * 2;
    canvas.height = viewHeight * 2;

    img.onload = () => {
      if(ctx) {
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = `Taelim_${text || 'Simbolo'}_${engine}.png`;
        downloadLink.href = pngFile;
        downloadLink.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const getEngineIcon = (e: RenderEngine) => {
    switch(e) {
      case 'plasma': return <Activity size={16} />;
      case 'tech': return <Hexagon size={16} />;
