              {/* El SVG escala manteniendo el aspecto gracias al viewBox dinámico */}
              <div 
                style={{ 
                  width: viewWidth, 
                  height: viewHeight,
                  transform: `scale(${zoom})`, 
                  transition: 'transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94)',
                  maxWidth: '100%',
                  maxHeight: '100%'
                }}
              >
                <svg 
                  ref={svgRef} 
                  viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
                  className="w-full h-full drop-shadow-2xl overflow-visible"
                >
                  <defs>
                    {/* Filtros de Neón mejorados */}
                    <filter id="neon-strong" x="-100%" y="-100%" width="300%" height="300%">
                      <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                      <feMerge>
                        <feMergeNode in="coloredBlur" />
                        <feMergeNode in="coloredBlur" />
                        <feMergeNode in="SourceGraphic" />
                      </feMerge>
                    </filter>
                  </defs>

                  {/* --- CAPA GRID (Retícula) --- */}
                  <g className="opacity-20 pointer-events-none">
                    {/* Dibujamos cuadrados perfectos */}
                    {currentGrid.map((row, y) => (
                      row.map((char, x) => {
                        const px = PADDING + x * CELL_SIZE;
                        const py = PADDING + y * CELL_SIZE;

                        return (
                          <g key={`${x}-${y}`}>
                            {/* Puntos de la retícula */}
                            <circle cx={px} cy={py} r={2} fill="#94a3b8" />
                            {/* Letras tenues */}
                            <text 
                              x={px} y={py + CELL_SIZE/2 - 10} 
                              textAnchor="middle" 
                              fill="#475569" 
                              fontSize="10" 
                              fontFamily="monospace"
                              opacity={0.5}
                            >
                              {char}
                            </text>
                          </g>
                        );
                      })
                    ))}
                  </g>

                  {/* --- CAPA NODOS ACTIVOS --- */}
                  {activePoints.map((p, i) => (
                    <g key={i}>
                       {/* Halo del nodo */}
                       <circle cx={p.x} cy={p.y} r={24} fill={mode === 'algante' ? '#6366f1' : '#10b981'} fillOpacity="0.1" />
                       {/* Núcleo del nodo */}
                       <circle cx={p.x} cy={p.y} r={4} fill={mode === 'algante' ? '#a5b4fc' : '#6ee7b7'} />
                       {/* Letra Activa */}
                       <text 
                         x={p.x} y={p.y - 12} 
                         textAnchor="middle" 
                         fill="white" 
                         fontSize="14" 
                         fontWeight="bold"
                         style={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}
                       >
                         {p.char}
                       </text>
                       {/* Marcador de Inicio */}
                       {i === 0 && <circle cx={p.x} cy={p.y} r={32} stroke="white" strokeWidth={1} strokeDasharray="4 4" fill="none" opacity="0.5" />}
                       {/* Marcador de Fin */}
                       {i === activePoints.length - 1 && <circle cx={p.x} cy={p.y} r={32} stroke="white" strokeWidth={2} fill="none" opacity="0.8" />}
                    </g>
                  ))}

                  {/* --- CAPA TRAZADO PRINCIPAL --- */}
                  <g 
                    filter={glow > 0 ? "url(#neon-strong)" : ""} 
                    className={mode === 'algante' ? 'text-indigo-400' : 'text-emerald-400'}
                  >
                    {generatePath()}
                  </g>

                </svg>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default Taelim;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Type, Activity, Spline, PenTool, Download, ZoomIn, ZoomOut, RefreshCw, Dice5, Hexagon, Zap, Feather, Wand2, Palette } from 'lucide-react';
import { Term } from '../types';

type GridMode = 'algante' | 'comun';
type RenderEngine = 'plasma' | 'tech' | 'pluma' | 'nexo';

interface Props {
  terms?: Term[];
}

// --- PRESETS CONFIGURATION ---
const PRESETS = {
  cyberpunk: {
    mode: 'algante' as GridMode,
    engine: 'tech' as RenderEngine,
    startWidth: 2,
    endWidth: 2,
    paramA: 10, // Chamfer
    paramB: 80, // Dashed
    glow: 12
  },
  calligraphy: {
    mode: 'comun' as GridMode,
    engine: 'pluma' as RenderEngine,
    startWidth: 8,
    endWidth: 1,
    paramA: 45, // Angle
    paramB: 10, // Complexity
    glow: 2
  },
  magic: {
    mode: 'algante' as GridMode,
    engine: 'plasma' as RenderEngine,
    startWidth: 1,
    endWidth: 1, // Will be overridden by profile logic in render
    paramA: 60, // Tension
    paramB: 30, // Wobble
    glow: 15
  },
  ink: {
    mode: 'comun' as GridMode,
    engine: 'pluma' as RenderEngine,
    startWidth: 4,
    endWidth: 12,
    paramA: 30,
    paramB: 5,
    glow: 0
  }
};

// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY HELPERS (Splines & Variable Width) ---

// Catmull-Rom to Cubic Bezier conversion for a segment
// Returns interpolated points for a smoother path
const getSplinePoints = (points: {x: number, y: number}[], tension: number = 0.5, resolution: number = 10) => {
  if (points.length < 2) return points;

  const spline: {x: number, y: number}[] = [];

  // Helper to get point at index safely (clamping)
  const getPt = (i: number) => points[Math.max(0, Math.min(points.length - 1, i))];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = getPt(i - 1);
    const p1 = getPt(i);
    const p2 = getPt(i + 1);
    const p3 = getPt(i + 2);

    for (let t = 0; t < 1; t += 1/resolution) {
      const t2 = t * t;
      const t3 = t2 * t;

      const c1 = 2 * t2 - 3 * t3 + t3; // This logic needs to be simpler for inline.
      // Implementing simplified Catmull-Rom interpolation directly:

      const x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
      const y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);

      spline.push({ x, y });
    }
  }
  spline.push(points[points.length - 1]);
  return spline;
};

// Generate a polygon strip with variable width
const getVariableWidthPath = (points: {x: number, y: number}[], startW: number, endW: number) => {
  if (points.length < 2) return '';

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];

  points.forEach((p, i) => {
    // Calculate progress (0 to 1)
    const progress = i / (points.length - 1);
    // Interpolate width
    const currentHalfWidth = (startW + (endW - startW) * progress) / 2;

    // Calculate normal vector
    // For first point, look ahead. For last, look back. For middle, average.
    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }

    // Normalize and rotate 90 degrees
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;

    leftSide.push({ x: p.x + nx * currentHalfWidth, y: p.y + ny * currentHalfWidth });
    rightSide.push({ x: p.x - nx * currentHalfWidth, y: p.y - ny * currentHalfWidth });
  });

  // Construct path string: Move to start, line to all left, line to end, line to all right reversed, close.
  let d = `M ${leftSide[0].x} ${leftSide[0].y}`;
  for (let i = 1; i < leftSide.length; i++) d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  for (let i = rightSide.length - 1; i >= 0; i--) d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  d += ' Z';

  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [] }) => {
  // Estado Principal
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);

  // Parámetros de Caligrafía
  const [startWidth, setStartWidth] = useState(4);
  const [endWidth, setEndWidth] = useState(4);

  const [paramA, setParamA] = useState(50); 
  const [paramB, setParamB] = useState(20); 
  const [glow, setGlow] = useState(6);

  const svgRef = useRef<SVGSVGElement>(null);

  // --- LÓGICA DEL GRID (PROPORCIÓN 1:1) ---
  const CELL_SIZE = 100; // Tamaño fijo del cuadrado en unidades SVG
  const PADDING = 80;

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  const viewWidth = (cols - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (rows - 1) * CELL_SIZE + (PADDING * 2);

  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- PRESET HANDLER ---
  const applyPreset = (presetName: keyof typeof PRESETS) => {
    const p = PRESETS[presetName];
    setMode(p.mode);
    setEngine(p.engine);
    setStartWidth(p.startWidth);
    setEndWidth(p.endWidth);
    setParamA(p.paramA);
    setParamB(p.paramB);
    setGlow(p.glow);
  };

  const handleAutoWidth = () => {
    // Generates a random pleasing width profile
    const r1 = Math.floor(Math.random() * 12) + 1;
    const r2 = Math.floor(Math.random() * 12) + 1;
    setStartWidth(r1);
    setEndWidth(r2);
  };

  // --- CÁLCULO DE PUNTOS ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const chars = cleanText.split('');
    const points: {x: number, y: number, char: string}[] = [];

    let lastPos: {x: number, y: number} | null = null;

    chars.forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;

      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) {
            minDist = dist;
            chosenPos = pos;
          }
        });
      }

      points.push({ 
        x: PADDING + chosenPos.x * CELL_SIZE, 
        y: PADDING + chosenPos.y * CELL_SIZE, 
        char 
      });
      lastPos = chosenPos;
    });

    return points;
  }, [text, gridMap, PADDING, CELL_SIZE]); 


  // --- MOTOR DE RENDERIZADO PRINCIPAL ---
  const renderPath = () => {
    if (activePoints.length < 2) return null;

    const baseColor = mode === 'algante' ? 'currentColor' : 'currentColor';

    // 1. MOTOR PLASMA (Fluid Spline with Variable Width)
    if (engine === 'plasma') {
      const tension = paramA / 100; 
      // Subdivide points for smooth curve
      const splinePoints = getSplinePoints(activePoints, tension, 15);

      // Calculate variable width polygon
      // Special Logic: If Magic preset, we might want "bulge" in middle.
      // For now, we stick to linear interpolation between start/end sliders
      const pathData = getVariableWidthPath(splinePoints, startWidth, endWidth);

      return (
        <path d={pathData} fill={baseColor} opacity="0.8" />
      );
    }

    // 2. MOTOR TECH (Rectilinear with Variable Width segments)
    if (engine === 'tech') {
       // Tech doesn't curve, it goes straight.
       // We can still apply tapering to the segments.
       const pathData = getVariableWidthPath(activePoints, startWidth, endWidth);
       const chamfer = paramA;

       return (
         <g>
           <path d={pathData} fill={baseColor} opacity="0.6" />
           {/* Wireframe overlay */}
           <path 
             d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke={baseColor} 
             strokeWidth={1} 
             strokeOpacity="1"
             strokeDasharray={paramB > 50 ? "4 4" : "none"}
           />
           {/* Tech Nodes */}
           {activePoints.map((p, i) => (
             <rect 
               key={i}
               x={p.x - (startWidth + chamfer/5)/2} 
               y={p.y - (startWidth + chamfer/5)/2} 
               width={startWidth + chamfer/5} 
               height={startWidth + chamfer/5} 
               fill={baseColor}
             />
           ))}
         </g>
       );
    }

    // 3. MOTOR PLUMA (Advanced Calligraphy)
    if (engine === 'pluma') {
      // Use Spline for smoothness
      const splinePoints = getSplinePoints(activePoints, 0.5, 20);
      const pathData = getVariableWidthPath(splinePoints, startWidth, endWidth);

      return (
        <g>
          <path d={pathData} fill={baseColor} />
          {/* Inner highlight line for "ink" effect */}
          <path 
             d={`M ${splinePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke="white" 
             strokeWidth={Math.min(startWidth, endWidth) / 4} 
             strokeOpacity="0.3"
          />
        </g>
      );
    }

    // 4. MOTOR NEXO (Particle/Ethereal)
    if (engine === 'nexo') {
      // Nexo ignores variable width polygon and uses it for particle spread
      const splinePoints = getSplinePoints(activePoints, 0.5, 5);

      return (
        <g>
          {splinePoints.map((p, i) => {
             const progress = i / (splinePoints.length - 1);
