             )
          })}
          {/* Core line */}
           <path 
             d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke={baseColor} 
             strokeWidth={1} 
             opacity="0.5"
          />
        </g>
      );
