import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Type, Activity, Spline, PenTool, Download, ZoomIn, ZoomOut, RefreshCw, Dice5, Hexagon, Zap, Feather, Wand2, Palette, Eye, EyeOff, FileText } from 'lucide-react';
