    endWidth: 1,
    paramA: 45, // Angle
    paramB: 10, // Complexity
    glow: 2
  },
  magic: {
    mode: 'algante' as GridMode,
    engine: 'plasma' as RenderEngine,
    startWidth: 1,
    endWidth: 1, // Will be overridden by profile logic in render
    paramA: 60, // Tension
    paramB: 30, // Wobble
    glow: 15
  },
  ink: {
    mode: 'comun' as GridMode,
    engine: 'pluma' as RenderEngine,
    startWidth: 4,
    endWidth: 12,
    paramA: 30,
    paramB: 5,
    glow: 0
  }
};

// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY HELPERS (Splines & Variable Width) ---

// Catmull-Rom to Cubic Bezier conversion for a segment
// Returns interpolated points for a smoother path
const getSplinePoints = (points: {x: number, y: number}[], tension: number = 0.5, resolution: number = 10) => {
  if (points.length < 2) return points;

  const spline: {x: number, y: number}[] = [];

  // Helper to get point at index safely (clamping)
  const getPt = (i: number) => points[Math.max(0, Math.min(points.length - 1, i))];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = getPt(i - 1);
    const p1 = getPt(i);
    const p2 = getPt(i + 1);
    const p3 = getPt(i + 2);

    for (let t = 0; t < 1; t += 1/resolution) {
      const t2 = t * t;
      const t3 = t2 * t;

      const c1 = 2 * t2 - 3 * t3 + t3; // This logic needs to be simpler for inline.
      // Implementing simplified Catmull-Rom interpolation directly:

      const x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
      const y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);

      spline.push({ x, y });
    }
  }
  spline.push(points[points.length - 1]);
  return spline;
};

// Generate a polygon strip with variable width
const getVariableWidthPath = (points: {x: number, y: number}[], startW: number, endW: number) => {
  if (points.length < 2) return '';

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];

  points.forEach((p, i) => {
    // Calculate progress (0 to 1)
    const progress = i / (points.length - 1);
    // Interpolate width
    const currentHalfWidth = (startW + (endW - startW) * progress) / 2;

    // Calculate normal vector
    // For first point, look ahead. For last, look back. For middle, average.
    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }

    // Normalize and rotate 90 degrees
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    const nx = -dy / len;
    const ny = dx / len;

    leftSide.push({ x: p.x + nx * currentHalfWidth, y: p.y + ny * currentHalfWidth });
    rightSide.push({ x: p.x - nx * currentHalfWidth, y: p.y - ny * currentHalfWidth });
  });

  // Construct path string: Move to start, line to all left, line to end, line to all right reversed, close.
  let d = `M ${leftSide[0].x} ${leftSide[0].y}`;
  for (let i = 1; i < leftSide.length; i++) d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  for (let i = rightSide.length - 1; i >= 0; i--) d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  d += ' Z';

  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [] }) => {
  // Estado Principal
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);
  const [showGuides, setShowGuides] = useState(true);
  const [exportWithMetadata, setExportWithMetadata] = useState(false);

  // Parámetros de Caligrafía
  const [startWidth, setStartWidth] = useState(4);
  const [endWidth, setEndWidth] = useState(4);

  const [paramA, setParamA] = useState(50); 
  const [paramB, setParamB] = useState(20); 
  const [glow, setGlow] = useState(6);

  const svgRef = useRef<SVGSVGElement>(null);

  // --- LÓGICA DEL GRID (PROPORCIÓN 1:1) ---
  const CELL_SIZE = 100; // Tamaño fijo del cuadrado en unidades SVG
  const PADDING = 80;

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const rows = currentGrid.length;
  const cols = currentGrid[0].length;

  const viewWidth = (cols - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (rows - 1) * CELL_SIZE + (PADDING * 2);

  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- PRESET HANDLER ---
  const applyPreset = (presetName: keyof typeof PRESETS) => {
    const p = PRESETS[presetName];
    setMode(p.mode);
    setEngine(p.engine);
    setStartWidth(p.startWidth);
    setEndWidth(p.endWidth);
    setParamA(p.paramA);
    setParamB(p.paramB);
    setGlow(p.glow);
  };

  const handleAutoWidth = () => {
    // Generates a random pleasing width profile
    const r1 = Math.floor(Math.random() * 12) + 1;
    const r2 = Math.floor(Math.random() * 12) + 1;
    setStartWidth(r1);
    setEndWidth(r2);
  };

  // --- CÁLCULO DE PUNTOS ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const chars = cleanText.split('');
    const points: {x: number, y: number, char: string}[] = [];

    let lastPos: {x: number, y: number} | null = null;

    chars.forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;

      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) {
            minDist = dist;
            chosenPos = pos;
          }
        });
      }

      points.push({ 
        x: PADDING + chosenPos.x * CELL_SIZE, 
        y: PADDING + chosenPos.y * CELL_SIZE, 
        char 
      });
      lastPos = chosenPos;
    });

    return points;
  }, [text, gridMap, PADDING, CELL_SIZE]); 


  // --- MOTOR DE RENDERIZADO PRINCIPAL ---
  const renderPath = () => {
    if (activePoints.length < 2) return null;

    const baseColor = mode === 'algante' ? 'currentColor' : 'currentColor';

    // 1. MOTOR PLASMA (Fluid Spline with Variable Width)
    if (engine === 'plasma') {
      const tension = paramA / 100; 
      // Subdivide points for smooth curve
      const splinePoints = getSplinePoints(activePoints, tension, 15);

      // Calculate variable width polygon
      // Special Logic: If Magic preset, we might want "bulge" in middle.
      // For now, we stick to linear interpolation between start/end sliders
      const pathData = getVariableWidthPath(splinePoints, startWidth, endWidth);

      return (
        <path d={pathData} fill={baseColor} opacity="0.8" />
      );
    }

    // 2. MOTOR TECH (Rectilinear with Variable Width segments)
    if (engine === 'tech') {
       // Tech doesn't curve, it goes straight.
       // We can still apply tapering to the segments.
       const pathData = getVariableWidthPath(activePoints, startWidth, endWidth);
       const chamfer = paramA;

       return (
         <g>
           <path d={pathData} fill={baseColor} opacity="0.6" />
           {/* Wireframe overlay */}
           <path 
             d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke={baseColor} 
             strokeWidth={1} 
             strokeOpacity="1"
             strokeDasharray={paramB > 50 ? "4 4" : "none"}
           />
           {/* Tech Nodes */}
           {activePoints.map((p, i) => (
             <rect 
               key={i}
               x={p.x - (startWidth + chamfer/5)/2} 
               y={p.y - (startWidth + chamfer/5)/2} 
               width={startWidth + chamfer/5} 
               height={startWidth + chamfer/5} 
               fill={baseColor}
             />
           ))}
         </g>
       );
    }

    // 3. MOTOR PLUMA (Advanced Calligraphy)
    if (engine === 'pluma') {
      // Use Spline for smoothness
      const splinePoints = getSplinePoints(activePoints, 0.5, 20);
      const pathData = getVariableWidthPath(splinePoints, startWidth, endWidth);

      return (
        <g>
          <path d={pathData} fill={baseColor} />
          {/* Inner highlight line for "ink" effect */}
          <path 
             d={`M ${splinePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke="white" 
             strokeWidth={Math.min(startWidth, endWidth) / 4} 
             strokeOpacity="0.3"
          />
        </g>
      );
    }

    // 4. MOTOR NEXO (Particle/Ethereal)
    if (engine === 'nexo') {
      // Nexo ignores variable width polygon and uses it for particle spread
      const splinePoints = getSplinePoints(activePoints, 0.5, 5);

      return (
        <g>
          {splinePoints.map((p, i) => {
             const progress = i / (splinePoints.length - 1);
             const currentSize = startWidth + (endWidth - startWidth) * progress;
             if (i % 2 !== 0) return null; // Skip some for stippled look

             return (
               <circle 
                  key={i} 
                  cx={p.x} 
                  cy={p.y} 
                  r={currentSize / 2} 
                  fill={baseColor} 
                  opacity={0.4 + (Math.random() * 0.4)} 
               />
             )
          })}
          {/* Core line */}
           <path 
             d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`} 
             fill="none" 
             stroke={baseColor} 
             strokeWidth={1} 
             opacity="0.5"
          />
        </g>
      );
    }

    return null;
  };


  // --- HANDLERS ---
  const handleRandomWord = () => {
    if (terms.length > 0) {
      const randomTerm = terms[Math.floor(Math.random() * terms.length)];
      setText(randomTerm.root);
    }
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    // Configuración base de exportación
    const scaleFactor = 2; // Alta resolución
    const paddingBottom = exportWithMetadata ? 300 : 0;

    canvas.width = viewWidth * scaleFactor;
    canvas.height = (viewHeight * scaleFactor) + paddingBottom;

    img.onload = () => {
      if(ctx) {
        // 1. Fondo
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Dibujar SVG (Centrado)
        ctx.drawImage(img, 0, 0, viewWidth * scaleFactor, viewHeight * scaleFactor);

        // 3. Dibujar Metadatos (Si está activo)
        if (exportWithMetadata) {
          const currentTerm = terms.find(t => t.root.toLowerCase() === text.toLowerCase());
          const displayRoot = currentTerm ? currentTerm.root : text;
          const displayMeaning = currentTerm ? currentTerm.meaning : "Trazo Libre";
          const displayDesc = currentTerm ? currentTerm.description : "";

          const startY = (viewHeight * scaleFactor) + 60;
          const centerX = canvas.width / 2;

          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffffff';

          // Título (Raíz)
          ctx.font = "bold 80px 'Space Grotesk', sans-serif";
          ctx.fillText(displayRoot.toUpperCase(), centerX, startY);

          // Subtítulo (Significado)
          ctx.fillStyle = '#818cf8'; // Indigo-400
          ctx.font = "50px 'Space Grotesk', sans-serif";
          ctx.fillText(displayMeaning, centerX, startY + 80);

          // Descripción (Pequeña)
          if (displayDesc) {
            ctx.fillStyle = '#94a3b8'; // Slate-400
            ctx.font = "30px 'Space Grotesk', sans-serif";
            // Simple word wrap logic for canvas
            const maxWidth = canvas.width - 200;
            const words = displayDesc.split(' ');
            let line = '';
            let lineY = startY + 140;

            for(let n = 0; n < words.length; n++) {
              const testLine = line + words[n] + ' ';
              const metrics = ctx.measureText(testLine);
              const testWidth = metrics.width;
              if (testWidth > maxWidth && n > 0) {
                ctx.fillText(line, centerX, lineY);
                line = words[n] + ' ';
                lineY += 40;
              } else {
                line = testLine;
              }
            }
            ctx.fillText(line, centerX, lineY);
          }
        }

        const pngFile = canvas.toDataURL("image/png");
        const downloadLink = document.createElement("a");
        downloadLink.download = `LexiCosmos_${text || 'Simbolo'}_${engine}.png`;
        downloadLink.href = pngFile;
        downloadLink.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const getEngineIcon = (e: RenderEngine) => {
    switch(e) {
      case 'plasma': return <Activity size={16} />;
      case 'tech': return <Hexagon size={16} />;
      case 'pluma': return <Feather size={16} />;
      case 'nexo': return <Zap size={16} />;
    }
  };

  return (
    <div className="max-w-[1920px] mx-auto p-4 lg:p-6 animate-fade-in font-sans h-[calc(100vh-100px)]">
      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 h-full">

        {/* --- PANEL DE CONTROL (Izquierda) --- */}
        <div className="xl:col-span-3 space-y-4 h-full overflow-y-auto pr-2 custom-scrollbar">
          <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 shadow-2xl">

            {/* Header */}
            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
              <div className="p-2 bg-indigo-500/10 rounded-lg text-indigo-400">
                <PenTool size={20} />
              </div>
              <div>
                <h2 className="text-lg font-bold text-white tracking-wide">Tael'im V3</h2>
                <p className="text-slate-500 text-[10px] uppercase tracking-[0.2em]">Calligraphy Engine</p>
              </div>
            </div>

            <div className="space-y-6">
              {/* Input Principal */}
              <div className="relative">
                <label className="text-[10px] font-bold text-slate-500 uppercase mb-2 block tracking-wider">Radical / Entrada</label>
                <div className="flex gap-2">
                  <input 
                    type="text" 
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    className="w-full bg-slate-950 border-2 border-slate-800 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none text-xl font-bold tracking-[0.15em] uppercase font-mono transition-colors"
                    placeholder="Escribe..."
                  />
                  <button 
                    onClick={handleRandomWord}
                    className="px-3 bg-slate-800 hover:bg-indigo-600 text-slate-400 hover:text-white rounded-lg transition-colors border border-slate-700 hover:border-indigo-500"
                    title="Palabra Aleatoria"
                  >
                    <Dice5 size={20} />
                  </button>
                </div>
              </div>

               {/* Presets Rápidos */}
               <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase mb-2 block tracking-wider flex items-center gap-2">
                  <Palette size={12}/> Presets
                </label>
                <div className="grid grid-cols-4 gap-2">
                  <button onClick={() => applyPreset('cyberpunk')} className="p-2 bg-emerald-900/30 border border-emerald-500/30 rounded hover:bg-emerald-500/20 text-[10px] text-emerald-400 text-center" title="Cyberpunk">Cyber</button>
                  <button onClick={() => applyPreset('calligraphy')} className="p-2 bg-indigo-900/30 border border-indigo-500/30 rounded hover:bg-indigo-500/20 text-[10px] text-indigo-400 text-center" title="Caligrafía">Pluma</button>
                  <button onClick={() => applyPreset('magic')} className="p-2 bg-purple-900/30 border border-purple-500/30 rounded hover:bg-purple-500/20 text-[10px] text-purple-400 text-center" title="Magia">Mago</button>
                  <button onClick={() => applyPreset('ink')} className="p-2 bg-slate-800 border border-slate-600 rounded hover:bg-slate-700 text-[10px] text-slate-300 text-center" title="Tinta">Tinta</button>
                </div>
              </div>

              {/* Selector de Dialecto (Grid) */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase mb-2 block tracking-wider">Dialecto</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['algante', 'comun'] as GridMode[]).map((m) => (
                    <button 
                      key={m}
                      onClick={() => setMode(m)}
                      className={`py-2 px-3 rounded-md border text-xs font-medium uppercase tracking-wide transition-all
                        ${mode === m 
                          ? 'bg-indigo-600/10 border-indigo-500/50 text-indigo-300' 
                          : 'bg-slate-950 border-slate-800 text-slate-500 hover:border-slate-700'}
                      `}
                    >
                      {m}
                    </button>
                  ))}
                </div>
              </div>

              {/* Selector de Motor */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase mb-2 block tracking-wider">Motor</label>
                <div className="grid grid-cols-2 gap-2">
                  {(['plasma', 'tech', 'pluma', 'nexo'] as RenderEngine[]).map((e) => (
                    <button 
                      key={e}
                      onClick={() => setEngine(e)}
                      className={`flex items-center gap-2 py-3 px-3 rounded-lg border text-sm transition-all
                        ${engine === e 
                          ? 'bg-gradient-to-br from-slate-800 to-slate-900 border-white/20 text-white shadow-lg shadow-black/20' 
                          : 'bg-slate-950 border-slate-800 text-slate-500 hover:bg-slate-900 hover:text-slate-300'}
                      `}
                    >
