                  ))}
                </div>
              </div>

              {/* Controles de Grosor Variable */}
              <div className="bg-slate-950/50 p-4 rounded-xl border border-slate-800/50 space-y-4">
                 <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] uppercase font-bold text-slate-500">Perfil de Trazo</span>
                    <button onClick={handleAutoWidth} className="text-[10px] flex items-center gap-1 text-indigo-400 hover:text-indigo-300 bg-indigo-900/30 px-2 py-0.5 rounded border border-indigo-500/30">
                       <Wand2 size={10} /> Auto
                    </button>
                 </div>

                 {/* Start Width */}
                 <div>
                    <div className="flex justify-between mb-1">
                      <span className="text-xs text-slate-500">Grosor Inicial</span>
                      <span className="text-xs font-mono text-indigo-300">{startWidth}px</span>
                    </div>
                    <input type="range" min="1" max="40" value={startWidth} onChange={(e) => setStartWidth(Number(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-indigo-500" />
                 </div>

                 {/* End Width */}
                 <div>
                    <div className="flex justify-between mb-1">
                      <span className="text-xs text-slate-500">Grosor Final</span>
                      <span className="text-xs font-mono text-indigo-300">{endWidth}px</span>
                    </div>
                    <input type="range" min="1" max="40" value={endWidth} onChange={(e) => setEndWidth(Number(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500" />
                 </div>
              </div>

              {/* Otros Parámetros */}
              <div className="bg-slate-950/50 p-4 rounded-xl border border-slate-800/50 space-y-4">
                {/* Parámetro A */}
                <div>
                  <div className="flex justify-between mb-2">
                     <span className="text-[10px] uppercase font-bold text-slate-500">
                       {engine === 'plasma' && 'Tensión'}
                       {engine === 'tech' && 'Chaflán'}
