                     <span className="text-xs font-mono text-indigo-400">{paramA}</span>
                  </div>
                  <input type="range" min="0" max="100" value={paramA} onChange={(e) => setParamA(Number(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-emerald-500" />
                </div>

                 {/* Glow */}
                 <div>
                  <div className="flex justify-between mb-2">
                     <span className="text-[10px] uppercase font-bold text-slate-500">Resplandor</span>
                     <span className="text-xs font-mono text-indigo-400">{(glow/2).toFixed(1)}</span>
                  </div>
                  <input type="range" min="0" max="20" value={glow} onChange={(e) => setGlow(Number(e.target.value))} className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-amber-500" />
                </div>

              </div>

            </div>
