        </div>

        {/* --- LIENZO DE VISUALIZACIÓN (Derecha) --- */}
        <div className="xl:col-span-9 flex flex-col h-full relative">

          {/* Barra de Herramientas Flotante */}
          <div className="absolute top-6 right-6 z-20 flex gap-2 bg-slate-900/90 backdrop-blur border border-slate-700/50 p-2 rounded-xl shadow-2xl">
             <button onClick={() => setShowGuides(!showGuides)} className={`p-2 rounded-lg transition-colors border ${showGuides ? 'bg-indigo-600/20 text-indigo-300 border-indigo-500/50' : 'bg-slate-800 text-slate-500 border-transparent hover:text-white'}`} title="Mostrar/Ocultar Guías">
               {showGuides ? <Eye size={18} /> : <EyeOff size={18} />}
             </button>

             <button onClick={() => setExportWithMetadata(!exportWithMetadata)} className={`p-2 rounded-lg transition-colors border ${exportWithMetadata ? 'bg-emerald-600/20 text-emerald-300 border-emerald-500/50' : 'bg-slate-800 text-slate-500 border-transparent hover:text-white'}`} title="Incluir Significado en Exportación">
               <FileText size={18} />
             </button>

             <div className="w-px h-6 bg-slate-700 my-auto mx-1"></div>

             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.0, z + 0.1))} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"><ZoomIn size={18} /></button>
             <div className="w-px h-6 bg-slate-700 my-auto mx-1"></div>
             <button onClick={() => {setText(''); setZoom(1);}} className="p-2 text-slate-400 hover:text-white hover:bg-slate-800 rounded-lg transition-colors"><RefreshCw size={18} /></button>
             <button onClick={handleDownload} className="flex items-center gap-2 px-3 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg ml-2 font-medium text-sm transition-colors shadow-lg shadow-indigo-500/20">
               <Download size={16} /> <span className="hidden sm:inline">Exportar</span>
             </button>
          </div>

          {/* Canvas Container */}
          <div className="flex-1 bg-slate-950 rounded-2xl border border-slate-800 overflow-hidden relative flex items-center justify-center shadow-inner">

            {/* Fondo decorativo sutil */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900/5 via-slate-950 to-slate-950 pointer-events-none"></div>

            {/* Contenedor con Scroll/Pan (si fuera necesario) */}
            <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar p-10">

              {/* El SVG escala manteniendo el aspecto gracias al viewBox dinámico */}
              <div 
                style={{ 
                  width: viewWidth, 
                  height: viewHeight,
                  transform: `scale(${zoom})`, 
                  transition: 'transform 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94)',
                  maxWidth: '100%',
                  maxHeight: '100%'
                }}
              >
                <svg 
                  ref={svgRef} 
                  viewBox={`0 0 ${viewWidth} ${viewHeight}`} 
                  className="w-full h-full drop-shadow-2xl overflow-visible"
                >
                  <defs>
                    {/* Filtros de Neón mejorados */}
                    <filter id="neon-strong" x="-100%" y="-100%" width="300%" height="300%">
                      <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                      <feMerge>
                        <feMergeNode in="coloredBlur" />
                        <feMergeNode in="coloredBlur" />
                        <feMergeNode in="SourceGraphic" />
                      </feMerge>
                    </filter>
                  </defs>

                  {/* --- CAPA GRID (Retícula) --- */}
                  {showGuides && (
                    <g className="opacity-20 pointer-events-none transition-opacity duration-300">
                      {/* Dibujamos cuadrados perfectos */}
                      {currentGrid.map((row, y) => (
                        row.map((char, x) => {
                          const px = PADDING + x * CELL_SIZE;
                          const py = PADDING + y * CELL_SIZE;

                          return (
                            <g key={`${x}-${y}`}>
                              {/* Puntos de la retícula */}
                              <circle cx={px} cy={py} r={2} fill="#94a3b8" />
                              {/* Letras tenues */}
                              <text 
                                x={px} y={py + CELL_SIZE/2 - 10} 
                                textAnchor="middle" 
                                fill="#475569" 
                                fontSize="10" 
                                fontFamily="monospace"
                                opacity={0.5}
                              >
                                {char}
                              </text>
                            </g>
                          );
                        })
                      ))}
                    </g>
                  )}

                  {/* --- CAPA NODOS ACTIVOS --- */}
                  {showGuides && activePoints.map((p, i) => (
                    <g key={i} className="transition-opacity duration-300">
                       {/* Halo del nodo */}
                       <circle cx={p.x} cy={p.y} r={24} fill={mode === 'algante' ? '#6366f1' : '#10b981'} fillOpacity="0.1" />
                       {/* Núcleo del nodo */}
                       <circle cx={p.x} cy={p.y} r={4} fill={mode === 'algante' ? '#a5b4fc' : '#6ee7b7'} />
                       {/* Letra Activa */}
                       <text 
                         x={p.x} y={p.y - 12} 
                         textAnchor="middle" 
                         fill="white" 
                         fontSize="14" 
                         fontWeight="bold"
                         style={{ textShadow: '0 2px 4px rgba(0,0,0,0.5)' }}
                       >
                         {p.char}
                       </text>
                       {/* Marcador de Inicio */}
                       {i === 0 && <circle cx={p.x} cy={p.y} r={32} stroke="white" strokeWidth={1} strokeDasharray="4 4" fill="none" opacity="0.5" />}
                       {/* Marcador de Fin */}
                       {i === activePoints.length - 1 && <circle cx={p.x} cy={p.y} r={32} stroke="white" strokeWidth={2} fill="none" opacity="0.8" />}
                    </g>
                  ))}

                  {/* --- CAPA TRAZADO PRINCIPAL --- */}
                  <g 
                    filter={glow > 0 ? "url(#neon-strong)" : ""} 
                    className={mode === 'algante' ? 'text-indigo-400' : 'text-emerald-400'}
                  >
                    {renderPath()}
                  </g>

                </svg>
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

