import React, { useState, useMemo, useRef } from 'react';
import { 
  PenTool, Download, ZoomIn, ZoomOut, RefreshCw, Dice5, 
  Eye, EyeOff, FileText, Sliders, Zap, Layers, Activity, Wand2
} from 'lucide-react';
import { Term } from '../types';

type GridMode = 'algante' | 'comun';
type RenderEngine = 'plasma' | 'tech' | 'pluma' | 'nexo';

interface Props {
  terms?: Term[];
}

// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY MATH HELPERS ---

// Pseudo-random estable para que el "Ruido" no vibre al renderizar
const pseudoRandom = (seed: number) => {
  const x = Math.sin(seed * 12.9898) * 43758.5453;
  return x - Math.floor(x);
};

// Catmull-Rom Spline Interpolation
const getSplinePoints = (
  points: {x: number, y: number}[], 
  tension: number, 
  resolution: number,
  roughness: number
) => {
  if (points.length < 2) return points;

  const spline: {x: number, y: number}[] = [];
  const getPt = (i: number) => points[Math.max(0, Math.min(points.length - 1, i))];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = getPt(i - 1);
    const p1 = getPt(i);
    const p2 = getPt(i + 1);
    const p3 = getPt(i + 2);

    for (let t = 0; t < 1; t += 1/resolution) {
      const t2 = t * t;
      const t3 = t2 * t;

      // Catmull-Rom
      let x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3);
      let y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3);

      // Apply Roughness (Noise)
      if (roughness > 0) {
        const seed = (i * resolution) + (t * 100);
        const noiseX = (pseudoRandom(seed) - 0.5) * roughness;
        const noiseY = (pseudoRandom(seed + 1000) - 0.5) * roughness;
        x += noiseX;
        y += noiseY;
      }

      spline.push({ x, y });
    }
  }
  spline.push(points[points.length - 1]);
  return spline;
};

// Advanced Variable Width Polygon Generator
const getBrushPath = (
  points: {x: number, y: number}[], 
  opts: {
    startW: number,
    midW: number,
    endW: number,
    angleInfluence: number, // 0 = sin efecto, 1 = efecto plumilla
    penAngleDeg: number // Ángulo de la plumilla
  }
) => {
  if (points.length < 2) return '';

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];
  const penAngleRad = (opts.penAngleDeg * Math.PI) / 180;

  points.forEach((p, i) => {
    // 1. Calcular progreso (0 a 1)
    const t = i / (points.length - 1);

    // 2. Calcular ancho base según perfil (Start -> Mid -> End)
    let baseWidth;
    if (t < 0.5) {
      // Interpolate Start to Mid
      const localT = t * 2; 
      baseWidth = opts.startW + (opts.midW - opts.startW) * localT;
    } else {
      // Interpolate Mid to End
      const localT = (t - 0.5) * 2;
      baseWidth = opts.midW + (opts.endW - opts.midW) * localT;
    }

    // 3. Calcular vector normal (dirección perpendicular al trazo)
    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    // 4. Aplicar efecto de plumilla caligráfica (Opcional)
    if (opts.angleInfluence > 0) {
      // Calculamos el ángulo actual del trazo
      const strokeAngle = Math.atan2(dy, dx);
      // Diferencia con el ángulo de la pluma
      const angleDiff = Math.abs(Math.cos(strokeAngle - penAngleRad));
      // Modulamos el ancho: si son perpendiculares = ancho máximo, paralelos = ancho mínimo
      const calligraphicFactor = 0.2 + (0.8 * angleDiff); // Nunca dejamos que desaparezca del todo (0.2 min)

      // Mezclamos el ancho base con el ancho caligráfico según la influencia
      baseWidth = baseWidth * (1 - opts.angleInfluence) + (baseWidth * calligraphicFactor * opts.angleInfluence);
    }

    const halfW = baseWidth / 2;

    leftSide.push({ x: p.x + nx * halfW, y: p.y + ny * halfW });
    rightSide.push({ x: p.x - nx * halfW, y: p.y - ny * halfW });
  });

  // Construir SVG Path
  let d = `M ${leftSide[0].x} ${leftSide[0].y}`;
  for (let i = 1; i < leftSide.length; i++) d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  for (let i = rightSide.length - 1; i >= 0; i--) d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  d += ' Z';

  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [] }) => {
  // Estado Principal
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);
  const [showGuides, setShowGuides] = useState(true);
  const [exportWithMetadata, setExportWithMetadata] = useState(false);

  // --- PARÁMETROS DE CALIGRAFÍA AVANZADOS ---
  // Geometría
  const [tension, setTension] = useState(50); // 0 (Recto) - 100 (Curvo)
  const [roughness, setRoughness] = useState(0); // Ruido en el trazo

  // Dinámica del Trazo (Width Profile)
  const [widthStart, setWidthStart] = useState(2);
  const [widthMid, setWidthMid] = useState(8);
  const [widthEnd, setWidthEnd] = useState(2);

  // Efecto Plumilla
  const [penAngle, setPenAngle] = useState(45); // Grados
  const [calligraphyAmount, setCalligraphyAmount] = useState(0); // 0 - 100% influencia

  // Efectos Visuales
  const [glow, setGlow] = useState(5);
  const [echoes, setEchoes] = useState(0); // Copias del trazo
  const [echoOffset, setEchoOffset] = useState(10); 

  const svgRef = useRef<SVGSVGElement>(null);

  // --- LÓGICA DEL GRID ---
  const CELL_SIZE = 100;
  const PADDING = 80;
  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const viewWidth = (currentGrid[0].length - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (currentGrid.length - 1) * CELL_SIZE + (PADDING * 2);
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- PRESETS ---
  const loadPreset = (type: string) => {
    switch(type) {
      case 'ink': // Tinta clásica
        setTension(60); setRoughness(5);
        setWidthStart(3); setWidthMid(12); setWidthEnd(1);
        setCalligraphyAmount(80); setPenAngle(30);
        setEchoes(0); setGlow(0);
        break;
      case 'marker': // Rotulador grueso constante
        setTension(40); setRoughness(2);
        setWidthStart(10); setWidthMid(10); setWidthEnd(10);
        setCalligraphyAmount(0);
        setEchoes(0); setGlow(0);
        break;
      case 'tech': // Cibernético
        setTension(0); setRoughness(0);
        setWidthStart(2); setWidthMid(2); setWidthEnd(2);
        setCalligraphyAmount(0);
        setEchoes(2); setEchoOffset(6); setGlow(10);
        break;
      case 'energy': // Plasma vibrante
        setTension(80); setRoughness(15);
        setWidthStart(1); setWidthMid(6); setWidthEnd(1);
        setCalligraphyAmount(0);
        setEchoes(1); setEchoOffset(3); setGlow(15);
        break;
    }
  };

  // --- CÁLCULO DE PUNTOS ACTIVOS ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const points: {x: number, y: number, char: string}[] = [];
    let lastPos: {x: number, y: number} | null = null;

    cleanText.split('').forEach(char => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;
      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) { minDist = dist; chosenPos = pos; }
        });
      }
      points.push({ x: PADDING + chosenPos.x * CELL_SIZE, y: PADDING + chosenPos.y * CELL_SIZE, char });
      lastPos = chosenPos;
    });
    return points;
  }, [text, gridMap]); 


  // --- RENDERIZADO DEL TRAZO ---
  const renderTrace = () => {
    if (activePoints.length < 2) return null;

    // 1. Generar Spline (Curva base)
    const splinePoints = getSplinePoints(
      activePoints, 
      tension / 100, // Normalized tension
      15, // Resolution
      roughness
    );

    // 2. Generar Polígono de Ancho Variable (Brush)
    const paths = [];
    const baseColor = mode === 'algante' ? 'currentColor' : 'currentColor';

    // Loop de Ecos (Multicapa)
    const totalLayers = 1 + echoes;

    for (let i = 0; i < totalLayers; i++) {
      // Calcular offset para ecos
      let layerPoints = splinePoints;
      let opacity = 1;
      let layerWidthStart = widthStart;
      let layerWidthMid = widthMid;
      let layerWidthEnd = widthEnd;

      if (i > 0) {
        // Lógica de desplazamiento para ecos
        // Desplazamos los puntos perpendicularmente o simplemente en X/Y
        const offset = i * echoOffset;
        layerPoints = splinePoints.map(p => ({ x: p.x + offset, y: p.y + offset }));
        opacity = 0.3 / i; // Ecos más transparentes
        // Ecos más finos
        layerWidthStart *= 0.5;
        layerWidthMid *= 0.5;
        layerWidthEnd *= 0.5;
      }

      const pathData = getBrushPath(layerPoints, {
        startW: layerWidthStart,
        midW: layerWidthMid,
        endW: layerWidthEnd,
        angleInfluence: calligraphyAmount / 100,
        penAngleDeg: penAngle
      });

      paths.push(
        <path 
          key={i} 
          d={pathData} 
          fill={baseColor} 
          opacity={engine === 'tech' && i > 0 ? 0.8 : 0.8 * opacity}
          fillRule="nonzero"
        />
      );
    }

    // Tech decorations (overlay nodes)
    if (engine === 'tech') {
       paths.push(
         <path 
            key="wireframe"
            d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`}
            fill="none"
            stroke={baseColor}
            strokeWidth={1}
            opacity={0.5}
            strokeDasharray="4 4"
         />
       );
    }

    return <g>{paths}</g>;
  };


  // --- HANDLERS (Igual que antes) ---
  const handleRandomWord = () => {
    if (terms.length > 0) setText(terms[Math.floor(Math.random() * terms.length)].root);
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();
    const scaleFactor = 3;
    const paddingBottom = exportWithMetadata ? 300 : 0;

    canvas.width = viewWidth * scaleFactor;
    canvas.height = (viewHeight * scaleFactor) + paddingBottom;

    img.onload = () => {
      if(ctx) {
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, viewWidth * scaleFactor, viewHeight * scaleFactor);

        if (exportWithMetadata) {
          const currentTerm = terms.find(t => t.root.toLowerCase() === text.toLowerCase());
          const displayRoot = currentTerm ? currentTerm.root : text;
          const displayMeaning = currentTerm ? currentTerm.meaning : "Trazo Libre";

          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffffff';
          ctx.font = "bold 80px 'Space Grotesk', sans-serif";
          ctx.fillText(displayRoot.toUpperCase(), canvas.width / 2, (viewHeight * scaleFactor) + 80);
          ctx.fillStyle = '#818cf8';
          ctx.font = "50px 'Space Grotesk', sans-serif";
          ctx.fillText(displayMeaning, canvas.width / 2, (viewHeight * scaleFactor) + 160);
        }

        const link = document.createElement("a");
        link.download = `LexiCosmos_${text}.png`;
        link.href = canvas.toDataURL("image/png");
        link.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  return (
    <div className="max-w-[1920px] mx-auto p-4 animate-fade-in font-sans h-[calc(100vh-100px)]">
      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 h-full">

        {/* --- PANEL LATERAL DE CONTROLES COMPLETOS --- */}
        <div className="xl:col-span-3 space-y-4 h-full overflow-y-auto pr-2 custom-scrollbar pb-20">
          <div className="bg-slate-900 p-5 rounded-2xl border border-slate-800 shadow-2xl">

            {/* Header */}
            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
              <div className="p-2 bg-indigo-500/10 rounded-lg text-indigo-400">
                <PenTool size={20} />
              </div>
              <div>
                <h2 className="text-lg font-bold text-white">Tael'im V4</h2>
                <p className="text-slate-500 text-[10px] uppercase tracking-widest">Master Calligraphy</p>
              </div>
            </div>

            {/* Input & Dialect */}
            <div className="space-y-4 mb-6">
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none text-xl font-bold font-mono tracking-widest uppercase"
                  placeholder="PALABRA..."
                />
                <button onClick={handleRandomWord} className="px-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg border border-slate-700"><Dice5 size={20}/></button>
              </div>
              <div className="grid grid-cols-2 gap-2">
                  {(['algante', 'comun'] as GridMode[]).map((m) => (
                    <button key={m} onClick={() => setMode(m)} className={`py-1.5 px-3 rounded border text-[10px] font-bold uppercase tracking-wider ${mode === m ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300' : 'bg-slate-950 border-slate-800 text-slate-500'}`}>{m}</button>
                  ))}
              </div>
            </div>

            {/* PRESETS */}
            <div className="mb-6">
               <label className="text-[10px] font-bold text-slate-500 uppercase mb-2 flex items-center gap-2"><Wand2 size={12}/> Estilos Rápidos</label>
               <div className="grid grid-cols-4 gap-2">
                 {['ink', 'marker', 'tech', 'energy'].map(p => (
                   <button key={p} onClick={() => loadPreset(p)} className="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded py-1 text-[10px] text-slate-300 capitalize">{p}</button>
                 ))}
               </div>
            </div>

            <hr className="border-slate-800 mb-6" />

            {/* --- SECCIÓN 1: DINÁMICA DEL TRAZO (GROSOR) --- */}
            <div className="space-y-4 mb-6">
               <div className="flex items-center gap-2 text-indigo-400 mb-2">
                 <Activity size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Perfil de Presión</span>
               </div>

               <div className="grid grid-cols-3 gap-2">
                 <div>
                   <label className="text-[9px] text-slate-500 uppercase block mb-1">Inicio</label>
                   <input type="number" value={widthStart} onChange={e => setWidthStart(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white" />
                 </div>
                 <div>
                   <label className="text-[9px] text-slate-500 uppercase block mb-1">Medio</label>
                   <input type="number" value={widthMid} onChange={e => setWidthMid(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white" />
                 </div>
                 <div>
                   <label className="text-[9px] text-slate-500 uppercase block mb-1">Final</label>
                   <input type="number" value={widthEnd} onChange={e => setWidthEnd(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white" />
                 </div>
               </div>
               <input type="range" min="1" max="40" value={widthMid} onChange={(e) => setWidthMid(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-indigo-500" />
            </div>

            {/* --- SECCIÓN 2: GEOMETRÍA --- */}
            <div className="space-y-4 mb-6">
               <div className="flex items-center gap-2 text-emerald-400 mb-2">
                 <Sliders size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Geometría</span>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Tensión (Curva vs Recta)</span> <span>{tension}%</span></div>
                  <input type="range" min="0" max="100" value={tension} onChange={(e) => setTension(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-500" />
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Rugosidad (Ruido)</span> <span>{roughness}</span></div>
                  <input type="range" min="0" max="30" value={roughness} onChange={(e) => setRoughness(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-500" />
               </div>
            </div>

            {/* --- SECCIÓN 3: EFECTO PLUMILLA --- */}
            <div className="space-y-4 mb-6">
               <div className="flex items-center gap-2 text-purple-400 mb-2">
                 <Zap size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Efecto Plumilla</span>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Influencia de Ángulo</span> <span>{calligraphyAmount}%</span></div>
                  <input type="range" min="0" max="100" value={calligraphyAmount} onChange={(e) => setCalligraphyAmount(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-purple-500" />
               </div>

               <div className={`${calligraphyAmount === 0 ? 'opacity-30' : ''} transition-opacity`}>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Ángulo de Pluma</span> <span>{penAngle}°</span></div>
                  <input type="range" min="0" max="180" value={penAngle} onChange={(e) => setPenAngle(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-purple-500" />
               </div>
            </div>

            {/* --- SECCIÓN 4: MULTICAPA & FX --- */}
            <div className="space-y-4">
               <div className="flex items-center gap-2 text-amber-400 mb-2">
                 <Layers size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Ecos & FX</span>
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Ecos (Copias)</label>
                    <input type="number" min="0" max="5" value={echoes} onChange={e => setEchoes(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white" />
                 </div>
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Offset Eco</label>
                    <input type="number" value={echoOffset} onChange={e => setEchoOffset(Number(e.target.value))} className="w-full bg-slate-950 border border-slate-700 rounded px-2 py-1 text-xs text-white" />
                 </div>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Resplandor (Glow)</span> <span>{glow}</span></div>
                  <input type="range" min="0" max="30" value={glow} onChange={(e) => setGlow(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
               </div>
            </div>

          </div>
        </div>

        {/* --- VISUALIZADOR --- */}
        <div className="xl:col-span-9 flex flex-col h-full relative">

           {/* Floating Toolbar */}
           <div className="absolute top-6 right-6 z-20 flex gap-2 bg-slate-900/90 backdrop-blur border border-slate-700/50 p-2 rounded-xl shadow-2xl">
             <button onClick={() => setShowGuides(!showGuides)} className={`p-2 rounded-lg transition-colors border ${showGuides ? 'bg-indigo-600/20 text-indigo-300 border-indigo-500/50' : 'bg-slate-800 text-slate-500 border-transparent'}`} title="Guías"><Eye size={18} /></button>
             <button onClick={() => setExportWithMetadata(!exportWithMetadata)} className={`p-2 rounded-lg transition-colors border ${exportWithMetadata ? 'bg-emerald-600/20 text-emerald-300 border-emerald-500/50' : 'bg-slate-800 text-slate-500 border-transparent'}`} title="Metadatos"><FileText size={18} /></button>
             <div className="w-px h-6 bg-slate-700 my-auto mx-1"></div>
             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-400 hover:text-white"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.0, z + 0.1))} className="p-2 text-slate-400 hover:text-white"><ZoomIn size={18} /></button>
             <button onClick={handleDownload} className="flex items-center gap-2 px-3 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg ml-2 font-medium text-sm shadow-lg shadow-indigo-500/20"><Download size={16} /> Exportar</button>
           </div>

           {/* Canvas */}
           <div className="flex-1 bg-slate-950 rounded-2xl border border-slate-800 overflow-hidden relative flex items-center justify-center shadow-inner">
             <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900/5 via-slate-950 to-slate-950 pointer-events-none"></div>
             <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar p-10">
               <div style={{ width: viewWidth, height: viewHeight, transform: `scale(${zoom})`, transition: 'transform 0.3s ease-out' }}>
                 <svg ref={svgRef} viewBox={`0 0 ${viewWidth} ${viewHeight}`} className="w-full h-full drop-shadow-2xl overflow-visible">
                    <defs>
                      <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                        <feMerge>
                          <feMergeNode in="coloredBlur" />
                          <feMergeNode in="SourceGraphic" />
                        </feMerge>
                      </filter>
                    </defs>

                    {/* Guías */}
                    {showGuides && (
                      <g className="opacity-20 pointer-events-none">
                        {currentGrid.map((row, y) => row.map((char, x) => (
                           <g key={`${x}-${y}`}>
                             <circle cx={PADDING + x * CELL_SIZE} cy={PADDING + y * CELL_SIZE} r={2} fill="#64748b" />
                             <text x={PADDING + x * CELL_SIZE} y={PADDING + y * CELL_SIZE + 40} textAnchor="middle" fill="#64748b" fontSize="10" fontFamily="monospace" opacity={0.5}>{char}</text>
                           </g>
                        )))}
                      </g>
                    )}

                    {/* Nodos Activos */}
                    {showGuides && activePoints.map((p, i) => (
                      <g key={i}>
                        <circle cx={p.x} cy={p.y} r={4} fill={mode === 'algante' ? '#818cf8' : '#34d399'} opacity={0.8} />
                        <text x={p.x} y={p.y - 15} textAnchor="middle" fill="white" fontSize="12" fontWeight="bold">{p.char}</text>
                      </g>
                    ))}

                    {/* TRAZO PRINCIPAL */}
                    <g filter={glow > 0 ? "url(#neon-glow)" : ""} className={mode === 'algante' ? 'text-indigo-400' : 'text-emerald-400'}>
                      {renderTrace()}
                    </g>
                 </svg>
               </div>
             </div>
           </div>

        </div>
      </div>
    </div>
  );
};

export default Taelim;

import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import StatsDashboard from './components/StatsDashboard';
import GlossaryList from './components/GlossaryList';
import Constructor from './components/Constructor';
import Taelim from './components/Taelim';
import { initialData } from './data/initialData';
import { Term } from './types';

const STORAGE_KEY = 'lexicosmos_data_v2'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'glossary' | 'stats' | 'constructor' | 'taelim'>('glossary');
  const [terms, setTerms] = useState<Term[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Load and Merge Strategy
  useEffect(() => {
    const loadData = () => {
      try {
        const storedJson = localStorage.getItem(STORAGE_KEY);
        // Fallback to old key if new key not found
        const oldJson = localStorage.getItem('lexicosmos_data');

        let localTerms: Term[] = [];

        if (storedJson) {
          localTerms = JSON.parse(storedJson);
        } else if (oldJson) {
          localTerms = JSON.parse(oldJson);
        }

        const localMap = new Map(localTerms.map(t => [t.root.toLowerCase(), t]));
        const mergedTerms = [...localTerms];

        initialData.forEach(staticTerm => {
          if (!localMap.has(staticTerm.root.toLowerCase())) {
            mergedTerms.push(staticTerm);
          }
        });

        // Sort by Root A-Z
        mergedTerms.sort((a, b) => a.root.localeCompare(b.root));

        setTerms(mergedTerms);
      } catch (e) {
        console.error("Failed to load/merge data", e);
        setTerms(initialData);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, []);

  // Persist data on change
  useEffect(() => {
    if (!isLoading && terms.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(terms));
    }
  }, [terms, isLoading]);

  const addTerm = (term: Term) => {
    setTerms(prev => {
      const updated = [term, ...prev];
      updated.sort((a, b) => a.root.localeCompare(b.root));
      return updated;
    });
    alert(`Radical "${term.root}" guardado exitosamente.`);
    setActiveTab('glossary'); 
  };

  const updateTerm = (updatedTerm: Term) => {
    setTerms(prev => prev.map(t => t.id === updatedTerm.id ? updatedTerm : t));
    // No alert necessary for smoother UX, visual feedback in UI is handled by modal closing
  };

  const handleExport = () => {
    const dataStr = JSON.stringify(terms, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `lexicosmos_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = event.target?.result as string;
        const importedTerms = JSON.parse(json);
        if (Array.isArray(importedTerms)) {
          if (importedTerms.length > 0 && !importedTerms[0].root) {
            throw new Error("Formato inválido");
          }
          if (confirm(`Se van a importar ${importedTerms.length} términos. Esto reemplazará la lista actual. ¿Deseas continuar?`)) {
            setTerms(importedTerms);
            alert("Base de datos importada correctamente.");
          }
        }
      } catch (error) {
        alert("Error al importar el archivo. Asegúrate de que es un JSON válido de LexiCosmos.");
        console.error(error);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center text-indigo-400 gap-4">
        <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
        <p className="animate-pulse">Sincronizando Base de Datos LexiCosmos...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 font-sans selection:bg-indigo-500/30">
      <Navigation 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onExport={handleExport}
        onImport={handleImport}
      />

      <main className="container mx-auto py-8 px-4">
        {activeTab === 'stats' && <StatsDashboard terms={terms} />}
        {activeTab === 'glossary' && <GlossaryList terms={terms} onUpdateTerm={updateTerm} />}
        {activeTab === 'constructor' && <Constructor onAddTerm={addTerm} />}
        {activeTab === 'taelim' && <Taelim terms={terms} />}
      </main>

      <footer className="text-center py-8 text-slate-600 text-sm">
        <p>LexiCosmos System v1.4.0 • Powered by Gemini AI</p>
      </footer>
    </div>
  );
};

export default App;

