import React, { useState, useEffect } from 'react';
import Navigation from './components/Navigation';
import StatsDashboard from './components/StatsDashboard';
import GlossaryList from './components/GlossaryList';
import Constructor from './components/Constructor';
import Taelim from './components/Taelim';
import { initialData } from './data/initialData';
import { Term, TaelimPreset, LexiData } from './types';

const STORAGE_KEY = 'lexicosmos_full_data_v3'; 

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'glossary' | 'stats' | 'constructor' | 'taelim'>('glossary');
  const [terms, setTerms] = useState<Term[]>([]);
  const [presets, setPresets] = useState<TaelimPreset[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Load and Merge Strategy
  useEffect(() => {
    const loadData = () => {
      try {
        const storedJson = localStorage.getItem(STORAGE_KEY);
        // Fallback checks
        const oldJsonV2 = localStorage.getItem('lexicosmos_data_v2');
        const oldJsonV1 = localStorage.getItem('lexicosmos_data');

        let loadedTerms: Term[] = [];
        let loadedPresets: TaelimPreset[] = [];

        if (storedJson) {
          const data = JSON.parse(storedJson) as LexiData;
          loadedTerms = data.terms || [];
          loadedPresets = data.presets || [];
        } else if (oldJsonV2) {
          // Migration V2 -> V3
          loadedTerms = JSON.parse(oldJsonV2);
        } else if (oldJsonV1) {
          // Migration V1 -> V3
          loadedTerms = JSON.parse(oldJsonV1);
        }

        // Merge initial static data if missing
        const localMap = new Map(loadedTerms.map(t => [t.root.toLowerCase(), t]));
        const mergedTerms = [...loadedTerms];

        initialData.forEach(staticTerm => {
          if (!localMap.has(staticTerm.root.toLowerCase())) {
            mergedTerms.push(staticTerm);
          }
        });

        // Sort by Root A-Z
        mergedTerms.sort((a, b) => a.root.localeCompare(b.root));

        setTerms(mergedTerms);
        setPresets(loadedPresets);

      } catch (e) {
        console.error("Failed to load/merge data", e);
        setTerms(initialData);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, []);

  // Persist data on change
  useEffect(() => {
    if (!isLoading) {
      const dataToSave: LexiData = {
        version: 3,
        terms: terms,
        presets: presets
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(dataToSave));
    }
  }, [terms, presets, isLoading]);

  const addTerm = (term: Term) => {
    setTerms(prev => {
      const updated = [term, ...prev];
      updated.sort((a, b) => a.root.localeCompare(b.root));
      return updated;
    });
    alert(`Radical "${term.root}" guardado exitosamente.`);
    setActiveTab('glossary'); 
  };

  const updateTerm = (updatedTerm: Term) => {
    setTerms(prev => prev.map(t => t.id === updatedTerm.id ? updatedTerm : t));
  };

  // Handlers for Taelim Presets
  const handleSavePreset = (preset: TaelimPreset) => {
    setPresets(prev => [...prev, preset]);
  };

  const handleDeletePreset = (id: string) => {
    setPresets(prev => prev.filter(p => p.id !== id));
  };

  const handleExport = () => {
    const data: LexiData = {
      version: 3,
      terms: terms,
      presets: presets
    };
    const dataStr = JSON.stringify(data, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `lexicosmos_full_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = event.target?.result as string;
        const parsed = JSON.parse(json);

        let newTerms: Term[] = [];
        let newPresets: TaelimPreset[] = [];

        // Detect format
        if (Array.isArray(parsed)) {
          // Old format (Array of terms)
          newTerms = parsed;
        } else if (parsed.terms) {
          // New format
          newTerms = parsed.terms;
          newPresets = parsed.presets || [];
        } else {
           throw new Error("Formato desconocido");
        }

        if (confirm(`Se han detectado ${newTerms.length} términos y ${newPresets.length} presets de estilos. ¿Deseas reemplazar la sesión actual?`)) {
          setTerms(newTerms);
          setPresets(newPresets);
          alert("Sesión restaurada correctamente.");
        }
      } catch (error) {
        alert("Error al importar el archivo. Asegúrate de que es un JSON válido de LexiCosmos.");
        console.error(error);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center text-indigo-400 gap-4">
        <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
        <p className="animate-pulse">Sincronizando Base de Datos LexiCosmos...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f172a] text-slate-200 font-sans selection:bg-indigo-500/30 overflow-hidden flex flex-col">
      <Navigation 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onExport={handleExport}
        onImport={handleImport}
      />

      {/* 
        Main content wrapper with overflow-auto. 
        Using display:none preserves component state when switching tabs.
      */}
      <main className="flex-1 overflow-y-auto container mx-auto py-8 px-4 relative">
        <div className={activeTab === 'glossary' ? 'block animate-fade-in' : 'hidden'}>
          <GlossaryList terms={terms} onUpdateTerm={updateTerm} />
        </div>

        <div className={activeTab === 'stats' ? 'block animate-fade-in' : 'hidden'}>
          <StatsDashboard terms={terms} />
        </div>

        <div className={activeTab === 'constructor' ? 'block animate-fade-in' : 'hidden'}>
          <Constructor onAddTerm={addTerm} />
        </div>

        <div className={activeTab === 'taelim' ? 'block h-full animate-fade-in' : 'hidden'}>
           <Taelim 
             terms={terms} 
             customPresets={presets}
             onSavePreset={handleSavePreset}
             onDeletePreset={handleDeletePreset}
           />
        </div>
      </main>

      <footer className="text-center py-4 text-slate-600 text-xs bg-slate-950/50 backdrop-blur border-t border-slate-800/50">
        <p>LexiCosmos System v1.5.0 • Powered by Gemini AI</p>
      </footer>
    </div>
  );
};

export default App;

