// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY MATH HELPERS ---
const getDistance = (p1: {x:number, y:number}, p2: {x:number, y:number}) => 
  Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));

const getControlPoint = (
  current: {x:number, y:number}, 
  previous: {x:number, y:number}, 
  next: {x:number, y:number}, 
  reverse: boolean,
  tension: number
) => {
  const p = previous || current;
  const n = next || current;
  const smoothing = tension;

  const o = {
    x: n.x - p.x + (n.x - current.x),
    y: n.y - p.y + (n.y - current.y)
  };

  const angle = Math.atan2(o.y, o.x) + (reverse ? Math.PI : 0);
  const length = getDistance(current, n) * smoothing;

  return {
    x: current.x + Math.cos(angle) * length,
    y: current.y + Math.sin(angle) * length
  };
};

// Point with Weight info
interface WeightedPoint {
  x: number;
  y: number;
  w: number; // Width at this specific sub-point
}

interface SegmentPressure {
  start: number;
  mid: number;
  end: number;
}

const getBezierPointsWithWeight = (
  points: {x: number, y: number}[], 
  segments: SegmentPressure[],
  tension: number, 
  resolution: number,
  waveFreq: number, 
  waveAmp: number   
): WeightedPoint[] => {
  if (points.length < 2) {
    // Single point fallback: uses the first segment's start as the global point width
    return points.map(p => ({ ...p, w: segments[0]?.start || 10 }));
  }

  const finalPoints: WeightedPoint[] = [];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1]; 
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2]; 

    // Get pressure profile for this segment (p1 -> p2)
    const seg = segments[i] || { start: 10, mid: 10, end: 10 };

    const cp1 = getControlPoint(p1, p0, p2, false, tension);
    const cp2 = getControlPoint(p2, p1, p3, true, tension);

    for (let t = 0; t <= 1; t += 1/resolution) {
      const x = Math.pow(1-t, 3)*p1.x + 3*Math.pow(1-t, 2)*t*cp1.x + 3*(1-t)*Math.pow(t, 2)*cp2.x + Math.pow(t, 3)*p2.x;
      const y = Math.pow(1-t, 3)*p1.y + 3*Math.pow(1-t, 2)*t*cp1.y + 3*(1-t)*Math.pow(t, 2)*cp2.y + Math.pow(t, 3)*p2.y;

      // Interpolate width: Start -> Mid -> End
      let currentW;
      if (t <= 0.5) {
        // Map 0..0.5 to 0..1 for Start->Mid
        const localT = t * 2;
        currentW = seg.start + (seg.mid - seg.start) * localT;
      } else {
        // Map 0.5..1 to 0..1 for Mid->End
        const localT = (t - 0.5) * 2;
        currentW = seg.mid + (seg.end - seg.mid) * localT;
      }

      let finalX = x;
      let finalY = y;

      if (waveAmp > 0) {
        const tx = (3*Math.pow(1-t, 2)*(cp1.x-p1.x) + 6*(1-t)*t*(cp2.x-cp1.x) + 3*t*t*(p2.x-cp2.x));
        const ty = (3*Math.pow(1-t, 2)*(cp1.y-p1.y) + 6*(1-t)*t*(cp2.y-cp1.y) + 3*t*t*(p2.y-cp2.y));
        const mag = Math.sqrt(tx*tx + ty*ty) || 1;
        const nx = -ty / mag; 
        const ny = tx / mag; 

        const wave = Math.sin((i + t) * waveFreq * Math.PI) * waveAmp;

        finalX += nx * wave;
        finalY += ny * wave;
      }

      finalPoints.push({ x: finalX, y: finalY, w: currentW });
    }
  }

  // Last point logic
  const lastSeg = segments[segments.length - 1];
  finalPoints.push({ 
    ...points[points.length - 1], 
    w: lastSeg ? lastSeg.end : 10 
  });

  return finalPoints;
};

// Variable Width Brush using per-point weights
const getBrushPath = (
  points: WeightedPoint[], 
  opts: {
    angleInfluence: number, 
    penAngleDeg: number
  }
) => {
  if (points.length < 2 && points.length > 0) {
      // Circle for single point
      const p = points[0];
      const r = p.w / 2;
      return `M ${p.x} ${p.y-r} A ${r} ${r} 0 1 0 ${p.x} ${p.y+r} A ${r} ${r} 0 1 0 ${p.x} ${p.y-r} Z`;
  }
  if (points.length === 0) return '';

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];
  const penAngleRad = (opts.penAngleDeg * Math.PI) / 180;

  points.forEach((p, i) => {
    let baseWidth = p.w;

    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    if (opts.angleInfluence > 0) {
      const strokeAngle = Math.atan2(dy, dx);
      const angleDiff = Math.abs(Math.cos(strokeAngle - penAngleRad));
      const calligraphicFactor = 0.2 + (0.8 * angleDiff);
      baseWidth = baseWidth * (1 - opts.angleInfluence) + (baseWidth * calligraphicFactor * opts.angleInfluence);
    }

    const halfW = baseWidth / 2;
    leftSide.push({ x: p.x + nx * halfW, y: p.y + ny * halfW });
    rightSide.push({ x: p.x - nx * halfW, y: p.y - ny * halfW });
  });

  let d = `M ${leftSide[0].x} ${leftSide[0].y}`;
  for (let i = 1; i < leftSide.length; i++) d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  for (let i = rightSide.length - 1; i >= 0; i--) d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  d += ' Z';
  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [], customPresets = [], onSavePreset, onDeletePreset, onImportSession }) => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);
  const [showGuides, setShowGuides] = useState(true);
  const [exportWithMetadata, setExportWithMetadata] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- PARÁMETROS CALIGRÁFICOS ---
  const [tension, setTension] = useState(0.2); 
  const [fluidity, setFluidity] = useState(0); 
  const [waveFreq, setWaveFreq] = useState(0); 
  const [waveAmp, setWaveAmp] = useState(0);   

  // 2. Dinámica del Trazo (Presiones por Segmento)
  const [segmentPressures, setSegmentPressures] = useState<SegmentPressure[]>([]);

  const [penAngle, setPenAngle] = useState(45);
  const [calligraphyAmount, setCalligraphyAmount] = useState(0);

  // 3. Efectos y Florituras
  const [glow, setGlow] = useState(5);
  const [echoes, setEchoes] = useState(0);
  const [echoOffset, setEchoOffset] = useState(10); 
  const [inkDensity, setInkDensity] = useState(0); 
  const [erosion, setErosion] = useState(0); 
  const [particles, setParticles] = useState(0); 

  // --- SAVE PRESET STATE ---
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');

  const svgRef = useRef<SVGSVGElement>(null);

  // --- GRID SETUP ---
  const CELL_SIZE = 100;
  const PADDING = 80;
  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const viewWidth = (currentGrid[0].length - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (currentGrid.length - 1) * CELL_SIZE + (PADDING * 2);
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- CALCULATE ACTIVE POINTS ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const points: {x: number, y: number, char: string, originalX: number, originalY: number}[] = [];
    let lastPos: {x: number, y: number} | null = null;

    cleanText.split('').forEach((char, idx) => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;
      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) { minDist = dist; chosenPos = pos; }
        });
      }

      const seed = idx * 1337;
      const wobbleX = fluidity > 0 ? (Math.sin(seed) * fluidity) : 0;
      const wobbleY = fluidity > 0 ? (Math.cos(seed) * fluidity) : 0;

      const px = PADDING + chosenPos.x * CELL_SIZE;
      const py = PADDING + chosenPos.y * CELL_SIZE;

      points.push({ 
        x: px + wobbleX, 
        y: py + wobbleY, 
        originalX: px,
        originalY: py,
        char 
      });
      lastPos = chosenPos;
    });
    return points;
  }, [text, gridMap, fluidity]); 

  // --- SYNC SEGMENT PRESSURES ---
  useEffect(() => {
    // Standardise: segments = activePoints.length - 1 (or 1 if single)
    const targetLen = Math.max(1, activePoints.length - 1);

    setSegmentPressures(prev => {
      if (prev.length === targetLen) return prev;
      const next = [...prev];
      if (next.length < targetLen) {
         // Add new segments
         for(let i=next.length; i<targetLen; i++) {
           next.push({ start: 15, mid: 6, end: 15 });
         }
      } else {
         return next.slice(0, targetLen);
      }
      return next;
    });
  }, [activePoints.length]);

  const updateSegment = (index: number, field: keyof SegmentPressure, value: number) => {
    setSegmentPressures(prev => {
      const copy = [...prev];
      if (copy[index]) {
        copy[index] = { ...copy[index], [field]: value };
      }
      return copy;
    });
  };

  // --- GLOBAL CONTROLS HANDLERS ---
  const updateAllNodes = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, start: value, end: value })));
  };

  const updateAllMids = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, mid: value })));
  };

  // --- PRESETS SYSTEM ---
  const applyPresetState = (p: Partial<TaelimPreset>) => {
    if (p.tension !== undefined) setTension(p.tension);
    if (p.fluidity !== undefined) setFluidity(p.fluidity);
    if (p.waveFreq !== undefined) setWaveFreq(p.waveFreq);
    if (p.waveAmp !== undefined) setWaveAmp(p.waveAmp);
    if (p.glow !== undefined) setGlow(p.glow);
    if (p.echoes !== undefined) setEchoes(p.echoes);
    if (p.echoOffset !== undefined) setEchoOffset(p.echoOffset);
    if (p.inkDensity !== undefined) setInkDensity(p.inkDensity);
    if (p.erosion !== undefined) setErosion(p.erosion);
    if (p.particles !== undefined) setParticles(p.particles);
    if (p.penAngle !== undefined) setPenAngle(p.penAngle);
    if (p.calligraphyAmount !== undefined) setCalligraphyAmount(p.calligraphyAmount);
    if (p.engine !== undefined) setEngine(p.engine);

    // Apply smart defaults for segments based on preset vibe
    let s=10, m=10, e=10;
    if (p.engine === 'pluma') { s=15; m=5; e=15; } // Classic calligraphy
    if (p.name === 'ink') { s=20; m=8; e=2; } // Tapered
    if (p.engine === 'tech') { s=3; m=3; e=3; }

    setSegmentPressures(prev => prev.map(() => ({ start: s, mid: m, end: e })));
  };

  const loadSystemPreset = (type: string) => {
    switch(type) {
      case 'ink': 
        applyPresetState({ name: 'ink', tension: 0.25, fluidity: 5, waveAmp: 0, calligraphyAmount: 90, penAngle: 30, echoes: 0, glow: 0, inkDensity: 60, erosion: 5, particles: 0, engine: 'pluma' });
        break;
      case 'calligraphy':
        applyPresetState({ name: 'calligraphy', tension: 0.2, fluidity: 0, waveAmp: 0, calligraphyAmount: 100, penAngle: 45, echoes: 0, glow: 0, inkDensity: 0, erosion: 0, particles: 0, engine: 'pluma' });
        break;
      case 'marker':
        applyPresetState({ name: 'marker', tension: 0.3, fluidity: 2, waveAmp: 0, calligraphyAmount: 10, penAngle: 90, echoes: 0, glow: 0, inkDensity: 5, erosion: 2, particles: 0, engine: 'pluma' });
        break;
      case 'liquid':
        applyPresetState({ name: 'liquid', tension: 0.5, fluidity: 0, waveFreq: 2, waveAmp: 15, calligraphyAmount: 0, echoes: 1, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 0, particles: 10, engine: 'plasma' });
        break;
      case 'tech':
        applyPresetState({ name: 'tech', tension: 0, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 2, echoOffset: 8, glow: 12, inkDensity: 0, erosion: 0, particles: 30, engine: 'tech' });
        break;
      case 'chaos':
        applyPresetState({ name: 'chaos', tension: 0.8, fluidity: 20, waveFreq: 10, waveAmp: 5, calligraphyAmount: 50, echoes: 0, glow: 8, inkDensity: 80, erosion: 15, particles: 20, engine: 'nexo' });
        break;
      case 'ghost':
        applyPresetState({ name: 'ghost', tension: 0.3, fluidity: 5, waveAmp: 5, calligraphyAmount: 0, echoes: 4, echoOffset: 15, glow: 20, inkDensity: 0, erosion: 3, particles: 10, engine: 'plasma' });
        break;
      case 'void':
        applyPresetState({ name: 'void', tension: 0.3, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 3, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 1, particles: 5, engine: 'tech' });
        break;
    }
  };

  const saveCurrentAsPreset = () => {
    if (!newPresetName || !onSavePreset) return;
    const newPreset: TaelimPreset = {
      id: crypto.randomUUID(),
      name: newPresetName,
      tension, fluidity, waveFreq, waveAmp, glow, echoes, echoOffset,
      inkDensity, erosion, particles, penAngle, calligraphyAmount, engine
    };
    onSavePreset(newPreset);
    setIsSavingPreset(false);
    setNewPresetName('');
  };


  // --- RENDER LOGIC ---
  const renderTrace = () => {
    if (activePoints.length === 0) return null;

    const splinePoints = getBezierPointsWithWeight(
      activePoints, 
      segmentPressures,
      tension, 
      20, 
      waveFreq,
      waveAmp
    );

    const paths = [];
    const baseColor = 'currentColor';

    const totalLayers = 1 + echoes;

    // Group filter for erosion
    const filterUrl = erosion > 0 ? "url(#erosion-filter)" : undefined;

    const layerPaths = [];

    for (let i = 0; i < totalLayers; i++) {
      let layerPoints = splinePoints;
      let opacity = 1;

      // Echo scaling factor
      let widthMultiplier = 1;

      if (i > 0) {
        const offset = i * echoOffset;
        layerPoints = splinePoints.map(p => ({ ...p, x: p.x + offset, y: p.y + offset }));
        opacity = 0.4 / i;
        widthMultiplier = 0.6;
      }

      // Adjust widths for echoes
      const finalLayerPoints = layerPoints.map(p => ({ ...p, w: p.w * widthMultiplier }));

      const pathData = getBrushPath(finalLayerPoints, {
        angleInfluence: calligraphyAmount / 100,
        penAngleDeg: penAngle
      });

      layerPaths.push(
        <path 
          key={`path-${i}`} 
          d={pathData} 
          fill={baseColor} 
          opacity={engine === 'tech' && i > 0 ? 0.8 : 0.8 * opacity}
          fillRule="nonzero"
        />
      );
    }

    paths.push(<g key="layers" filter={filterUrl}>{layerPaths}</g>);

    if (engine === 'tech') {
       paths.push(
         <path 
            key="wireframe"
            d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`}
            fill="none"
            stroke={baseColor}
            strokeWidth={1}
            opacity={0.5}
            strokeDasharray="4 4"
         />
       );
    }

    // Ink Density (Spatter)
    if (inkDensity > 0) {
      activePoints.forEach((p, idx) => {
        const seed = (p.x * p.y) + idx;
        const count = Math.floor((inkDensity / 10) * ((seed % 10) / 10 + 0.5)); 
        // Use approximate width at this point
        const segIdx = Math.min(idx, segmentPressures.length - 1);
        const localW = segmentPressures[segIdx] ? segmentPressures[segIdx].start : 10;

        const dots = [];
        for(let k=0; k<count; k++) {
            const angle = (seed * k) % (Math.PI * 2);
            const dist = 10 + (seed * k * 7) % 60;
            const size = (localW / 4) * (((seed + k)%10)/10);
            dots.push(
                <circle 
                    key={`spat-${idx}-${k}`} 
                    cx={p.x + Math.cos(angle)*dist} 
                    cy={p.y + Math.sin(angle)*dist} 
                    r={size} 
                    fill={baseColor} 
                    opacity={0.6} 
                />
            );
        }
        paths.push(<g key={`spats-${idx}`}>{dots}</g>);
      });
    }

    // Particles (Stardust)
    if (particles > 0) {
         activePoints.forEach((p, idx) => {
            const count = Math.floor(particles / 2);
            const dots = [];
             for(let k=0; k<count; k++) {
                const angle = (p.x * k) % (Math.PI * 2);
                const dist = 20 + (p.y * k) % 80;
                dots.push(
                    <circle 
                        key={`part-${idx}-${k}`} 
                        cx={p.x + Math.cos(angle)*dist} 
                        cy={p.y + Math.sin(angle)*dist} 
                        r={1 + (k%2)} 
                        fill={baseColor} 
                        opacity={0.4} 
                    />
                );
            }
            paths.push(<g key={`parts-${idx}`} filter="url(#neon-glow)">{dots}</g>);
         });
    }

    return <g>{paths}</g>;
  };

  const handleRandomWord = () => {
    if (terms.length > 0) setText(terms[Math.floor(Math.random() * terms.length)].root);
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();
    const scaleFactor = 3;
    const paddingBottom = exportWithMetadata ? 300 : 0;

    canvas.width = viewWidth * scaleFactor;
    canvas.height = (viewHeight * scaleFactor) + paddingBottom;

    img.onload = () => {
      if(ctx) {
        ctx.fillStyle = "#0f172a"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, viewWidth * scaleFactor, viewHeight * scaleFactor);

        if (exportWithMetadata) {
          const currentTerm = terms.find(t => t.root.toLowerCase() === text.toLowerCase());
          const displayRoot = currentTerm ? currentTerm.root : text;
          const displayMeaning = currentTerm ? currentTerm.meaning : "Trazo Libre";

          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffffff';
          ctx.font = "bold 80px 'Space Grotesk', sans-serif";
          ctx.fillText(displayRoot.toUpperCase(), canvas.width / 2, (viewHeight * scaleFactor) + 80);
          ctx.fillStyle = '#818cf8';
          ctx.font = "50px 'Space Grotesk', sans-serif";
          ctx.fillText(displayMeaning, canvas.width / 2, (viewHeight * scaleFactor) + 160);
        }

        const link = document.createElement("a");
        link.download = `LexiCosmos_${text}.png`;
        link.href = canvas.toDataURL("image/png");
        link.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const handleImportClick = () => {
    if (onImportSession && fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  return (
    <div className="max-w-[1920px] mx-auto p-4 font-sans h-[calc(100vh-140px)] lg:h-[calc(100vh-100px)]">
      <input type="file" ref={fileInputRef} onChange={onImportSession} className="hidden" accept="application/json" />

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 h-full">

        {/* --- PANEL DE CONTROLES --- */}
        <div className="xl:col-span-3 space-y-4 h-full overflow-y-auto pr-2 custom-scrollbar pb-20">
          <div className="bg-slate-900 p-5 rounded-2xl border border-slate-800 shadow-2xl">

            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
              <div className="p-2 bg-indigo-500/10 rounded-lg text-indigo-400">
                <PenTool size={20} />
              </div>
              <div>
                <h2 className="text-lg font-bold text-white">Tael'im V5</h2>
                <p className="text-slate-500 text-[10px] uppercase tracking-widest">Master Calligraphy</p>
              </div>
            </div>

            {/* Input */}
            <div className="space-y-4 mb-6">
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-700 rounded-lg px-4 py-3 text-white focus:border-indigo-500 outline-none text-xl font-bold font-mono tracking-widest uppercase"
                  placeholder="PALABRA..."
                />
                <button onClick={handleRandomWord} className="px-3 bg-slate-800 hover:bg-slate-700 text-slate-400 rounded-lg border border-slate-700"><Dice5 size={20}/></button>
              </div>
              <div className="grid grid-cols-2 gap-2">
                  {(['algante', 'comun'] as GridMode[]).map((m) => (
                    <button key={m} onClick={() => setMode(m)} className={`py-1.5 px-3 rounded border text-[10px] font-bold uppercase tracking-wider ${mode === m ? 'bg-indigo-600/20 border-indigo-500 text-indigo-300' : 'bg-slate-950 border-slate-800 text-slate-500'}`}>{m}</button>
                  ))}
              </div>
            </div>

            {/* PRESETS */}
            <div className="mb-6">
               <div className="flex justify-between items-end mb-2">
                 <label className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-2"><Wand2 size={12}/> Estilos</label>
                 <div className="flex gap-2">
                    <button onClick={handleImportClick} className="text-[10px] text-emerald-400 hover:text-emerald-300 flex items-center gap-1" title="Cargar sesión completa"><Upload size={10}/> Cargar</button>
                    <button onClick={() => setIsSavingPreset(!isSavingPreset)} className="text-[10px] text-indigo-400 hover:text-indigo-300 flex items-center gap-1"><Save size={10}/> Guardar</button>
                 </div>
               </div>

               {isSavingPreset && (
                 <div className="flex gap-2 mb-2 animate-fade-in">
                   <input type="text" value={newPresetName} onChange={e => setNewPresetName(e.target.value)} placeholder="Nombre del estilo" className="flex-1 bg-slate-950 border border-slate-700 rounded text-xs px-2 py-1 text-white" />
                   <button onClick={saveCurrentAsPreset} className="bg-indigo-600 px-2 rounded text-white text-xs">OK</button>
                 </div>
               )}

               <div className="grid grid-cols-4 gap-1.5 mb-2">
                 {['ink', 'calligraphy', 'marker', 'liquid', 'tech', 'chaos', 'ghost', 'void'].map(p => (
                   <button key={p} onClick={() => loadSystemPreset(p)} className="bg-slate-800 hover:bg-slate-700 border border-slate-700 rounded py-1 text-[9px] text-slate-300 capitalize truncate px-1">{p}</button>
                 ))}
               </div>

               {/* Custom Presets */}
               {customPresets && customPresets.length > 0 && (
                 <>
                   <label className="text-[9px] font-bold text-slate-600 uppercase mb-1 block mt-2">Mis Estilos</label>
                   <div className="flex flex-wrap gap-1.5">
                     {customPresets.map(p => (
                       <div key={p.id} className="group relative flex items-center">
                         <button onClick={() => applyPresetState(p)} className="bg-indigo-900/30 hover:bg-indigo-900/50 border border-indigo-800 rounded py-1 pl-2 pr-4 text-[9px] text-indigo-200 capitalize truncate">{p.name}</button>
                         <button onClick={() => onDeletePreset && onDeletePreset(p.id)} className="absolute right-1 text-indigo-400 hover:text-red-400 opacity-0 group-hover:opacity-100"><X size={10}/></button>
                       </div>
                     ))}
                   </div>
                 </>
               )}
            </div>

            <hr className="border-slate-800 mb-6" />

             {/* --- PRESIÓN POR SEGMENTO (3 PUNTOS) --- */}
             <div className="space-y-4 mb-6">
               <div className="flex items-center justify-between text-indigo-400 mb-2">
                 <div className="flex items-center gap-2">
                    <Activity size={16} />
                    <span className="text-xs font-bold uppercase tracking-wider">Grosor por Trazo</span>
                 </div>
               </div>

               {/* GLOBAL CONTROLS */}
               {activePoints.length > 0 && (
                 <div className="bg-indigo-950/20 border border-indigo-900/50 rounded-lg p-2 mb-3">
                   <div className="flex items-center gap-2 mb-1">
                     <Layers size={12} className="text-indigo-400" />
                     <span className="text-[9px] font-bold text-indigo-300 uppercase">Controles Maestros</span>
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                     <div>
                       <label className="text-[8px] text-slate-400 block mb-1">Grosor Nodos (Todos)</label>
                       <input type="range" min="1" max="50" step="0.5" className="w-full h-1 bg-slate-800 rounded appearance-none accent-indigo-400" 
                         onChange={(e) => updateAllNodes(Number(e.target.value))} />
                     </div>
                     <div>
                       <label className="text-[8px] text-slate-400 block mb-1">Grosor Trazos (Todos)</label>
                       <input type="range" min="1" max="50" step="0.5" className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-400" 
                         onChange={(e) => updateAllMids(Number(e.target.value))} />
                     </div>
                   </div>
                 </div>
               )}

               {activePoints.length === 0 ? (
                 <p className="text-xs text-slate-600 italic">Escribe una palabra para ver los puntos de control.</p>
               ) : (
                 <div className="space-y-3 max-h-[350px] overflow-y-auto pr-2 custom-scrollbar bg-slate-950/30 p-3 rounded-lg border border-slate-800">

                   {/* SPECIAL CASE: Single Point */}
                   {activePoints.length === 1 && segmentPressures.length > 0 && (
                      <div className="bg-slate-900/50 p-2 rounded border border-slate-800/50">
                        <div className="flex items-center justify-between mb-2">
                           <span className="text-[10px] font-bold text-indigo-400 bg-indigo-500/10 px-1.5 rounded">{activePoints[0].char}</span>
                           <span className="text-[9px] text-slate-500">Punto Único</span>
                        </div>
                        <div className="flex items-center gap-2">
                             <span className="text-[8px] text-slate-400 w-8 uppercase">Grosor Base</span>
                             <input 
                                 type="range" min="1" max="50" step="0.5" 
                                 value={segmentPressures[0].start} 
                                 onChange={(e) => updateSegment(0, 'start', Number(e.target.value))}
                                 className="flex-1 h-1 bg-slate-800 rounded appearance-none accent-indigo-500" 
                             />
                        </div>
                      </div>
                   )}

                   {/* Standard Segments */}
                   {activePoints.length > 1 && segmentPressures.map((seg, idx) => {
                     const charStart = activePoints[idx]?.char || '?';
                     const charEnd = activePoints[idx+1]?.char || '?';

                     return (
                      <div key={idx} className="bg-slate-900/50 p-2 rounded border border-slate-800/50">
                        <div className="flex items-center justify-between mb-2">
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] font-bold text-indigo-400 bg-indigo-500/10 px-1.5 rounded">{charStart}</span>
                                <ArrowRight size={10} className="text-slate-600" />
                                <span className="text-[10px] font-bold text-emerald-400 bg-emerald-500/10 px-1.5 rounded">{charEnd}</span>
                            </div>
                            <span className="text-[9px] text-slate-500">Trazo {idx + 1}</span>
                        </div>

                        <div className="space-y-1">
                            {/* Inicio */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-400 w-8 uppercase">Inicio ({charStart})</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.start} 
                                    onChange={(e) => updateSegment(idx, 'start', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded appearance-none accent-indigo-500" 
                                />
                            </div>
                            {/* Centro */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-400 w-8 uppercase">Centro</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.mid} 
                                    onChange={(e) => updateSegment(idx, 'mid', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded appearance-none accent-slate-400" 
                                />
                            </div>
                            {/* Final */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-400 w-8 uppercase">Final ({charEnd})</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.end} 
                                    onChange={(e) => updateSegment(idx, 'end', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded appearance-none accent-emerald-500" 
                                />
                            </div>
                        </div>
                      </div>
                     );
                   })}
                 </div>
               )}

               <div className="pt-2">
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Influencia Ángulo Pluma</span> <span>{calligraphyAmount}%</span></div>
                  <input type="range" min="0" max="100" value={calligraphyAmount} onChange={(e) => setCalligraphyAmount(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-indigo-500" />
               </div>

               <div className={calligraphyAmount === 0 ? 'opacity-30' : ''}>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Rotación Pluma</span> <span>{penAngle}°</span></div>
                  <input type="range" min="0" max="180" value={penAngle} onChange={(e) => setPenAngle(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-indigo-500" />
               </div>
            </div>


            {/* --- GEOMETRÍA & MOVIMIENTO --- */}
            <div className="space-y-4 mb-6">
               <div className="flex items-center gap-2 text-emerald-400 mb-2">
                 <Move size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Geometría & Movimiento</span>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1">
                    <span>Tensión de Curva</span> 
                    <span>{tension.toFixed(2)}</span>
                  </div>
                  <input type="range" min="0" max="1" step="0.01" value={tension} onChange={(e) => setTension(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-500" />
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1">
                    <span>Fluidez (Caos de Nodos)</span> 
                    <span>{fluidity}</span>
                  </div>
                  <input type="range" min="0" max="40" value={fluidity} onChange={(e) => setFluidity(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-500" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Frec. Onda</label>
                    <input type="range" min="0" max="20" step="0.5" value={waveFreq} onChange={e => setWaveFreq(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-400" />
                 </div>
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Amplitud Onda</label>
                    <input type="range" min="0" max="40" value={waveAmp} onChange={e => setWaveAmp(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-emerald-400" />
                 </div>
               </div>
            </div>

            {/* --- FLORITURAS & FX --- */}
            <div className="space-y-4">
               <div className="flex items-center gap-2 text-amber-400 mb-2">
                 <Droplets size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Florituras & FX</span>
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Densidad Tinta (Salpicaduras)</span> <span>{inkDensity}%</span></div>
                 <input type="range" min="0" max="100" value={inkDensity} onChange={(e) => setInkDensity(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Erosión (Textura)</span> <span>{erosion}</span></div>
                 <input type="range" min="0" max="20" step="0.5" value={erosion} onChange={(e) => setErosion(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Partículas (Polvo)</span> <span>{particles}</span></div>
                 <input type="range" min="0" max="50" value={particles} onChange={(e) => setParticles(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Ecos ({echoes})</label>
                    <input type="range" min="0" max="10" step="1" value={echoes} onChange={e => setEchoes(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
                 </div>
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1">Offset Eco</label>
                    <input type="range" min="0" max="100" value={echoOffset} onChange={e => setEchoOffset(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
                 </div>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1"><span>Resplandor (Glow)</span> <span>{glow}</span></div>
                  <input type="range" min="0" max="50" value={glow} onChange={(e) => setGlow(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded appearance-none accent-amber-500" />
               </div>
            </div>

          </div>
        </div>

        {/* --- VISUALIZADOR --- */}
        <div className="xl:col-span-9 flex flex-col h-full relative">

           <div className="absolute top-6 right-6 z-20 flex gap-2 bg-slate-900/90 backdrop-blur border border-slate-700/50 p-2 rounded-xl shadow-2xl">
             <button onClick={() => setShowGuides(!showGuides)} className={`p-2 rounded-lg transition-colors border ${showGuides ? 'bg-indigo-600/20 text-indigo-300 border-indigo-500/50' : 'bg-slate-800 text-slate-500 border-transparent'}`} title="Guías"><Eye size={18} /></button>
             <button onClick={() => setExportWithMetadata(!exportWithMetadata)} className={`p-2 rounded-lg transition-colors border ${exportWithMetadata ? 'bg-emerald-600/20 text-emerald-300 border-emerald-500/50' : 'bg-slate-800 text-slate-500 border-transparent'}`} title="Metadatos"><FileText size={18} /></button>
             <div className="w-px h-6 bg-slate-700 my-auto mx-1"></div>
             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-400 hover:text-white"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.0, z + 0.1))} className="p-2 text-slate-400 hover:text-white"><ZoomIn size={18} /></button>
             <button onClick={handleDownload} className="flex items-center gap-2 px-3 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg ml-2 font-medium text-sm shadow-lg shadow-indigo-500/20"><Download size={16} /> Exportar</button>
           </div>

           <div className="flex-1 bg-slate-950 rounded-2xl border border-slate-800 overflow-hidden relative flex items-center justify-center shadow-inner">
             <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-indigo-900/5 via-slate-950 to-slate-950 pointer-events-none"></div>
             <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar p-10">
               <div style={{ width: viewWidth, height: viewHeight, transform: `scale(${zoom})`, transition: 'transform 0.3s ease-out' }}>
                 <svg ref={svgRef} viewBox={`0 0 ${viewWidth} ${viewHeight}`} className="w-full h-full drop-shadow-2xl overflow-visible">
                    <defs>
                      <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                        <feMerge>
                          <feMergeNode in="coloredBlur" />
                          <feMergeNode in="SourceGraphic" />
                        </feMerge>
                      </filter>
                      <filter id="erosion-filter" x="-20%" y="-20%" width="140%" height="140%">
                        <feTurbulence type="fractalNoise" baseFrequency="0.05" numOctaves="3" result="noise" />
                        <feDisplacementMap in="SourceGraphic" in2="noise" scale={erosion} />
                      </filter>
                    </defs>

                    {/* Guías */}
                    {showGuides && (
                      <g className="opacity-20 pointer-events-none">
                        {currentGrid.map((row, y) => row.map((char, x) => (
                           <g key={`${x}-${y}`}>
                             <circle cx={PADDING + x * CELL_SIZE} cy={PADDING + y * CELL_SIZE} r={2} fill="#64748b" />
                             <text x={PADDING + x * CELL_SIZE} y={PADDING + y * CELL_SIZE + 40} textAnchor="middle" fill="#64748b" fontSize="10" fontFamily="monospace" opacity={0.5}>{char}</text>
                           </g>
                        )))}
                      </g>
                    )}

                    {/* Nodos Activos */}
                    {showGuides && activePoints.map((p, i) => (
                      <g key={i}>
                        <circle cx={p.x} cy={p.y} r={4} fill={mode === 'algante' ? '#818cf8' : '#34d399'} opacity={0.8} />
                        <line x1={p.originalX} y1={p.originalY} x2={p.x} y2={p.y} stroke="white" strokeWidth="1" strokeDasharray="2 2" opacity="0.3" />
                        <text x={p.x} y={p.y - 15} textAnchor="middle" fill="white" fontSize="12" fontWeight="bold">{p.char}</text>
                      </g>
                    ))}

                    {/* TRAZO PRINCIPAL */}
                    <g filter={glow > 0 ? "url(#neon-glow)" : ""} className={mode === 'algante' ? 'text-indigo-400' : 'text-emerald-400'}>
                      {renderTrace()}
                    </g>
                 </svg>
               </div>
             </div>
           </div>

        </div>
      </div>
    </div>
  );
};

export default Taelim;

