import React, { useMemo } from 'react';

// Grid Configuration (Algante Standard)
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

interface Props {
  root: string;
  className?: string;
  strokeColor?: string;
}

const MiniTaelim: React.FC<Props> = ({ root, className = "", strokeColor = "currentColor" }) => {
  // Precompute Map for performance
  const gridMap = useMemo(() => {
    const map = new Map<string, {x: number, y: number}>();
    ALGANTE_GRID.forEach((row, y) => {
      row.forEach((char, x) => {
        // Normalize coordinates to a 0-100 range for SVG viewbox
        // Grid is 6 cols (0-5), 4 rows (0-3).
        // X: (x / 5) * 100
        // Y: (y / 3) * 100
        map.set(char, { x: (x / 5) * 100, y: (y / 3) * 100 });
      });
    });
    return map;
  }, []);

  const points = useMemo(() => {
    const cleanRoot = root.toUpperCase().replace(/[^A-Z]/g, '');
    const pts: {x: number, y: number}[] = [];

    cleanRoot.split('').forEach(char => {
      const pos = gridMap.get(char);
      if (pos) {
        // Add some padding/margin to not hit the exact edges (10% padding)
        pts.push({ 
          x: 10 + (pos.x * 0.8), 
          y: 10 + (pos.y * 0.8) 
        });
      }
    });
    return pts;
  }, [root, gridMap]);

  if (points.length === 0) return null;

  // Generate Path Data
  const pathD = points.map((p, i) => 
    `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`
  ).join(' ');

  return (
    <div className={`relative ${className}`} title={`Patrón Tael'im: ${root}`}>
       <svg viewBox="0 0 100 100" className="w-full h-full overflow-visible">
          {/* Background Grid Dots (Optional, very subtle) */}
          <g className="opacity-10 text-slate-500 fill-current">
             {ALGANTE_GRID.flat().map((_, i) => {
                 const x = 10 + ((i % 6) / 5) * 80;
                 const y = 10 + (Math.floor(i / 6) / 3) * 80;
                 return <circle key={i} cx={x} cy={y} r={1.5} />;
             })}
          </g>

          {/* Connection Line */}
          <path 
            d={pathD} 
            fill="none" 
            stroke={strokeColor} 
            strokeWidth="3" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className="drop-shadow-[0_0_3px_rgba(129,140,248,0.5)]"
          />

          {/* Nodes */}
          {points.map((p, i) => (
            <circle 
              key={i} 
              cx={p.x} 
              cy={p.y} 
              r={i === 0 ? 5 : 3} // Start point slightly larger
              className={i === 0 ? "fill-white" : "fill-indigo-300"}
            />
          ))}
       </svg>
    </div>
  );
};

export default MiniTaelim;

import React, { useState, useMemo, useEffect } from 'react';
import { Term, CATEGORIES, Tonality } from '../types';
import { Search, Filter, GitCompare, X, Edit2, Save } from 'lucide-react';
import MiniTaelim from './MiniTaelim';

interface Props {
  terms: Term[];
  onUpdateTerm: (term: Term) => void;
}

const GlossaryList: React.FC<Props> = ({ terms, onUpdateTerm }) => {
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [tonalityFilter, setTonalityFilter] = useState('');
  const [compareList, setCompareList] = useState<string[]>([]);
  const [showCompareModal, setShowCompareModal] = useState(false);

  // Edit State
  const [editingTerm, setEditingTerm] = useState<Term | null>(null);
  const [editRoot, setEditRoot] = useState('');
  const [editMeaning, setEditMeaning] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editTonality, setEditTonality] = useState<Tonality>(Tonality.NEUTRAL);
  const [editSyllables, setEditSyllables] = useState(1);

  const filteredTerms = useMemo(() => {
    return terms.filter(t => {
      const matchesSearch = t.root.toLowerCase().includes(search.toLowerCase()) || 
                            t.meaning.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = categoryFilter ? t.category === categoryFilter : true;
      const matchesTonality = tonalityFilter ? t.tonality === tonalityFilter : true;
      return matchesSearch && matchesCategory && matchesTonality;
    });
  }, [terms, search, categoryFilter, tonalityFilter]);

  const toggleCompare = (id: string) => {
    setCompareList(prev => {
      if (prev.includes(id)) return prev.filter(p => p !== id);
      if (prev.length < 2) return [...prev, id];
      return [prev[1], id]; // Keep only 2, remove oldest
    });
  };

  const handleEditClick = (term: Term) => {
    setEditingTerm(term);
    setEditRoot(term.root);
    setEditMeaning(term.meaning);
    setEditDescription(term.description);
    setEditCategory(term.category);
    setEditTonality(term.tonality);
    setEditSyllables(term.syllables);
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTerm) return;

    const updatedTerm: Term = {
      ...editingTerm,
      root: editRoot,
      meaning: editMeaning,
      description: editDescription,
      category: editCategory,
      tonality: editTonality,
      syllables: editSyllables
    };

    onUpdateTerm(updatedTerm);
    setEditingTerm(null);
  };

  const getTonalityColor = (t: Tonality) => {
    switch (t) {
      case Tonality.POSITIVE: return 'text-green-400 border-green-400/30 bg-green-400/10';
      case Tonality.NEGATIVE: return 'text-red-400 border-red-400/30 bg-red-400/10';
      case Tonality.TRANSFORMATIVE: return 'text-purple-400 border-purple-400/30 bg-purple-400/10';
      case Tonality.NEUTRAL: return 'text-slate-400 border-slate-400/30 bg-slate-400/10';
      default: return 'text-amber-400 border-amber-400/30 bg-amber-400/10';
    }
  };

  const comparedTerms = terms.filter(t => compareList.includes(t.id));

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {/* Controls */}
      <div className="flex flex-col xl:flex-row gap-4 mb-8 bg-slate-800 p-4 rounded-xl border border-slate-700 shadow-lg">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-3 text-slate-500" size={20} />
          <input 
            type="text" 
            placeholder="Buscar concepto o significado..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full bg-slate-900 border border-slate-700 rounded-lg pl-10 pr-4 py-2.5 text-white focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none"
          />
        </div>

        <div className="flex flex-col sm:flex-row gap-4">
          <div className="relative">
            <Filter className="absolute left-3 top-3 text-slate-500" size={18} />
            <select 
              value={categoryFilter} 
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="bg-slate-900 border border-slate-700 rounded-lg pl-10 pr-8 py-2.5 text-slate-300 outline-none appearance-none cursor-pointer hover:bg-slate-800 w-full sm:w-auto"
            >
              <option value="">Todas las categorías</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <select 
            value={tonalityFilter}
            onChange={(e) => setTonalityFilter(e.target.value)}
            className="bg-slate-900 border border-slate-700 rounded-lg px-4 py-2.5 text-slate-300 outline-none cursor-pointer hover:bg-slate-800 w-full sm:w-auto"
          >
            <option value="">Cualquier tonalidad</option>
            {Object.values(Tonality).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        {compareList.length > 0 && (
          <button 
            onClick={() => setShowCompareModal(true)}
            className="flex items-center justify-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-6 py-2.5 rounded-lg transition-colors"
          >
            <GitCompare size={18} />
            <span>Comparar ({compareList.length})</span>
          </button>
        )}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredTerms.map(term => (
          <div key={term.id} className="group bg-slate-800/50 hover:bg-slate-800 border border-slate-700 hover:border-indigo-500/50 rounded-xl p-6 transition-all duration-300 relative overflow-hidden flex flex-col h-full">

            {/* Action Buttons (Edit + Compare) */}
            <div className="absolute top-4 right-4 z-10 flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <button 
                onClick={() => handleEditClick(term)}
                className="p-1.5 rounded-md bg-slate-700 hover:bg-indigo-600 text-slate-300 hover:text-white transition-colors border border-slate-600 hover:border-indigo-500"
                title="Editar Radical"
              >
                <Edit2 size={14} />
              </button>
              <input 
                type="checkbox" 
                checked={compareList.includes(term.id)}
                onChange={() => toggleCompare(term.id)}
                className="w-5 h-5 rounded border-slate-600 bg-slate-700 text-indigo-600 focus:ring-indigo-500 cursor-pointer"
                title="Seleccionar para comparar"
              />
            </div>

            <div className="flex items-baseline gap-2 mb-2 pr-16">
              <h2 className="text-2xl font-bold text-white tracking-wide">{term.root}</h2>
