import React, { useMemo } from 'react';

// Grid Configuration (Algante Standard)
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

// Grid Configuration (Común Standard)
const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

interface Props {
  root: string;
  className?: string;
  strokeColor?: string;
  mode?: 'algante' | 'comun';
}

const MiniTaelim: React.FC<Props> = ({ root, className = "", strokeColor = "currentColor", mode = 'algante' }) => {

  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;

  // Precompute Map for performance
  const gridMap = useMemo(() => {
    const map = new Map<string, {x: number, y: number}>();
    const rows = currentGrid.length;
    const cols = currentGrid[0].length;

    currentGrid.forEach((row, y) => {
      row.forEach((char, x) => {
        // Normalize coordinates to a 0-100 range for SVG viewbox
        // Use (cols - 1) and (rows - 1) to ensure points hit the edges properly if needed,
        // but we usually want some padding handled in the points calculation.
        map.set(char, { 
          x: (x / (cols - 1)) * 100, 
          y: (y / (rows - 1)) * 100 
        });
      });
    });
    return map;
  }, [currentGrid]);

  const points = useMemo(() => {
    const cleanRoot = root.toUpperCase().replace(/[^A-Z]/g, '');
    const pts: {x: number, y: number}[] = [];

    cleanRoot.split('').forEach(char => {
      const pos = gridMap.get(char);
      if (pos) {
        // Add 15% padding/margin to keep it centered and not touching borders
        pts.push({ 
          x: 15 + (pos.x * 0.7), 
          y: 15 + (pos.y * 0.7) 
        });
      }
    });
    return pts;
  }, [root, gridMap]);

  if (points.length === 0) return null;

  // Generate Path Data
  const pathD = points.map((p, i) => 
    `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`
  ).join(' ');

  // Calculate dots for background grid
  const gridDots = useMemo(() => {
    const dots: {x: number, y: number}[] = [];
    const rows = currentGrid.length;
    const cols = currentGrid[0].length;

    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        dots.push({
          x: 15 + ((x / (cols - 1)) * 100) * 0.7,
          y: 15 + ((y / (rows - 1)) * 100) * 0.7
        });
      }
    }
    return dots;
  }, [currentGrid]);

  return (
    <div className={`relative ${className}`} title={`Patrón ${mode === 'algante' ? 'Algante' : 'Común'}: ${root}`}>
       <svg viewBox="0 0 100 100" className="w-full h-full overflow-visible">
          {/* Background Grid Dots */}
          <g className="opacity-10 text-slate-500 fill-current">
             {gridDots.map((d, i) => (
                 <circle key={i} cx={d.x} cy={d.y} r={1.5} />
             ))}
          </g>

          {/* Connection Line */}
          <path 
            d={pathD} 
            fill="none" 
            stroke={strokeColor} 
            strokeWidth="3" 
            strokeLinecap="round" 
            strokeLinejoin="round"
            className="drop-shadow-[0_0_3px_rgba(255,255,255,0.2)]"
          />

          {/* Nodes */}
          {points.map((p, i) => (
            <circle 
              key={i} 
              cx={p.x} 
              cy={p.y} 
              r={i === 0 ? 5 : 3} // Start point slightly larger
              fill={strokeColor}
              className="opacity-80"
            />
          ))}
       </svg>
    </div>
  );
};

