      const matchesSearch = t.root.toLowerCase().includes(search.toLowerCase()) || 
                            t.meaning.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = categoryFilter ? t.category === categoryFilter : true;
      const matchesTonality = tonalityFilter ? t.tonality === tonalityFilter : true;
      return matchesSearch && matchesCategory && matchesTonality;
