                  <div className="border-2 border-dashed border-slate-700 rounded-xl flex items-center justify-center p-12 text-slate-600">
                    Selecciona otro término para comparar
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

