                   title="Ver patrón Algante"
                 >
                    <div className="absolute top-0.5 right-0.5 opacity-0 group-hover/glyph:opacity-100 bg-black/50 rounded text-indigo-200"><Maximize2 size={10}/></div>
                    <MiniTaelim root={term.root} mode="algante" strokeColor="#818cf8" />
