                   title="Ver patrón Común"
                 >
                    <div className="absolute top-0.5 right-0.5 opacity-0 group-hover/glyph:opacity-100 bg-black/50 rounded text-emerald-200"><Maximize2 size={10}/></div>
                    <MiniTaelim root={term.root} mode="comun" strokeColor="#34d399" />
