  useEffect(() => {
    const loadData = () => {
      try {
        const storedJson = localStorage.getItem(STORAGE_KEY);
        // Fallback checks
        const oldJsonV2 = localStorage.getItem('lexicosmos_data_v2');
        const oldJsonV1 = localStorage.getItem('lexicosmos_data');

        let loadedTerms: Term[] = [];
        let loadedPresets: TaelimPreset[] = [];

        if (storedJson) {
          const data = JSON.parse(storedJson) as LexiData;
          loadedTerms = data.terms || [];
          loadedPresets = data.presets || [];
        } else if (oldJsonV2) {
          // Migration V2 -> V3
          loadedTerms = JSON.parse(oldJsonV2);
        } else if (oldJsonV1) {
          // Migration V1 -> V3
          loadedTerms = JSON.parse(oldJsonV1);
        }

        // Merge initial static data if missing
        const localMap = new Map(loadedTerms.map(t => [t.root.toLowerCase(), t]));
        const mergedTerms = [...loadedTerms];

        initialData.forEach(staticTerm => {
          if (!localMap.has(staticTerm.root.toLowerCase())) {
            mergedTerms.push(staticTerm);
          }
        });

        // Sort by Root A-Z
        mergedTerms.sort((a, b) => a.root.localeCompare(b.root));

        setTerms(mergedTerms);
        setPresets(loadedPresets);

      } catch (e) {
        console.error("Failed to load/merge data", e);
        setTerms(initialData);
      } finally {
        setIsLoading(false);
      }
    };

    loadData();
  }, []);

  // Persist data on change
  useEffect(() => {
    if (!isLoading) {
      const dataToSave: LexiData = {
        version: 3,
        terms: terms,
        presets: presets
      };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(dataToSave));
    }
  }, [terms, presets, isLoading]);

  const addTerm = (term: Term) => {
    setTerms(prev => {
      const updated = [term, ...prev];
      updated.sort((a, b) => a.root.localeCompare(b.root));
      return updated;
    });
    alert(`Radical "${term.root}" guardado exitosamente.`);
    setActiveTab('glossary'); 
  };

  const updateTerm = (updatedTerm: Term) => {
    setTerms(prev => prev.map(t => t.id === updatedTerm.id ? updatedTerm : t));
  };

  // Handlers for Taelim Presets
  const handleSavePreset = (preset: TaelimPreset) => {
    setPresets(prev => [...prev, preset]);
  };

  const handleDeletePreset = (id: string) => {
    setPresets(prev => prev.filter(p => p.id !== id));
  };

  const handleExport = () => {
    const data: LexiData = {
      version: 3,
      terms: terms,
      presets: presets
    };
    const dataStr = JSON.stringify(data, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `glosario_transversal_backup_${new Date().toISOString().slice(0, 10)}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = event.target?.result as string;
        const parsed = JSON.parse(json);

        let newTerms: Term[] = [];
        let newPresets: TaelimPreset[] = [];

        // Detect format
        if (Array.isArray(parsed)) {
          // Old format (Array of terms)
          newTerms = parsed;
        } else if (parsed.terms) {
          // New format
          newTerms = parsed.terms;
          newPresets = parsed.presets || [];
        } else {
           throw new Error("Formato desconocido");
        }

        if (confirm(`Se han detectado ${newTerms.length} términos y ${newPresets.length} presets de estilos. ¿Deseas reemplazar la sesión actual?`)) {
          setTerms(newTerms);
          setPresets(newPresets);
          alert("Sesión restaurada correctamente.");
        }
      } catch (error) {
        alert("Error al importar el archivo. Asegúrate de que es un JSON válido.");
        console.error(error);
      }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#020617] flex flex-col items-center justify-center text-cyan-400 gap-4">
        <div className="w-12 h-12 border border-cyan-500/30 border-t-cyan-400 rounded-none animate-spin"></div>
        <p className="animate-pulse font-mono uppercase tracking-widest text-xs">Inicializando Protocolos...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-transparent text-slate-300 font-sans selection:bg-cyan-500/30 selection:text-cyan-100 overflow-hidden flex flex-col">
      <Navigation 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        onExport={handleExport}
        onImport={handleImport}
      />

      {/* 
        Main content wrapper with overflow-auto. 
        Using display:none preserves component state when switching tabs.
      */}
      <main className="flex-1 overflow-y-auto container mx-auto py-8 px-4 relative custom-scrollbar">
        <div className={activeTab === 'glossary' ? 'block animate-fade-in' : 'hidden'}>
          <GlossaryList terms={terms} onUpdateTerm={updateTerm} />
        </div>

        <div className={activeTab === 'stats' ? 'block animate-fade-in' : 'hidden'}>
          <StatsDashboard terms={terms} />
        </div>

        <div className={activeTab === 'constructor' ? 'block animate-fade-in' : 'hidden'}>
          <Constructor onAddTerm={addTerm} />
        </div>

        <div className={activeTab === 'taelim' ? 'block h-full animate-fade-in' : 'hidden'}>
           <Taelim 
             terms={terms} 
             customPresets={presets}
             onSavePreset={handleSavePreset}
             onDeletePreset={handleDeletePreset}
             onImportSession={handleImport}
           />
        </div>
      </main>

      <footer className="flex justify-between items-center px-6 py-2 text-slate-600 text-[10px] uppercase tracking-widest bg-[#020617] border-t border-slate-800">
        <p>Sistema Operativo Transversal // Build 3.0.1</p>
        <div className="flex gap-2">
            <span className="text-emerald-500">● ONLINE</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef } from 'react';
import { Term, CATEGORIES, Tonality } from '../types';
import { Search, Filter, GitCompare, X, Edit2, Save, Maximize2, Download, Terminal } from 'lucide-react';
import MiniTaelim from './MiniTaelim';

interface Props {
  terms: Term[];
  onUpdateTerm: (term: Term) => void;
}

interface GlyphModalState {
  term: Term;
  mode: 'algante' | 'comun';
}

const GlossaryList: React.FC<Props> = ({ terms, onUpdateTerm }) => {
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [tonalityFilter, setTonalityFilter] = useState('');
  const [compareList, setCompareList] = useState<string[]>([]);
  const [showCompareModal, setShowCompareModal] = useState(false);

  // Glyph Detail Modal State
  const [viewingGlyph, setViewingGlyph] = useState<GlyphModalState | null>(null);
  const glyphRef = useRef<HTMLDivElement>(null);

  // Edit State
  const [editingTerm, setEditingTerm] = useState<Term | null>(null);
  const [editRoot, setEditRoot] = useState('');
  const [editMeaning, setEditMeaning] = useState('');
  const [editDescription, setEditDescription] = useState('');
  const [editCategory, setEditCategory] = useState('');
  const [editTonality, setEditTonality] = useState<Tonality>(Tonality.NEUTRAL);
  const [editSyllables, setEditSyllables] = useState(1);

  const filteredTerms = useMemo(() => {
    return terms.filter(t => {
      const matchesSearch = t.root.toLowerCase().includes(search.toLowerCase()) || 
                            t.meaning.toLowerCase().includes(search.toLowerCase());
      const matchesCategory = categoryFilter ? t.category === categoryFilter : true;
      const matchesTonality = tonalityFilter ? t.tonality === tonalityFilter : true;
      return matchesSearch && matchesCategory && matchesTonality;
    });
  }, [terms, search, categoryFilter, tonalityFilter]);

  const toggleCompare = (id: string) => {
    setCompareList(prev => {
      if (prev.includes(id)) return prev.filter(p => p !== id);
      if (prev.length < 2) return [...prev, id];
      return [prev[1], id]; // Keep only 2, remove oldest
    });
  };

  const handleEditClick = (term: Term) => {
    setEditingTerm(term);
    setEditRoot(term.root);
    setEditMeaning(term.meaning);
    setEditDescription(term.description);
    setEditCategory(term.category);
    setEditTonality(term.tonality);
    setEditSyllables(term.syllables);
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTerm) return;

    const updatedTerm: Term = {
      ...editingTerm,
      root: editRoot,
      meaning: editMeaning,
      description: editDescription,
      category: editCategory,
      tonality: editTonality,
