  const handleDownloadGlyph = () => {
    if (!glyphRef.current || !viewingGlyph) return;

    const svgElement = glyphRef.current.querySelector('svg');
    if (!svgElement) return;

    // Serialize SVG
    const svgData = new XMLSerializer().serializeToString(svgElement);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    // High res export
    const size = 1000; 
    canvas.width = size;
    canvas.height = size;

    img.onload = () => {
      if(ctx) {
        // Dark background for contrast
        ctx.fillStyle = "#020617"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Center image
        ctx.drawImage(img, 0, 0, size, size);

        // Metadata footer
        ctx.font = "bold 40px 'Space Grotesk', sans-serif";
        ctx.fillStyle = viewingGlyph.mode === 'algante' ? '#22d3ee' : '#34d399';
        ctx.textAlign = 'center';
        ctx.fillText(viewingGlyph.term.root.toUpperCase(), size / 2, size - 100);

        ctx.font = "30px 'Space Grotesk', sans-serif";
        ctx.fillStyle = '#94a3b8';
        ctx.fillText(viewingGlyph.term.meaning, size / 2, size - 50);

        const link = document.createElement("a");
        link.download = `Glosario_${viewingGlyph.term.root}_${viewingGlyph.mode}.png`;
        link.href = canvas.toDataURL("image/png");
        link.click();
