                  >
                    Abortar
                   </button>
                   <button 
                    type="submit"
                    className="px-6 py-2 bg-cyan-700 hover:bg-cyan-600 text-white font-bold uppercase tracking-widest text-xs flex items-center gap-2 border border-cyan-500"
