// --- CONFIGURACIÓN DE LOS GRIDS ---
const ALGANTE_GRID: string[][] = [
  ['P', 'V', 'U', 'Y', 'M', 'B'],
  ['F', 'R', 'E', 'A', 'D', 'C'],
  ['H', 'N', 'I', 'L', 'Z', 'Q'],
  ['K', 'S', 'O', 'T', 'G', 'J']
];

const COMUN_GRID: string[][] = [
  ['B', 'L', 'A', 'V'],
  ['C', 'N', 'E', 'S'],
  ['D', 'R', 'I', 'T'],
  ['F', 'M', 'O', 'Z'],
  ['G', 'K', 'U', 'H'],
  ['J', 'P', 'Y', 'K'] 
];

// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY MATH HELPERS ---
const getDistance = (p1: {x:number, y:number}, p2: {x:number, y:number}) => 
  Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));

const getControlPoint = (
  current: {x:number, y:number}, 
  previous: {x:number, y:number}, 
  next: {x:number, y:number}, 
  reverse: boolean,
  tension: number
) => {
  const p = previous || current;
  const n = next || current;
  const smoothing = tension;

  const o = {
    x: n.x - p.x + (n.x - current.x),
    y: n.y - p.y + (n.y - current.y)
  };

  const angle = Math.atan2(o.y, o.x) + (reverse ? Math.PI : 0);
  const length = getDistance(current, n) * smoothing;

  return {
    x: current.x + Math.cos(angle) * length,
    y: current.y + Math.sin(angle) * length
  };
};

// Smoothstep function for organic width transition
const smoothStep = (t: number) => {
  return t * t * (3 - 2 * t);
};

// Point with Weight info
interface WeightedPoint {
  x: number;
  y: number;
  w: number; // Width at this specific sub-point
}

interface SegmentPressure {
  start: number;
  mid: number;
  end: number;
}

const getBezierPointsWithWeight = (
  points: {x: number, y: number}[], 
  segments: SegmentPressure[],
  tension: number, 
  resolution: number,
  waveFreq: number, 
  waveAmp: number,
  useSmoothing: boolean
): WeightedPoint[] => {
  if (points.length < 2) {
    // Single point fallback
    return points.map(p => ({ ...p, w: segments[0]?.start || 10 }));
  }

  const finalPoints: WeightedPoint[] = [];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1]; 
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2]; 

    // Get pressure profile for this segment (p1 -> p2)
    const seg = segments[i] || { start: 10, mid: 10, end: 10 };

    const cp1 = getControlPoint(p1, p0, p2, false, tension);
    const cp2 = getControlPoint(p2, p1, p3, true, tension);

    // Increase resolution slightly for smoother width transitions
    const step = 1 / (resolution * 1.5); 

    for (let t = 0; t < 1; t += step) {
      const x = Math.pow(1-t, 3)*p1.x + 3*Math.pow(1-t, 2)*t*cp1.x + 3*(1-t)*Math.pow(t, 2)*cp2.x + Math.pow(t, 3)*p2.x;
      const y = Math.pow(1-t, 3)*p1.y + 3*Math.pow(1-t, 2)*t*cp1.y + 3*(1-t)*Math.pow(t, 2)*cp2.y + Math.pow(t, 3)*p2.y;

      // Interpolate width: Start -> Mid -> End
      let currentW;

      // Determine local T (0 to 1) for the half-segment
      let localT;
      let wStart, wEnd;

      if (t <= 0.5) {
        // First half: Start -> Mid
        localT = t * 2;
        wStart = seg.start;
        wEnd = seg.mid;
      } else {
        // Second half: Mid -> End
        localT = (t - 0.5) * 2;
        wStart = seg.mid;
        wEnd = seg.end;
      }

      // Apply smoothing to the interpolation factor
      const factor = useSmoothing ? smoothStep(localT) : localT;
      currentW = wStart + (wEnd - wStart) * factor;

      let finalX = x;
      let finalY = y;

      if (waveAmp > 0) {
        const tx = (3*Math.pow(1-t, 2)*(cp1.x-p1.x) + 6*(1-t)*t*(cp2.x-cp1.x) + 3*t*t*(p2.x-cp2.x));
        const ty = (3*Math.pow(1-t, 2)*(cp1.y-p1.y) + 6*(1-t)*t*(cp2.y-cp1.y) + 3*t*t*(p2.y-cp2.y));
        const mag = Math.sqrt(tx*tx + ty*ty) || 1;
        const nx = -ty / mag; 
        const ny = tx / mag; 

        const wave = Math.sin((i + t) * waveFreq * Math.PI) * waveAmp;

        finalX += nx * wave;
        finalY += ny * wave;
      }

      finalPoints.push({ x: finalX, y: finalY, w: currentW });
    }
  }

  // Explicitly add the very last point with the exact End weight of the last segment
  const lastSeg = segments[segments.length - 1];
  const lastP = points[points.length - 1];
  finalPoints.push({ 
    x: lastP.x,
    y: lastP.y,
    w: lastSeg ? lastSeg.end : 10 
  });

  return finalPoints;
};

// Variable Width Brush using per-point weights + Rounded Caps
const getBrushPath = (
  rawPoints: WeightedPoint[], 
  opts: {
    angleInfluence: number, 
    penAngleDeg: number,
    roundedCaps: boolean
  }
) => {
  // Filter duplicate/too-close points to avoid NaN normals and rendering artifacts
  const points: WeightedPoint[] = [];
  if (rawPoints.length > 0) {
      points.push(rawPoints[0]);
      for (let i = 1; i < rawPoints.length; i++) {
          const p = rawPoints[i];
          const prev = points[points.length - 1];
          const dist = Math.sqrt(Math.pow(p.x - prev.x, 2) + Math.pow(p.y - prev.y, 2));
          // Filter threshold 0.5px
          if (dist > 0.5) points.push(p);
      }
  }

  if (points.length < 2) {
      if (points.length === 1) {
           const p = points[0];
           const r = p.w / 2;
           // Full circle
           return `M ${p.x} ${p.y-r} A ${r} ${r} 0 1 0 ${p.x} ${p.y+r} A ${r} ${r} 0 1 0 ${p.x} ${p.y-r} Z`;
      }
      return '';
  }

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];
  const penAngleRad = (opts.penAngleDeg * Math.PI) / 180;

  points.forEach((p, i) => {
    let baseWidth = p.w;

    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    if (opts.angleInfluence > 0) {
      const strokeAngle = Math.atan2(dy, dx);
      const angleDiff = Math.abs(Math.cos(strokeAngle - penAngleRad));
      const calligraphicFactor = 0.2 + (0.8 * angleDiff);
      baseWidth = baseWidth * (1 - opts.angleInfluence) + (baseWidth * calligraphicFactor * opts.angleInfluence);
    }

    const halfW = baseWidth / 2;
    leftSide.push({ x: p.x + nx * halfW, y: p.y + ny * halfW });
    rightSide.push({ x: p.x - nx * halfW, y: p.y - ny * halfW });
  });

  // Construct SVG Path
  // 1. Start at first Right point
  let d = `M ${rightSide[0].x} ${rightSide[0].y}`;

  // 2. Start Cap (Round)
  if (opts.roundedCaps) {
      const startW = points[0].w / 2;
      // Arc from Right to Left
      // SWEEP FLAG = 0 (Counter-Clockwise) ensures the arc bulges OUTWARD (Convex)
      // because we are moving from Right Side to Left Side (across the back of the start point)
      d += ` A ${startW} ${startW} 0 0 0 ${leftSide[0].x} ${leftSide[0].y}`;
  } else {
      d += ` L ${leftSide[0].x} ${leftSide[0].y}`;
  }

  // 3. Left Side Line
  for (let i = 1; i < leftSide.length; i++) {
      d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  }

  // 4. End Cap (Round)
  const lastIdx = leftSide.length - 1;
  if (opts.roundedCaps) {
      const endW = points[lastIdx].w / 2;
      // Arc from Left to Right
      // SWEEP FLAG = 0 (Counter-Clockwise) ensures the arc bulges OUTWARD (Convex)
      // because we are moving from Left Side to Right Side (across the front of the end point)
      d += ` A ${endW} ${endW} 0 0 0 ${rightSide[lastIdx].x} ${rightSide[lastIdx].y}`;
  } else {
      d += ` L ${rightSide[lastIdx].x} ${rightSide[lastIdx].y}`;
  }

  // 5. Right Side Line (Backwards)
  for (let i = rightSide.length - 2; i >= 0; i--) {
      d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  }

  d += ' Z';
  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [], customPresets = [], onSavePreset, onDeletePreset, onImportSession }) => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);
  const [showGuides, setShowGuides] = useState(true);
  const [exportWithMetadata, setExportWithMetadata] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- PARÁMETROS CALIGRÁFICOS ---
  const [tension, setTension] = useState(0.2); 
  const [fluidity, setFluidity] = useState(0); 
  const [waveFreq, setWaveFreq] = useState(0); 
  const [waveAmp, setWaveAmp] = useState(0);   
  const [smoothEnds, setSmoothEnds] = useState(true); // New: Toggle for Rounded Caps & Smoothing

  // 2. Dinámica del Trazo (Presiones por Segmento)
  const [segmentPressures, setSegmentPressures] = useState<SegmentPressure[]>([]);

  const [penAngle, setPenAngle] = useState(45);
  const [calligraphyAmount, setCalligraphyAmount] = useState(0);

  // 3. Efectos y Florituras
  const [glow, setGlow] = useState(5);
  const [echoes, setEchoes] = useState(0);
  const [echoOffset, setEchoOffset] = useState(10); 
  const [inkDensity, setInkDensity] = useState(0); 
  const [erosion, setErosion] = useState(0); 
  const [particles, setParticles] = useState(0); 

  // --- SAVE PRESET STATE ---
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');

  const svgRef = useRef<SVGSVGElement>(null);

  // --- GRID SETUP ---
  const CELL_SIZE = 100;
  const PADDING = 80;
  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const viewWidth = (currentGrid[0].length - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (currentGrid.length - 1) * CELL_SIZE + (PADDING * 2);
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- CALCULATE ACTIVE POINTS ---
  const activePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const points: {x: number, y: number, char: string, originalX: number, originalY: number}[] = [];
    let lastPos: {x: number, y: number} | null = null;

    cleanText.split('').forEach((char, idx) => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;
      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) { minDist = dist; chosenPos = pos; }
        });
      }

      const seed = idx * 1337;
      const wobbleX = fluidity > 0 ? (Math.sin(seed) * fluidity) : 0;
      const wobbleY = fluidity > 0 ? (Math.cos(seed) * fluidity) : 0;

      const px = PADDING + chosenPos.x * CELL_SIZE;
      const py = PADDING + chosenPos.y * CELL_SIZE;

      points.push({ 
        x: px + wobbleX, 
        y: py + wobbleY, 
        originalX: px,
        originalY: py,
        char 
      });
      lastPos = chosenPos;
    });
    return points;
  }, [text, gridMap, fluidity]); 

  // --- SYNC SEGMENT PRESSURES ---
  useEffect(() => {
    const targetLen = Math.max(1, activePoints.length - 1);

    setSegmentPressures(prev => {
      if (prev.length === targetLen) return prev;
      const next = [...prev];
      if (next.length < targetLen) {
         for(let i=next.length; i<targetLen; i++) {
           next.push({ start: 15, mid: 6, end: 15 });
         }
      } else {
         return next.slice(0, targetLen);
      }
      return next;
    });
  }, [activePoints.length]);

  const updateSegment = (index: number, field: keyof SegmentPressure, value: number) => {
    setSegmentPressures(prev => {
      const copy = [...prev];
      if (copy[index]) {
        copy[index] = { ...copy[index], [field]: value };
      }
      return copy;
    });
  };

  // --- GLOBAL CONTROLS HANDLERS ---
  const updateAllNodes = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, start: value, end: value })));
  };

  const updateAllMids = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, mid: value })));
  };

  // --- PRESETS SYSTEM ---
  const applyPresetState = (p: Partial<TaelimPreset>) => {
    if (p.tension !== undefined) setTension(p.tension);
    if (p.fluidity !== undefined) setFluidity(p.fluidity);
    if (p.waveFreq !== undefined) setWaveFreq(p.waveFreq);
    if (p.waveAmp !== undefined) setWaveAmp(p.waveAmp);
    if (p.glow !== undefined) setGlow(p.glow);
    if (p.echoes !== undefined) setEchoes(p.echoes);
    if (p.echoOffset !== undefined) setEchoOffset(p.echoOffset);
    if (p.inkDensity !== undefined) setInkDensity(p.inkDensity);
    if (p.erosion !== undefined) setErosion(p.erosion);
    if (p.particles !== undefined) setParticles(p.particles);
    if (p.penAngle !== undefined) setPenAngle(p.penAngle);
    if (p.calligraphyAmount !== undefined) setCalligraphyAmount(p.calligraphyAmount);
    if (p.engine !== undefined) setEngine(p.engine);

    // Typically presets enable smoothing by default
    setSmoothEnds(true);

    let s=10, m=10, e=10;
    if (p.engine === 'pluma') { s=15; m=5; e=15; } 
    if (p.name === 'ink') { s=20; m=8; e=2; }
    if (p.engine === 'tech') { s=3; m=3; e=3; setSmoothEnds(false); } // Tech usually sharp

    setSegmentPressures(prev => prev.map(() => ({ start: s, mid: m, end: e })));
  };

  const loadSystemPreset = (type: string) => {
    switch(type) {
      case 'ink': 
        applyPresetState({ name: 'ink', tension: 0.25, fluidity: 5, waveAmp: 0, calligraphyAmount: 90, penAngle: 30, echoes: 0, glow: 0, inkDensity: 60, erosion: 5, particles: 0, engine: 'pluma' });
        break;
      case 'calligraphy':
        applyPresetState({ name: 'calligraphy', tension: 0.2, fluidity: 0, waveAmp: 0, calligraphyAmount: 100, penAngle: 45, echoes: 0, glow: 0, inkDensity: 0, erosion: 0, particles: 0, engine: 'pluma' });
        break;
      case 'marker':
        applyPresetState({ name: 'marker', tension: 0.3, fluidity: 2, waveAmp: 0, calligraphyAmount: 10, penAngle: 90, echoes: 0, glow: 0, inkDensity: 5, erosion: 2, particles: 0, engine: 'pluma' });
        break;
      case 'liquid':
        applyPresetState({ name: 'liquid', tension: 0.5, fluidity: 0, waveFreq: 2, waveAmp: 15, calligraphyAmount: 0, echoes: 1, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 0, particles: 10, engine: 'plasma' });
        break;
      case 'tech':
        applyPresetState({ name: 'tech', tension: 0, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 2, echoOffset: 8, glow: 12, inkDensity: 0, erosion: 0, particles: 30, engine: 'tech' });
        break;
      case 'chaos':
        applyPresetState({ name: 'chaos', tension: 0.8, fluidity: 20, waveFreq: 10, waveAmp: 5, calligraphyAmount: 50, echoes: 0, glow: 8, inkDensity: 80, erosion: 15, particles: 20, engine: 'nexo' });
        break;
      case 'ghost':
        applyPresetState({ name: 'ghost', tension: 0.3, fluidity: 5, waveAmp: 5, calligraphyAmount: 0, echoes: 4, echoOffset: 15, glow: 20, inkDensity: 0, erosion: 3, particles: 10, engine: 'plasma' });
        break;
      case 'void':
        applyPresetState({ name: 'void', tension: 0.3, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 3, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 1, particles: 5, engine: 'tech' });
        break;
    }
  };

  const saveCurrentAsPreset = () => {
    if (!newPresetName || !onSavePreset) return;
    const newPreset: TaelimPreset = {
      id: crypto.randomUUID(),
      name: newPresetName,
      tension, fluidity, waveFreq, waveAmp, glow, echoes, echoOffset,
      inkDensity, erosion, particles, penAngle, calligraphyAmount, engine
    };
    onSavePreset(newPreset);
    setIsSavingPreset(false);
    setNewPresetName('');
  };


  // --- RENDER LOGIC ---
  const renderTrace = () => {
    if (activePoints.length === 0) return null;

    const splinePoints = getBezierPointsWithWeight(
      activePoints, 
      segmentPressures,
      tension, 
      20, 
      waveFreq,
      waveAmp,
      smoothEnds // Pass smoothing preference
    );

    const paths = [];
    const baseColor = 'currentColor';

    const totalLayers = 1 + echoes;
    const filterUrl = erosion > 0 ? "url(#erosion-filter)" : undefined;

    const layerPaths = [];

    for (let i = 0; i < totalLayers; i++) {
      let layerPoints = splinePoints;
      let opacity = 1;

      let widthMultiplier = 1;

      if (i > 0) {
        const offset = i * echoOffset;
        layerPoints = splinePoints.map(p => ({ ...p, x: p.x + offset, y: p.y + offset }));
        opacity = 0.4 / i;
        widthMultiplier = 0.6;
      }

      const finalLayerPoints = layerPoints.map(p => ({ ...p, w: p.w * widthMultiplier }));

      const pathData = getBrushPath(finalLayerPoints, {
        angleInfluence: calligraphyAmount / 100,
        penAngleDeg: penAngle,
        roundedCaps: smoothEnds // Use smooth ends setting
      });

      layerPaths.push(
        <path 
          key={`path-${i}`} 
          d={pathData} 
          fill={baseColor} 
          opacity={engine === 'tech' && i > 0 ? 0.8 : 0.8 * opacity}
          fillRule="nonzero"
        />
      );
    }

    paths.push(<g key="layers" filter={filterUrl}>{layerPaths}</g>);

    if (engine === 'tech') {
       paths.push(
         <path 
            key="wireframe"
            d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`}
            fill="none"
            stroke={baseColor}
            strokeWidth={1}
            opacity={0.5}
            strokeDasharray="4 4"
         />
       );
    }

    if (inkDensity > 0) {
      activePoints.forEach((p, idx) => {
        const seed = (p.x * p.y) + idx;
        const count = Math.floor((inkDensity / 10) * ((seed % 10) / 10 + 0.5)); 
        const segIdx = Math.min(idx, segmentPressures.length - 1);
        const localW = segmentPressures[segIdx] ? segmentPressures[segIdx].start : 10;

        const dots = [];
        for(let k=0; k<count; k++) {
            const angle = (seed * k) % (Math.PI * 2);
            const dist = 10 + (seed * k * 7) % 60;
            const size = (localW / 4) * (((seed + k)%10)/10);
            dots.push(
                <circle 
                    key={`spat-${idx}-${k}`} 
                    cx={p.x + Math.cos(angle)*dist} 
                    cy={p.y + Math.sin(angle)*dist} 
                    r={size} 
                    fill={baseColor} 
                    opacity={0.6} 
                />
            );
        }
        paths.push(<g key={`spats-${idx}`}>{dots}</g>);
      });
    }

    if (particles > 0) {
         activePoints.forEach((p, idx) => {
            const count = Math.floor(particles / 2);
            const dots = [];
             for(let k=0; k<count; k++) {
                const angle = (p.x * k) % (Math.PI * 2);
                const dist = 20 + (p.y * k) % 80;
                dots.push(
                    <circle 
                        key={`part-${idx}-${k}`} 
                        cx={p.x + Math.cos(angle)*dist} 
                        cy={p.y + Math.sin(angle)*dist} 
                        r={1 + (k%2)} 
                        fill={baseColor} 
                        opacity={0.4} 
                    />
                );
            }
            paths.push(<g key={`parts-${idx}`} filter="url(#neon-glow)">{dots}</g>);
         });
    }

    return <g>{paths}</g>;
  };

  const handleRandomWord = () => {
    if (terms.length > 0) setText(terms[Math.floor(Math.random() * terms.length)].root);
  };

  const handleDownload = () => {
    if (!svgRef.current) return;
    const svgData = new XMLSerializer().serializeToString(svgRef.current);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();
    const scaleFactor = 3;
    const paddingBottom = exportWithMetadata ? 300 : 0;

    canvas.width = viewWidth * scaleFactor;
    canvas.height = (viewHeight * scaleFactor) + paddingBottom;

    img.onload = () => {
      if(ctx) {
        ctx.fillStyle = "#020617"; 
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(img, 0, 0, viewWidth * scaleFactor, viewHeight * scaleFactor);

        if (exportWithMetadata) {
          const currentTerm = terms.find(t => t.root.toLowerCase() === text.toLowerCase());
          const displayRoot = currentTerm ? currentTerm.root : text;
          const displayMeaning = currentTerm ? currentTerm.meaning : "Trazo Libre";

          ctx.textAlign = 'center';
          ctx.fillStyle = '#ffffff';
          ctx.font = "bold 80px 'Space Grotesk', sans-serif";
          ctx.fillText(displayRoot.toUpperCase(), canvas.width / 2, (viewHeight * scaleFactor) + 80);
          ctx.fillStyle = '#22d3ee';
          ctx.font = "50px 'Space Grotesk', sans-serif";
          ctx.fillText(displayMeaning, canvas.width / 2, (viewHeight * scaleFactor) + 160);
        }

        const link = document.createElement("a");
        link.download = `Glosario_${text}.png`;
        link.href = canvas.toDataURL("image/png");
        link.click();
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
  };

  const handleImportClick = () => {
    if (onImportSession && fileInputRef.current) {
        fileInputRef.current.click();
    }
  };

  return (
    <div className="max-w-[1920px] mx-auto p-4 font-sans h-[calc(100vh-140px)] lg:h-[calc(100vh-100px)]">
      <input type="file" ref={fileInputRef} onChange={onImportSession} className="hidden" accept="application/json" />

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 h-full">

        {/* --- PANEL DE CONTROLES --- */}
        <div className="xl:col-span-3 space-y-4 h-full overflow-y-auto pr-2 custom-scrollbar pb-20">
          <div className="bg-slate-950/80 p-5 border border-slate-800 shadow-2xl relative corner-accent backdrop-blur">

            <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-800">
              <div className="p-2 bg-slate-900 border border-slate-700 text-cyan-400">
                <PenTool size={20} />
              </div>
              <div>
                <h2 className="text-lg font-bold text-white uppercase tracking-widest font-sans">Tael'im V5</h2>
                <p className="text-slate-500 text-[10px] uppercase tracking-widest font-mono">Master Calligraphy</p>
              </div>
            </div>

            {/* Input */}
            <div className="space-y-4 mb-6">
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={text}
                  onChange={(e) => setText(e.target.value)}
                  className="w-full bg-slate-900 border border-slate-700 rounded-none px-4 py-3 text-white focus:border-cyan-500 outline-none text-xl font-bold font-mono tracking-widest uppercase"
                  placeholder="PALABRA..."
                />
                <button onClick={handleRandomWord} className="px-3 bg-slate-900 hover:bg-slate-800 text-slate-400 border border-slate-700 rounded-none"><Dice5 size={20}/></button>
              </div>
              <div className="grid grid-cols-2 gap-2">
                  {(['algante', 'comun'] as GridMode[]).map((m) => (
                    <button key={m} onClick={() => setMode(m)} className={`py-1.5 px-3 rounded-none border text-[10px] font-bold uppercase tracking-wider ${mode === m ? 'bg-cyan-900/30 border-cyan-500 text-cyan-300' : 'bg-slate-950 border-slate-800 text-slate-500'}`}>{m}</button>
                  ))}
              </div>
            </div>

            {/* PRESETS */}
            <div className="mb-6">
               <div className="flex justify-between items-end mb-2">
                 <label className="text-[10px] font-bold text-slate-500 uppercase flex items-center gap-2 tracking-widest"><Wand2 size={12}/> Estilos</label>
                 <div className="flex gap-2">
                    <button onClick={handleImportClick} className="text-[10px] text-emerald-500 hover:text-emerald-400 flex items-center gap-1 font-mono uppercase" title="Cargar sesión completa"><Upload size={10}/> Load</button>
                    <button onClick={() => setIsSavingPreset(!isSavingPreset)} className="text-[10px] text-cyan-500 hover:text-cyan-400 flex items-center gap-1 font-mono uppercase"><Save size={10}/> Save</button>
                 </div>
               </div>

               {isSavingPreset && (
                 <div className="flex gap-2 mb-2 animate-fade-in">
                   <input type="text" value={newPresetName} onChange={e => setNewPresetName(e.target.value)} placeholder="NOMBRE" className="flex-1 bg-slate-900 border border-slate-700 rounded-none text-xs px-2 py-1 text-white font-mono uppercase" />
                   <button onClick={saveCurrentAsPreset} className="bg-cyan-600 px-2 rounded-none text-white text-xs font-bold">OK</button>
                 </div>
               )}

               <div className="grid grid-cols-4 gap-1.5 mb-2">
                 {['ink', 'calligraphy', 'marker', 'liquid', 'tech', 'chaos', 'ghost', 'void'].map(p => (
                   <button key={p} onClick={() => loadSystemPreset(p)} className="bg-slate-900 hover:bg-slate-800 border border-slate-700 hover:border-cyan-500/50 rounded-none py-1 text-[9px] text-slate-300 uppercase truncate px-1 font-mono">{p}</button>
                 ))}
               </div>

               {/* Custom Presets */}
               {customPresets && customPresets.length > 0 && (
                 <>
                   <label className="text-[9px] font-bold text-slate-600 uppercase mb-1 block mt-2 tracking-widest">Mis Estilos</label>
                   <div className="flex flex-wrap gap-1.5">
                     {customPresets.map(p => (
                       <div key={p.id} className="group relative flex items-center">
                         <button onClick={() => applyPresetState(p)} className="bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded-none py-1 pl-2 pr-4 text-[9px] text-cyan-200 uppercase truncate font-mono">{p.name}</button>
                         <button onClick={() => onDeletePreset && onDeletePreset(p.id)} className="absolute right-1 text-slate-500 hover:text-red-400 opacity-0 group-hover:opacity-100"><X size={10}/></button>
                       </div>
                     ))}
                   </div>
                 </>
               )}
            </div>

            <div className="w-full h-px bg-gradient-to-r from-transparent via-slate-700 to-transparent my-6"></div>

             {/* --- PRESIÓN POR SEGMENTO (3 PUNTOS) --- */}
             <div className="space-y-4 mb-6">
               <div className="flex items-center justify-between text-cyan-400 mb-2">
                 <div className="flex items-center gap-2">
                    <Activity size={16} />
                    <span className="text-xs font-bold uppercase tracking-wider">Modulación de Trazo</span>
                 </div>
                 <button 
                   onClick={() => setSmoothEnds(!smoothEnds)} 
                   className={`p-1 rounded-sm transition-colors border ${smoothEnds ? 'bg-cyan-900/30 text-cyan-300 border-cyan-500' : 'text-slate-600 border-slate-800 hover:text-slate-400'}`}
                   title="Suavizar puntas y transiciones"
                 >
                   <Circle size={14} className={smoothEnds ? 'fill-current' : ''} />
                 </button>
               </div>

               {/* GLOBAL CONTROLS */}
               {activePoints.length > 0 && (
                 <div className="bg-slate-900 border border-slate-800 p-3 mb-3 relative">
                   <div className="absolute top-0 right-0 w-2 h-2 bg-slate-800"></div>
                   <div className="flex items-center gap-2 mb-2">
                     <Layers size={12} className="text-cyan-500" />
                     <span className="text-[9px] font-bold text-cyan-500 uppercase tracking-widest">Global Override</span>
                   </div>
                   <div className="grid grid-cols-2 gap-3">
                     <div>
                       <label className="text-[8px] text-slate-500 block mb-1 uppercase font-mono">Grosor Nodos</label>
                       <input type="range" min="1" max="50" step="0.5" className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-cyan-400" 
                         onChange={(e) => updateAllNodes(Number(e.target.value))} />
                     </div>
                     <div>
                       <label className="text-[8px] text-slate-500 block mb-1 uppercase font-mono">Grosor Trazos</label>
                       <input type="range" min="1" max="50" step="0.5" className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-emerald-400" 
                         onChange={(e) => updateAllMids(Number(e.target.value))} />
                     </div>
                   </div>
                 </div>
               )}

               {activePoints.length === 0 ? (
                 <p className="text-xs text-slate-600 italic font-mono uppercase text-center py-4 border border-dashed border-slate-800">Esperando Input...</p>
               ) : (
                 <div className="space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar bg-black/20 p-2 border border-slate-800">

                   {/* SPECIAL CASE: Single Point */}
                   {activePoints.length === 1 && segmentPressures.length > 0 && (
                      <div className="bg-slate-900 p-2 border border-slate-800">
                        <div className="flex items-center justify-between mb-2">
                           <span className="text-[10px] font-bold text-cyan-400 bg-cyan-900/20 px-1.5 py-0.5 border border-cyan-900/50">{activePoints[0].char}</span>
                           <span className="text-[9px] text-slate-500 uppercase">Punto Único</span>
                        </div>
                        <div className="flex items-center gap-2">
                             <span className="text-[8px] text-slate-500 w-8 uppercase">Base</span>
                             <input 
                                 type="range" min="1" max="50" step="0.5" 
                                 value={segmentPressures[0].start} 
                                 onChange={(e) => updateSegment(0, 'start', Number(e.target.value))}
                                 className="flex-1 h-1 bg-slate-800 rounded-none appearance-none accent-cyan-500" 
                             />
                        </div>
                      </div>
                   )}

                   {/* Standard Segments */}
                   {activePoints.length > 1 && segmentPressures.map((seg, idx) => {
                     const charStart = activePoints[idx]?.char || '?';
                     const charEnd = activePoints[idx+1]?.char || '?';

                     return (
                      <div key={idx} className="bg-slate-900 p-2 border-l-2 border-slate-700 hover:border-cyan-500 transition-colors">
                        <div className="flex items-center justify-between mb-2">
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] font-bold text-cyan-400 bg-cyan-950 px-1 border border-cyan-900">{charStart}</span>
                                <ArrowRight size={10} className="text-slate-600" />
                                <span className="text-[10px] font-bold text-emerald-400 bg-emerald-950 px-1 border border-emerald-900">{charEnd}</span>
                            </div>
                            <span className="text-[9px] text-slate-600 font-mono">SEG_{idx < 9 ? '0'+(idx+1) : idx+1}</span>
                        </div>

                        <div className="space-y-1">
                            {/* Inicio */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-500 w-8 uppercase font-mono">Start</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.start} 
                                    onChange={(e) => updateSegment(idx, 'start', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded-none appearance-none accent-cyan-500" 
                                />
                            </div>
                            {/* Centro */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-500 w-8 uppercase font-mono">Mid</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.mid} 
                                    onChange={(e) => updateSegment(idx, 'mid', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded-none appearance-none accent-slate-400" 
                                />
                            </div>
                            {/* Final */}
                            <div className="flex items-center gap-2">
                                <span className="text-[8px] text-slate-500 w-8 uppercase font-mono">End</span>
                                <input 
                                    type="range" min="1" max="50" step="0.5" 
                                    value={seg.end} 
                                    onChange={(e) => updateSegment(idx, 'end', Number(e.target.value))}
                                    className="flex-1 h-1 bg-slate-800 rounded-none appearance-none accent-emerald-500" 
                                />
                            </div>
                        </div>
                      </div>
                     );
                   })}
                 </div>
               )}

               <div className="pt-2">
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase tracking-widest"><span>Influencia Ángulo</span> <span>{calligraphyAmount}%</span></div>
                  <input type="range" min="0" max="100" value={calligraphyAmount} onChange={(e) => setCalligraphyAmount(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-cyan-500" />
               </div>

               <div className={calligraphyAmount === 0 ? 'opacity-30' : ''}>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase tracking-widest"><span>Rotación</span> <span>{penAngle}°</span></div>
                  <input type="range" min="0" max="180" value={penAngle} onChange={(e) => setPenAngle(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-cyan-500" />
               </div>
            </div>

            <div className="w-full h-px bg-gradient-to-r from-transparent via-slate-700 to-transparent my-6"></div>

            {/* --- GEOMETRÍA & MOVIMIENTO --- */}
            <div className="space-y-4 mb-6">
               <div className="flex items-center gap-2 text-emerald-400 mb-2">
                 <Move size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">Geometría</span>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono">
                    <span>Tensión Curva</span> 
                    <span>{tension.toFixed(2)}</span>
                  </div>
                  <input type="range" min="0" max="1" step="0.01" value={tension} onChange={(e) => setTension(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-emerald-500" />
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono">
                    <span>Caos Nodos</span> 
                    <span>{fluidity}</span>
                  </div>
                  <input type="range" min="0" max="40" value={fluidity} onChange={(e) => setFluidity(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-emerald-500" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1 font-mono">Frec. Onda</label>
                    <input type="range" min="0" max="20" step="0.5" value={waveFreq} onChange={e => setWaveFreq(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-emerald-400" />
                 </div>
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1 font-mono">Amp. Onda</label>
                    <input type="range" min="0" max="40" value={waveAmp} onChange={e => setWaveAmp(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-emerald-400" />
                 </div>
               </div>
            </div>

            {/* --- FLORITURAS & FX --- */}
            <div className="space-y-4">
               <div className="flex items-center gap-2 text-orange-400 mb-2">
                 <Droplets size={16} />
                 <span className="text-xs font-bold uppercase tracking-wider">FX & Partículas</span>
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono"><span>Densidad</span> <span>{inkDensity}%</span></div>
                 <input type="range" min="0" max="100" value={inkDensity} onChange={(e) => setInkDensity(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono"><span>Erosión</span> <span>{erosion}</span></div>
                 <input type="range" min="0" max="20" step="0.5" value={erosion} onChange={(e) => setErosion(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
               </div>

               <div>
                 <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono"><span>Partículas</span> <span>{particles}</span></div>
                 <input type="range" min="0" max="50" value={particles} onChange={(e) => setParticles(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
               </div>

               <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1 font-mono">Ecos ({echoes})</label>
                    <input type="range" min="0" max="10" step="1" value={echoes} onChange={e => setEchoes(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
                 </div>
                 <div>
                    <label className="text-[9px] text-slate-500 uppercase block mb-1 font-mono">Offset</label>
                    <input type="range" min="0" max="100" value={echoOffset} onChange={e => setEchoOffset(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
                 </div>
               </div>

               <div>
                  <div className="flex justify-between text-[10px] text-slate-500 mb-1 uppercase font-mono"><span>Glow</span> <span>{glow}</span></div>
                  <input type="range" min="0" max="50" value={glow} onChange={(e) => setGlow(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
               </div>
            </div>

          </div>
        </div>

        {/* --- VISUALIZADOR --- */}
        <div className="xl:col-span-9 flex flex-col h-full relative">

           <div className="absolute top-6 right-6 z-20 flex gap-2 bg-slate-950/90 backdrop-blur border border-slate-700/50 p-2 shadow-2xl corner-accent">
             <button onClick={() => setShowGuides(!showGuides)} className={`p-2 rounded-none transition-colors border ${showGuides ? 'bg-cyan-900/20 text-cyan-300 border-cyan-500' : 'bg-slate-900 text-slate-500 border-transparent'}`} title="Guías"><Eye size={18} /></button>
             <button onClick={() => setExportWithMetadata(!exportWithMetadata)} className={`p-2 rounded-none transition-colors border ${exportWithMetadata ? 'bg-emerald-900/20 text-emerald-300 border-emerald-500' : 'bg-slate-900 text-slate-500 border-transparent'}`} title="Metadatos"><FileText size={18} /></button>
             <div className="w-px h-6 bg-slate-800 my-auto mx-1"></div>
             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-500 hover:text-white"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.0, z + 0.1))} className="p-2 text-slate-500 hover:text-white"><ZoomIn size={18} /></button>
             <button onClick={handleDownload} className="flex items-center gap-2 px-3 py-2 bg-cyan-700 hover:bg-cyan-600 text-white rounded-none ml-2 font-bold text-xs uppercase tracking-widest border border-cyan-500"><Download size={14} /> Exportar</button>
           </div>

           <div className="flex-1 bg-slate-950 border border-slate-800 overflow-hidden relative flex items-center justify-center shadow-[inset_0_0_20px_rgba(0,0,0,0.5)] tech-border">
             {/* Background Grid inside canvas */}
             <div className="absolute inset-0 opacity-10" style={{backgroundImage: 'linear-gradient(rgba(14,165,233,0.3) 1px, transparent 1px), linear-gradient(90deg, rgba(14,165,233,0.3) 1px, transparent 1px)', backgroundSize: '40px 40px'}}></div>

             <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar p-10 relative z-10">
               <div style={{ width: viewWidth, height: viewHeight, transform: `scale(${zoom})`, transition: 'transform 0.3s ease-out' }}>
                 <svg ref={svgRef} viewBox={`0 0 ${viewWidth} ${viewHeight}`} className="w-full h-full drop-shadow-2xl overflow-visible">
                    <defs>
                      <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                        <feMerge>
                          <feMergeNode in="coloredBlur" />
                          <feMergeNode in="SourceGraphic" />
                        </feMerge>
                      </filter>
                      <filter id="erosion-filter" x="-20%" y="-20%" width="140%" height="140%">
                        <feTurbulence type="fractalNoise" baseFrequency="0.05" numOctaves="3" result="noise" />
                        <feDisplacementMap in="SourceGraphic" in2="noise" scale={erosion} />
                      </filter>
                    </defs>

                    {/* Guías */}
                    {showGuides && (
                      <g className="opacity-20 pointer-events-none">
                        {currentGrid.map((row, y) => row.map((char, x) => (
                           <g key={`${x}-${y}`}>
                             <rect x={PADDING + x * CELL_SIZE - 2} y={PADDING + y * CELL_SIZE - 2} width="4" height="4" fill="#334155" />
                             <text x={PADDING + x * CELL_SIZE} y={PADDING + y * CELL_SIZE + 40} textAnchor="middle" fill="#475569" fontSize="10" fontFamily="monospace" opacity={0.5}>{char}</text>
                           </g>
                        )))}
                      </g>
                    )}

                    {/* Nodos Activos */}
                    {showGuides && activePoints.map((p, i) => (
                      <g key={i}>
                        <rect x={p.x - 4} y={p.y - 4} width="8" height="8" fill={mode === 'algante' ? '#06b6d4' : '#10b981'} opacity={0.8} />
                        <line x1={p.originalX} y1={p.originalY} x2={p.x} y2={p.y} stroke="white" strokeWidth="1" strokeDasharray="2 2" opacity="0.3" />
                        <text x={p.x} y={p.y - 15} textAnchor="middle" fill="white" fontSize="12" fontWeight="bold">{p.char}</text>
                      </g>
                    ))}

                    {/* TRAZO PRINCIPAL */}
                    <g filter={glow > 0 ? "url(#neon-glow)" : ""} className={mode === 'algante' ? 'text-cyan-400' : 'text-emerald-400'}>
                      {renderTrace()}
                    </g>
                 </svg>
               </div>
             </div>
           </div>

        </div>
      </div>
    </div>
  );
};

export default Taelim;

