                          <span className="text-xs font-mono text-slate-300">{exportConfig.strokeColor}</span>
                       </div>
                    </div>
                    <div>
                       <label className="text-[10px] font-bold text-slate-500 uppercase block mb-2">Fondo</label>
                       <div className="flex items-center gap-2">
                          <input 
