                    className={`flex items-center justify-center gap-2 py-2 text-xs font-bold uppercase tracking-wider border transition-all ${isAnimating ? 'bg-orange-900/30 text-orange-400 border-orange-500' : 'bg-slate-900 text-slate-400 border-slate-700 hover:border-cyan-500'}`}
                  >
                    {isAnimating ? <Pause size={14} /> : <Play size={14} />}
                    {isAnimating ? 'Pausar' : 'Replay'}
