                         <button onClick={() => applyPresetState(p)} className="bg-slate-800 hover:bg-slate-700 border border-slate-600 rounded-none py-1 pl-2 pr-4 text-[9px] text-cyan-200 uppercase truncate font-mono">{p.name}</button>
                         <button onClick={() => onDeletePreset && onDeletePreset(p.id)} className="absolute right-1 text-slate-500 hover:text-red-400 opacity-0 group-hover:opacity-100"><X size={10}/></button>
                       </div>
