// Helper: Mapa de coordenadas
const getGridMap = (grid: string[][]) => {
  const map = new Map<string, {x: number, y: number}[]>();
  grid.forEach((row, y) => {
    row.forEach((char, x) => {
      if (!map.has(char)) map.set(char, []);
      map.get(char)?.push({ x, y });
    });
  });
  return map;
};

// --- GEOMETRY MATH HELPERS ---
const getDistance = (p1: {x:number, y:number}, p2: {x:number, y:number}) => 
  Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));

const getControlPoint = (
  current: {x:number, y:number}, 
  previous: {x:number, y:number}, 
  next: {x:number, y:number}, 
  reverse: boolean,
  tension: number
) => {
  const p = previous || current;
  const n = next || current;
  const smoothing = tension;

  const o = {
    x: n.x - p.x + (n.x - current.x),
    y: n.y - p.y + (n.y - current.y)
  };

  const angle = Math.atan2(o.y, o.x) + (reverse ? Math.PI : 0);
  const length = getDistance(current, n) * smoothing;

  return {
    x: current.x + Math.cos(angle) * length,
    y: current.y + Math.sin(angle) * length
  };
};

// Smoothstep function for organic width transition
const smoothStep = (t: number) => {
  return t * t * (3 - 2 * t);
};

// Point with Weight info
interface WeightedPoint {
  x: number;
  y: number;
  w: number; // Width at this specific sub-point
}

interface SegmentPressure {
  start: number;
  mid: number;
  end: number;
}

const getBezierPointsWithWeight = (
  points: {x: number, y: number}[], 
  segments: SegmentPressure[],
  tension: number, 
  resolution: number,
  waveFreq: number, 
  waveAmp: number,
  useSmoothing: boolean
): WeightedPoint[] => {
  if (points.length < 2) {
    // Single point fallback
    return points.map(p => ({ ...p, w: segments[0]?.start || 10 }));
  }

  const finalPoints: WeightedPoint[] = [];

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1]; 
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2]; 

    // Get pressure profile for this segment (p1 -> p2)
    const seg = segments[i] || { start: 10, mid: 10, end: 10 };

    const cp1 = getControlPoint(p1, p0, p2, false, tension);
    const cp2 = getControlPoint(p2, p1, p3, true, tension);

    // Increase resolution slightly for smoother width transitions
    const step = 1 / (resolution * 1.5); 

    for (let t = 0; t < 1; t += step) {
      const x = Math.pow(1-t, 3)*p1.x + 3*Math.pow(1-t, 2)*t*cp1.x + 3*(1-t)*Math.pow(t, 2)*cp2.x + Math.pow(t, 3)*p2.x;
      const y = Math.pow(1-t, 3)*p1.y + 3*Math.pow(1-t, 2)*t*cp1.y + 3*(1-t)*Math.pow(t, 2)*cp2.y + Math.pow(t, 3)*p2.y;

      // Interpolate width: Start -> Mid -> End
      let currentW;

      // Determine local T (0 to 1) for the half-segment
      let localT;
      let wStart, wEnd;

      if (t <= 0.5) {
        // First half: Start -> Mid
        localT = t * 2;
        wStart = seg.start;
        wEnd = seg.mid;
      } else {
        // Second half: Mid -> End
        localT = (t - 0.5) * 2;
        wStart = seg.mid;
        wEnd = seg.end;
      }

      // Apply smoothing to the interpolation factor
      const factor = useSmoothing ? smoothStep(localT) : localT;
      currentW = wStart + (wEnd - wStart) * factor;

      let finalX = x;
      let finalY = y;

      if (waveAmp > 0) {
        const tx = (3*Math.pow(1-t, 2)*(cp1.x-p1.x) + 6*(1-t)*t*(cp2.x-cp1.x) + 3*t*t*(p2.x-cp2.x));
        const ty = (3*Math.pow(1-t, 2)*(cp1.y-p1.y) + 6*(1-t)*t*(cp2.y-cp1.y) + 3*t*t*(p2.y-cp2.y));
        const mag = Math.sqrt(tx*tx + ty*ty) || 1;
        const nx = -ty / mag; 
        const ny = tx / mag; 

        const wave = Math.sin((i + t) * waveFreq * Math.PI) * waveAmp;

        finalX += nx * wave;
        finalY += ny * wave;
      }

      finalPoints.push({ x: finalX, y: finalY, w: currentW });
    }
  }

  // Explicitly add the very last point with the exact End weight of the last segment
  const lastSeg = segments[segments.length - 1];
  const lastP = points[points.length - 1];
  finalPoints.push({ 
    x: lastP.x,
    y: lastP.y,
    w: lastSeg ? lastSeg.end : 10 
  });

  return finalPoints;
};

// Variable Width Brush using per-point weights + Rounded Caps
const getBrushPath = (
  rawPoints: WeightedPoint[], 
  opts: {
    angleInfluence: number, 
    penAngleDeg: number,
    roundedCaps: boolean
  }
) => {
  // Filter duplicate/too-close points to avoid NaN normals and rendering artifacts
  const points: WeightedPoint[] = [];
  if (rawPoints.length > 0) {
      points.push(rawPoints[0]);
      for (let i = 1; i < rawPoints.length; i++) {
          const p = rawPoints[i];
          const prev = points[points.length - 1];
          const dist = Math.sqrt(Math.pow(p.x - prev.x, 2) + Math.pow(p.y - prev.y, 2));
          // Filter threshold 0.5px
          if (dist > 0.5) points.push(p);
      }
  }

  if (points.length < 2) {
      if (points.length === 1) {
           const p = points[0];
           const r = p.w / 2;
           // Full circle
           return `M ${p.x} ${p.y-r} A ${r} ${r} 0 1 0 ${p.x} ${p.y+r} A ${r} ${r} 0 1 0 ${p.x} ${p.y-r} Z`;
      }
      return '';
  }

  const leftSide: {x: number, y: number}[] = [];
  const rightSide: {x: number, y: number}[] = [];
  const penAngleRad = (opts.penAngleDeg * Math.PI) / 180;

  points.forEach((p, i) => {
    let baseWidth = p.w;

    let dx, dy;
    if (i === 0) {
      dx = points[i+1].x - p.x;
      dy = points[i+1].y - p.y;
    } else if (i === points.length - 1) {
      dx = p.x - points[i-1].x;
      dy = p.y - points[i-1].y;
    } else {
      dx = points[i+1].x - points[i-1].x;
      dy = points[i+1].y - points[i-1].y;
    }
    const len = Math.sqrt(dx*dx + dy*dy) || 1;
    let nx = -dy / len;
    let ny = dx / len;

    if (opts.angleInfluence > 0) {
      const strokeAngle = Math.atan2(dy, dx);
      const angleDiff = Math.abs(Math.cos(strokeAngle - penAngleRad));
      const calligraphicFactor = 0.2 + (0.8 * angleDiff);
      baseWidth = baseWidth * (1 - opts.angleInfluence) + (baseWidth * calligraphicFactor * opts.angleInfluence);
    }

    const halfW = baseWidth / 2;
    leftSide.push({ x: p.x + nx * halfW, y: p.y + ny * halfW });
    rightSide.push({ x: p.x - nx * halfW, y: p.y - ny * halfW });
  });

  // Construct SVG Path
  // 1. Start at first Right point
  let d = `M ${rightSide[0].x} ${rightSide[0].y}`;

  // 2. Start Cap (Round)
  if (opts.roundedCaps) {
      const startW = points[0].w / 2;
      // Arc from Right to Left
      // SWEEP FLAG = 0 (Counter-Clockwise) ensures the arc bulges OUTWARD (Convex)
      // because we are moving from Right Side to Left Side (across the back of the start point)
      d += ` A ${startW} ${startW} 0 0 0 ${leftSide[0].x} ${leftSide[0].y}`;
  } else {
      d += ` L ${leftSide[0].x} ${leftSide[0].y}`;
  }

  // 3. Left Side Line
  for (let i = 1; i < leftSide.length; i++) {
      d += ` L ${leftSide[i].x} ${leftSide[i].y}`;
  }

  // 4. End Cap (Round)
  const lastIdx = leftSide.length - 1;
  if (opts.roundedCaps) {
      const endW = points[lastIdx].w / 2;
      // Arc from Left to Right
      // SWEEP FLAG = 0 (Counter-Clockwise) ensures the arc bulges OUTWARD (Convex)
      // because we are moving from Left Side to Right Side (across the front of the end point)
      d += ` A ${endW} ${endW} 0 0 0 ${rightSide[lastIdx].x} ${rightSide[lastIdx].y}`;
  } else {
      d += ` L ${rightSide[lastIdx].x} ${rightSide[lastIdx].y}`;
  }

  // 5. Right Side Line (Backwards)
  for (let i = rightSide.length - 2; i >= 0; i--) {
      d += ` L ${rightSide[i].x} ${rightSide[i].y}`;
  }

  d += ' Z';
  return d;
};


// --- COMPONENTE PRINCIPAL ---
const Taelim: React.FC<Props> = ({ terms = [], customPresets = [], onSavePreset, onDeletePreset, onImportSession }) => {
  const [text, setText] = useState('');
  const [mode, setMode] = useState<GridMode>('algante');
  const [engine, setEngine] = useState<RenderEngine>('plasma');
  const [zoom, setZoom] = useState(1);
  const [showGuides, setShowGuides] = useState(true);

  // --- EXPORT STATE ---
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportConfig, setExportConfig] = useState({
    bgColor: '#020617',
    strokeColor: '#22d3ee', // Default Cyan
    includeMetadata: false,
    includeGuides: false,
    includeStartEnd: false, // New export option
    isTransparent: false,
    useGradient: false // New export option
  });

  // --- DIDACTIC STATE ---
  const [showSequence, setShowSequence] = useState(false);
  const [isGradient, setIsGradient] = useState(false);
  const [gradientColors, setGradientColors] = useState({ start: '#22d3ee', end: '#a855f7' });

  // Animation State
  const [isAnimating, setIsAnimating] = useState(false);
  const [animationFrame, setAnimationFrame] = useState(0); // Index of point being drawn
  const animationRef = useRef<number>();

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- PARÁMETROS CALIGRÁFICOS ---
  const [tension, setTension] = useState(0.2); 
  const [fluidity, setFluidity] = useState(0); 
  const [waveFreq, setWaveFreq] = useState(0); 
  const [waveAmp, setWaveAmp] = useState(0);   
  const [smoothEnds, setSmoothEnds] = useState(true); // New: Toggle for Rounded Caps & Smoothing

  // 2. Dinámica del Trazo (Presiones por Segmento)
  const [segmentPressures, setSegmentPressures] = useState<SegmentPressure[]>([]);

  const [penAngle, setPenAngle] = useState(45);
  const [calligraphyAmount, setCalligraphyAmount] = useState(0);

  // 3. Efectos y Florituras
  const [glow, setGlow] = useState(5);
  const [echoes, setEchoes] = useState(0);
  const [echoOffset, setEchoOffset] = useState(10); 
  const [inkDensity, setInkDensity] = useState(0); 
  const [erosion, setErosion] = useState(0); 
  const [particles, setParticles] = useState(0); 

  // --- SAVE PRESET STATE ---
  const [isSavingPreset, setIsSavingPreset] = useState(false);
  const [newPresetName, setNewPresetName] = useState('');

  const svgRef = useRef<SVGSVGElement>(null);

  // --- GRID SETUP ---
  const CELL_SIZE = 100;
  const PADDING = 80;
  const currentGrid = mode === 'algante' ? ALGANTE_GRID : COMUN_GRID;
  const viewWidth = (currentGrid[0].length - 1) * CELL_SIZE + (PADDING * 2);
  const viewHeight = (currentGrid.length - 1) * CELL_SIZE + (PADDING * 2);
  const gridMap = useMemo(() => getGridMap(currentGrid), [currentGrid]);

  // --- CALCULATE ACTIVE POINTS ---
  const fullActivePoints = useMemo(() => {
    const cleanText = text.toUpperCase().replace(/[^A-Z]/g, '');
    const points: {x: number, y: number, char: string, originalX: number, originalY: number}[] = [];
    let lastPos: {x: number, y: number} | null = null;

    cleanText.split('').forEach((char, idx) => {
      const possiblePositions = gridMap.get(char);
      if (!possiblePositions || possiblePositions.length === 0) return;
      let chosenPos = possiblePositions[0];

      if (lastPos && possiblePositions.length > 1) {
        let minDist = Infinity;
        possiblePositions.forEach(pos => {
          const dist = Math.sqrt(Math.pow(pos.x - lastPos!.x, 2) + Math.pow(pos.y - lastPos!.y, 2));
          if (dist < minDist) { minDist = dist; chosenPos = pos; }
        });
      }

      const seed = idx * 1337;
      const wobbleX = fluidity > 0 ? (Math.sin(seed) * fluidity) : 0;
      const wobbleY = fluidity > 0 ? (Math.cos(seed) * fluidity) : 0;

      const px = PADDING + chosenPos.x * CELL_SIZE;
      const py = PADDING + chosenPos.y * CELL_SIZE;

      points.push({ 
        x: px + wobbleX, 
        y: py + wobbleY, 
        originalX: px,
        originalY: py,
        char 
      });
      lastPos = chosenPos;
    });
    return points;
  }, [text, gridMap, fluidity]);

  // Determine which points to render based on animation
  const activePoints = useMemo(() => {
    if (!isAnimating) return fullActivePoints;
    if (fullActivePoints.length === 0) return [];
    // Always show at least first point so it's not empty
    const limit = Math.max(1, Math.floor(animationFrame));
    return fullActivePoints.slice(0, limit + 1);
  }, [fullActivePoints, isAnimating, animationFrame]);

  // --- ANIMATION LOOP ---
  useEffect(() => {
    if (isAnimating) {
      if (animationFrame < fullActivePoints.length) {
        animationRef.current = window.setTimeout(() => {
          setAnimationFrame(prev => prev + 0.5); // Speed of animation
        }, 100); // Frame delay
      } else {
        setIsAnimating(false);
      }
    }
    return () => clearTimeout(animationRef.current);
  }, [isAnimating, animationFrame, fullActivePoints.length]);

  const toggleAnimation = () => {
    if (isAnimating) {
      setIsAnimating(false);
      setAnimationFrame(fullActivePoints.length);
    } else {
      setAnimationFrame(0);
      setIsAnimating(true);
    }
  };

  // --- SYNC SEGMENT PRESSURES ---
  useEffect(() => {
    // Use full points for pressure array to maintain state even during animation
    const targetLen = Math.max(1, fullActivePoints.length - 1);

    setSegmentPressures(prev => {
      if (prev.length === targetLen) return prev;
      const next = [...prev];
      if (next.length < targetLen) {
         for(let i=next.length; i<targetLen; i++) {
           next.push({ start: 15, mid: 6, end: 15 });
         }
      } else {
         return next.slice(0, targetLen);
      }
      return next;
    });
  }, [fullActivePoints.length]);

  const updateSegment = (index: number, field: keyof SegmentPressure, value: number) => {
    setSegmentPressures(prev => {
      const copy = [...prev];
      if (copy[index]) {
        copy[index] = { ...copy[index], [field]: value };
      }
      return copy;
    });
  };

  // --- GLOBAL CONTROLS HANDLERS ---
  const updateAllNodes = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, start: value, end: value })));
  };

  const updateAllMids = (value: number) => {
    setSegmentPressures(prev => prev.map(s => ({ ...s, mid: value })));
  };

  // --- PRESETS SYSTEM ---
  const applyPresetState = (p: Partial<TaelimPreset>) => {
    // 1. Basic Physics
    if (p.tension !== undefined) setTension(p.tension);
    if (p.fluidity !== undefined) setFluidity(p.fluidity);
    if (p.waveFreq !== undefined) setWaveFreq(p.waveFreq);
    if (p.waveAmp !== undefined) setWaveAmp(p.waveAmp);

    // 2. Effects
    if (p.glow !== undefined) setGlow(p.glow);
    if (p.echoes !== undefined) setEchoes(p.echoes);
    if (p.echoOffset !== undefined) setEchoOffset(p.echoOffset);
    if (p.inkDensity !== undefined) setInkDensity(p.inkDensity);
    if (p.erosion !== undefined) setErosion(p.erosion);
    if (p.particles !== undefined) setParticles(p.particles);

    // 3. Calligraphy
    if (p.penAngle !== undefined) setPenAngle(p.penAngle);
    if (p.calligraphyAmount !== undefined) setCalligraphyAmount(p.calligraphyAmount);
    if (p.engine !== undefined) setEngine(p.engine);

    // 4. Enhanced Style Parameters
    if (p.smoothEnds !== undefined) setSmoothEnds(p.smoothEnds);
    else setSmoothEnds(true); // Default

    if (p.isGradient !== undefined) setIsGradient(p.isGradient);
    if (p.gradientColors !== undefined) setGradientColors(p.gradientColors);

    // 5. Thickness (Apply base thickness to all segments if present)
    if (p.baseNodeThickness !== undefined && p.baseStrokeThickness !== undefined) {
       setSegmentPressures(prev => prev.map(s => ({
         start: p.baseNodeThickness!,
         mid: p.baseStrokeThickness!,
         end: p.baseNodeThickness!
       })));
    } else {
      // Legacy System Presets fallback
      let s=10, m=10, e=10;
      if (p.engine === 'pluma') { s=15; m=5; e=15; } 
      if (p.name === 'ink') { s=20; m=8; e=2; }
      if (p.engine === 'tech') { s=3; m=3; e=3; setSmoothEnds(false); } 
      setSegmentPressures(prev => prev.map(() => ({ start: s, mid: m, end: e })));
    }
  };

  const loadSystemPreset = (type: string) => {
    // Reset advanced styles for system presets to keep them clean unless defined
    setIsGradient(false);

    switch(type) {
      case 'ink': 
        applyPresetState({ name: 'ink', tension: 0.25, fluidity: 5, waveAmp: 0, calligraphyAmount: 90, penAngle: 30, echoes: 0, glow: 0, inkDensity: 60, erosion: 5, particles: 0, engine: 'pluma' });
        break;
      case 'calligraphy':
        applyPresetState({ name: 'calligraphy', tension: 0.2, fluidity: 0, waveAmp: 0, calligraphyAmount: 100, penAngle: 45, echoes: 0, glow: 0, inkDensity: 0, erosion: 0, particles: 0, engine: 'pluma' });
        break;
      case 'marker':
        applyPresetState({ name: 'marker', tension: 0.3, fluidity: 2, waveAmp: 0, calligraphyAmount: 10, penAngle: 90, echoes: 0, glow: 0, inkDensity: 5, erosion: 2, particles: 0, engine: 'pluma' });
        break;
      case 'liquid':
        applyPresetState({ name: 'liquid', tension: 0.5, fluidity: 0, waveFreq: 2, waveAmp: 15, calligraphyAmount: 0, echoes: 1, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 0, particles: 10, engine: 'plasma' });
        break;
      case 'tech':
        applyPresetState({ name: 'tech', tension: 0, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 2, echoOffset: 8, glow: 12, inkDensity: 0, erosion: 0, particles: 30, engine: 'tech' });
        break;
      case 'chaos':
        applyPresetState({ name: 'chaos', tension: 0.8, fluidity: 20, waveFreq: 10, waveAmp: 5, calligraphyAmount: 50, echoes: 0, glow: 8, inkDensity: 80, erosion: 15, particles: 20, engine: 'nexo' });
        break;
      case 'ghost':
        applyPresetState({ name: 'ghost', tension: 0.3, fluidity: 5, waveAmp: 5, calligraphyAmount: 0, echoes: 4, echoOffset: 15, glow: 20, inkDensity: 0, erosion: 3, particles: 10, engine: 'plasma' });
        break;
      case 'void':
        applyPresetState({ name: 'void', tension: 0.3, fluidity: 0, waveAmp: 0, calligraphyAmount: 0, echoes: 3, echoOffset: 5, glow: 5, inkDensity: 0, erosion: 1, particles: 5, engine: 'tech' });
        break;
    }
  };

  const applyColorPreset = (start: string, end: string) => {
    setGradientColors({ start, end });
    setIsGradient(true);
  };

  const saveCurrentAsPreset = () => {
    if (!newPresetName || !onSavePreset) return;
    const newPreset: TaelimPreset = {
      id: crypto.randomUUID(),
      name: newPresetName,
      tension, fluidity, waveFreq, waveAmp, glow, echoes, echoOffset,
      inkDensity, erosion, particles, penAngle, calligraphyAmount, engine,
      // Enhanced parameters
      smoothEnds,
      isGradient,
      gradientColors: isGradient ? gradientColors : undefined,
      // Save current average thickness as the preset base thickness
      baseNodeThickness: segmentPressures.length > 0 ? segmentPressures[0].start : 10,
      baseStrokeThickness: segmentPressures.length > 0 ? segmentPressures[0].mid : 10
    };
    onSavePreset(newPreset);
    setIsSavingPreset(false);
    setNewPresetName('');
  };


  // --- RENDER LOGIC ---
  const renderTrace = () => {
    if (activePoints.length === 0) return null;

    const splinePoints = getBezierPointsWithWeight(
      activePoints, 
      segmentPressures,
      tension, 
      20, 
      waveFreq,
      waveAmp,
      smoothEnds // Pass smoothing preference
    );

    const paths = [];
    // If gradient is active, use URL ref, else currentColor
    const baseColor = isGradient ? 'url(#traceGradient)' : 'currentColor';

    const totalLayers = 1 + echoes;
    const filterUrl = erosion > 0 ? "url(#erosion-filter)" : undefined;

    const layerPaths = [];

    for (let i = 0; i < totalLayers; i++) {
      let layerPoints = splinePoints;
      let opacity = 1;

      let widthMultiplier = 1;

      if (i > 0) {
        const offset = i * echoOffset;
        layerPoints = splinePoints.map(p => ({ ...p, x: p.x + offset, y: p.y + offset }));
        opacity = 0.4 / i;
        widthMultiplier = 0.6;
      }

      const finalLayerPoints = layerPoints.map(p => ({ ...p, w: p.w * widthMultiplier }));

      const pathData = getBrushPath(finalLayerPoints, {
        angleInfluence: calligraphyAmount / 100,
        penAngleDeg: penAngle,
        roundedCaps: smoothEnds // Use smooth ends setting
      });

      layerPaths.push(
        <path 
          key={`path-${i}`} 
          d={pathData} 
          fill={baseColor} 
          opacity={engine === 'tech' && i > 0 ? 0.8 : 0.8 * opacity}
          fillRule="nonzero"
        />
      );
    }

    paths.push(<g key="layers" filter={filterUrl}>{layerPaths}</g>);

    if (engine === 'tech') {
       paths.push(
         <path 
            key="wireframe"
            d={`M ${activePoints.map(p => `${p.x} ${p.y}`).join(' L ')}`}
            fill="none"
            stroke={baseColor}
            strokeWidth={1}
            opacity={0.5}
            strokeDasharray="4 4"
         />
       );
    }

    if (inkDensity > 0) {
      activePoints.forEach((p, idx) => {
        const seed = (p.x * p.y) + idx;
        const count = Math.floor((inkDensity / 10) * ((seed % 10) / 10 + 0.5)); 
        const segIdx = Math.min(idx, segmentPressures.length - 1);
        const localW = segmentPressures[segIdx] ? segmentPressures[segIdx].start : 10;

        const dots = [];
        for(let k=0; k<count; k++) {
            const angle = (seed * k) % (Math.PI * 2);
            const dist = 10 + (seed * k * 7) % 60;
            const size = (localW / 4) * (((seed + k)%10)/10);
            dots.push(
                <circle 
                    key={`spat-${idx}-${k}`} 
                    cx={p.x + Math.cos(angle)*dist} 
                    cy={p.y + Math.sin(angle)*dist} 
                    r={size} 
                    fill={baseColor} 
                    opacity={0.6} 
                />
            );
        }
        paths.push(<g key={`spats-${idx}`}>{dots}</g>);
      });
    }

    if (particles > 0) {
         activePoints.forEach((p, idx) => {
            const count = Math.floor(particles / 2);
            const dots = [];
             for(let k=0; k<count; k++) {
                const angle = (p.x * k) % (Math.PI * 2);
                const dist = 20 + (p.y * k) % 80;
                dots.push(
                    <circle 
                        key={`part-${idx}-${k}`} 
                        cx={p.x + Math.cos(angle)*dist} 
                        cy={p.y + Math.sin(angle)*dist} 
                        r={1 + (k%2)} 
                        fill={baseColor} 
                        opacity={0.4} 
                    />
                );
            }
            paths.push(<g key={`parts-${idx}`} filter="url(#neon-glow)">{dots}</g>);
         });
    }

    return <g>{paths}</g>;
  };

  const handleRandomWord = () => {
    if (terms.length > 0) setText(terms[Math.floor(Math.random() * terms.length)].root);
  };

  const performExport = () => {
    if (!svgRef.current) return;

    // 1. Clonar el nodo SVG para manipularlo sin afectar la vista
    const clonedSvg = svgRef.current.cloneNode(true) as SVGSVGElement;

    // 2. Modificar colores en el clon
    // Buscar el grupo que tiene la clase text-* y reemplazarlo por el color deseado
    const coloredGroups = clonedSvg.querySelectorAll(`[class*="text-"]`);
    coloredGroups.forEach(el => {
      // Remove text- classes that control color
      const classes = el.getAttribute('class') || '';
      const newClasses = classes.replace(/text-\w+-\d+/g, '').trim();
      el.setAttribute('class', newClasses);
      // Force inline style color only if NOT using gradient
      if (!exportConfig.useGradient) {
         (el as SVGElement).style.color = exportConfig.strokeColor;
      }
    });

    // Handle Gradient Export
    if (exportConfig.useGradient) {
       // Find paths that used url(#traceGradient) and keep them, 
       // but ensure the defs are copied correctly (which cloneNode does).
       // If the gradient uses 'current' DOM state, it should be fine in the clone.
       // However, Canvas cannot directly render SVG gradients referenced by URL inside `drawImage` sometimes
       // if the context is lost. But usually serializeToString works.

       // Force update gradient colors in the clone just in case
       const gradStop1 = clonedSvg.querySelector('#traceGradient stop:nth-child(1)');
       const gradStop2 = clonedSvg.querySelector('#traceGradient stop:nth-child(2)');
       if (gradStop1) gradStop1.setAttribute('stop-color', gradientColors.start);
       if (gradStop2) gradStop2.setAttribute('stop-color', gradientColors.end);
    } else {
       // If no gradient, replace fills
       const paths = clonedSvg.querySelectorAll('path');
       paths.forEach(p => {
          if (p.getAttribute('fill') === 'url(#traceGradient)') {
             p.setAttribute('fill', exportConfig.strokeColor);
          }
       });
    }

    // 3. Manejar Guías (Grid)
    if (!exportConfig.includeGuides) {
      const gridGroup = clonedSvg.querySelector('.opacity-20.pointer-events-none');
      if (gridGroup) gridGroup.remove();

      const nodes = clonedSvg.querySelectorAll('rect[width="8"]');
      nodes.forEach(n => n.parentElement?.remove());
    }

    // Remove sequence numbers if not desired in export or clean up generally
    // (Sequence numbers are rendered as text in SVG, so they persist if guides persist? 
    // actually, they are separate. Let's ensure logic is consistent).
    // The current render puts sequence numbers in the "Active Points" loop.
    // If includeGuides is false, we usually remove that loop. 
    // We'll trust the cloned SVG state based on what was visible, or manually strip if needed.

    // 4. Serializar
    const svgData = new XMLSerializer().serializeToString(clonedSvg);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();
    const scaleFactor = 3;
    const paddingBottom = exportConfig.includeMetadata ? 300 : 0;

    canvas.width = viewWidth * scaleFactor;
    canvas.height = (viewHeight * scaleFactor) + paddingBottom;

    img.onload = () => {
      if(ctx) {
        // Draw Background
        if (!exportConfig.isTransparent) {
           ctx.fillStyle = exportConfig.bgColor; 
           ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        // Draw Image
        ctx.drawImage(img, 0, 0, viewWidth * scaleFactor, viewHeight * scaleFactor);

        // Draw Start/End Markers if requested
        if (exportConfig.includeStartEnd && activePoints.length > 0) {
           const startP = activePoints[0];
           const endP = activePoints[activePoints.length - 1];

           ctx.font = "bold 60px 'JetBrains Mono', monospace";
           ctx.textAlign = "center";
           ctx.textBaseline = "middle";

           // Start Marker (Greenish)
           ctx.fillStyle = "#22c55e"; 
           ctx.beginPath();
           ctx.arc(startP.x * scaleFactor, startP.y * scaleFactor, 40, 0, Math.PI * 2);
           ctx.fill();
           ctx.fillStyle = "#000000";
           ctx.fillText("S", startP.x * scaleFactor, startP.y * scaleFactor);

           // End Marker (Reddish)
           ctx.fillStyle = "#ef4444"; 
           ctx.beginPath();
           ctx.arc(endP.x * scaleFactor, endP.y * scaleFactor, 40, 0, Math.PI * 2);
           ctx.fill();
           ctx.fillStyle = "#000000";
           ctx.fillText("E", endP.x * scaleFactor, endP.y * scaleFactor);
        }

        // Draw Metadata
        if (exportConfig.includeMetadata) {
          const currentTerm = terms.find(t => t.root.toLowerCase() === text.toLowerCase());
          const displayRoot = currentTerm ? currentTerm.root : text;
          const displayMeaning = currentTerm ? currentTerm.meaning : "Trazo Libre";

          ctx.textAlign = 'center';
          ctx.fillStyle = exportConfig.useGradient ? gradientColors.start : exportConfig.strokeColor; 
          ctx.font = "bold 80px 'Space Grotesk', sans-serif";
          ctx.fillText(displayRoot.toUpperCase(), canvas.width / 2, (viewHeight * scaleFactor) + 100);

          ctx.fillStyle = exportConfig.bgColor === '#ffffff' ? '#64748b' : '#94a3b8'; // Adapting contrast
          ctx.font = "50px 'Space Grotesk', sans-serif";
          ctx.fillText(displayMeaning, canvas.width / 2, (viewHeight * scaleFactor) + 180);
        }

        const link = document.createElement("a");
        link.download = `Taelim_${text || 'Export'}.png`;
        link.href = canvas.toDataURL("image/png");
        link.click();

        setShowExportModal(false);
      }
    };
    img.src = "data:image/svg+xml;base64," + btoa(unescape(encodeURIComponent(svgData)));
