                   {activePoints.length === 1 && segmentPressures.length > 0 && (
                      <div className="bg-slate-900 p-2 border border-slate-800">
                        <div className="flex items-center justify-between mb-2">
                           <span className="text-[10px] font-bold text-cyan-400 bg-cyan-900/20 px-1.5 py-0.5 border border-cyan-900/50">{activePoints[0].char}</span>
                           <span className="text-[9px] text-slate-500 uppercase">Punto Único</span>
                        </div>
                        <div className="flex items-center gap-2">
                             <span className="text-[8px] text-slate-500 w-8 uppercase">Base</span>
                             <input 
                                 type="range" min="1" max="50" step="0.5" 
                                 value={segmentPressures[0].start} 
                                 onChange={(e) => updateSegment(0, 'start', Number(e.target.value))}
                                 className="flex-1 h-1 bg-slate-800 rounded-none appearance-none accent-cyan-500" 
                             />
                        </div>
                      </div>
                   )}

                   {/* Standard Segments */}
                   {activePoints.length > 1 && segmentPressures.map((seg, idx) => {
                     const charStart = activePoints[idx]?.char || '?';
                     const charEnd = activePoints[idx+1]?.char || '?';

                     return (
                      <div key={idx} className="bg-slate-900 p-2 border-l-2 border-slate-700 hover:border-cyan-500 transition-colors">
                        <div className="flex items-center justify-between mb-2">
                            <div className="flex items-center gap-2">
                                <span className="text-[10px] font-bold text-cyan-400 bg-cyan-950 px-1 border border-cyan-900">{charStart}</span>
                                <ArrowRight size={10} className="text-slate-600" />
                                <span className="text-[10px] font-bold text-emerald-400 bg-emerald-950 px-1 border border-emerald-900">{charEnd}</span>
