                  <input type="range" min="0" max="50" value={glow} onChange={(e) => setGlow(Number(e.target.value))} className="w-full h-1 bg-slate-800 rounded-none appearance-none accent-orange-500" />
               </div>
            </div>

          </div>
        </div>

        {/* --- VISUALIZADOR --- */}
