             <div className="w-px h-6 bg-slate-800 my-auto mx-1"></div>

             <button onClick={() => setZoom(z => Math.max(0.5, z - 0.1))} className="p-2 text-slate-500 hover:text-white"><ZoomOut size={18} /></button>
             <button onClick={() => setZoom(z => Math.min(2.0, z + 0.1))} className="p-2 text-slate-500 hover:text-white"><ZoomIn size={18} /></button>
             <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 px-3 py-2 bg-cyan-700 hover:bg-cyan-600 text-white rounded-none ml-2 font-bold text-xs uppercase tracking-widest border border-cyan-500"><Download size={14} /> Exportar</button>
           </div>

           <div className={`flex-1 border border-slate-800 overflow-hidden relative flex items-center justify-center shadow-[inset_0_0_20px_rgba(0,0,0,0.5)] tech-border transition-colors duration-500 ${lightMode ? 'bg-slate-100' : 'bg-slate-950'}`}>
             {/* Background Grid inside canvas */}
             <div className="absolute inset-0 opacity-10 pointer-events-none" style={{backgroundImage: `linear-gradient(${lightMode ? '#94a3b8' : 'rgba(14,165,233,0.3)'} 1px, transparent 1px), linear-gradient(90deg, ${lightMode ? '#94a3b8' : 'rgba(14,165,233,0.3)'} 1px, transparent 1px)`, backgroundSize: '40px 40px'}}></div>

             <div className="w-full h-full overflow-auto flex items-center justify-center custom-scrollbar p-10 relative z-10">
               <div style={{ width: viewWidth, height: viewHeight, transform: `scale(${zoom})`, transition: 'transform 0.3s ease-out' }}>
                 <svg ref={svgRef} viewBox={`0 0 ${viewWidth} ${viewHeight}`} className="w-full h-full drop-shadow-2xl overflow-visible">
                    <defs>
                      <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation={glow} result="coloredBlur" />
                        <feMerge>
                          <feMergeNode in="coloredBlur" />
                          <feMergeNode in="SourceGraphic" />
                        </feMerge>
                      </filter>
                      <filter id="erosion-filter" x="-20%" y="-20%" width="140%" height="140%">
                        <feTurbulence type="fractalNoise" baseFrequency="0.05" numOctaves="3" result="noise" />
                        <feDisplacementMap in="SourceGraphic" in2="noise" scale={erosion} />
                      </filter>
                      {/* Dynamic Gradient Def */}
                      <linearGradient id="traceGradient" x1={gradientCoords.x1} y1={gradientCoords.y1} x2={gradientCoords.x2} y2={gradientCoords.y2} gradientUnits="userSpaceOnUse">
                         <stop offset="0%" stopColor={gradientColors.start} />
                         <stop offset="100%" stopColor={gradientColors.end} />
                      </linearGradient>
                    </defs>

                    {/* Guías */}
                    {showGuides && (
                      <g className="grid-layer" style={{opacity: gridOpacity, transition: 'opacity 0.2s'}}>
                        {currentGrid.map((row, y) => row.map((char, x) => (
                           <g key={`${x}-${y}`}>
                             <rect x={PADDING + x * CELL_SIZE - 2} y={PADDING + y * CELL_SIZE - 2} width="4" height="4" fill={lightMode ? '#cbd5e1' : '#334155'} />
                             <text x={PADDING + x * CELL_SIZE} y={PADDING + y * CELL_SIZE + 40} textAnchor="middle" fill={lightMode ? '#94a3b8' : '#475569'} fontSize="10" fontFamily="monospace" opacity={0.5}>{char}</text>
                           </g>
                        )))}
                      </g>
                    )}

                    {/* TRAZO PRINCIPAL (Moved to bottom layer) */}
                    <g filter={glow > 0 ? "url(#neon-glow)" : ""} className={mode === 'algante' ? 'text-cyan-400' : 'text-emerald-400'}>
                      {renderTrace()}
                    </g>

                    {/* Nodos Activos & Esqueleto (Moved to top layer) */}
                    {showGuides && activePoints.length > 0 && (
                      <g>
                        {/* New Connected Polyline Skeleton */}
                        {showSkeleton && activePoints.length > 1 && (
                          <polyline 
                            points={activePoints.map(p => `${p.x},${p.y}`).join(' ')}
                            fill="none"
                            stroke={lightMode ? "#94a3b8" : "#475569"}
                            strokeWidth="1.5"
                            strokeDasharray="4 4"
                            opacity="0.6"
                          />
                        )}

                        {activePoints.map((p, i) => (
                          <g key={i}>
                            <rect x={p.x - 4} y={p.y - 4} width="8" height="8" fill={mode === 'algante' ? '#06b6d4' : '#10b981'} opacity={0.8} />
                            {/* Original offset tether, optional, kept for detail but less prominent */}
                            {showSkeleton && fluidity > 0 && (
                               <line x1={p.originalX} y1={p.originalY} x2={p.x} y2={p.y} stroke={lightMode ? "#cbd5e1" : "#334155"} strokeWidth="1" opacity="0.3" />
                            )}
                            <text x={p.x} y={p.y - 15} textAnchor="middle" fill={lightMode ? "#334155" : "white"} fontSize="12" fontWeight="bold">{p.char}</text>
                            {/* Sequence Numbering */}
                            {showSequence && (
                              <g transform={`translate(${p.x + 15}, ${p.y - 15})`}>
                                  <circle r="8" fill="#f59e0b" />
                                  <text dy="3" textAnchor="middle" fontSize="10" fontWeight="bold" fill="black">{i + 1}</text>
                              </g>
                            )}
                          </g>
                        ))}
                      </g>
                    )}

                 </svg>
               </div>
             </div>
           </div>

        </div>
      </div>
    </div>
  );
};

