            >
              <option value="">// TODAS LAS CATEGORÍAS</option>
              {CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <select 
            value={tonalityFilter}
            onChange={(e) => setTonalityFilter(e.target.value)}
            className="bg-slate-900 border border-slate-700 hover:border-cyan-500/50 rounded-none px-4 py-3 text-slate-300 outline-none cursor-pointer text-xs uppercase font-bold tracking-wider w-full sm:w-auto"
          >
            <option value="">// CUALQUIER TONALIDAD</option>
            {Object.values(Tonality).map(t => <option key={t} value={t}>{t}</option>)}
          </select>
        </div>

        {compareList.length > 0 && (
          <button 
            onClick={() => setShowCompareModal(true)}
            className="mt-2 flex items-center justify-center gap-2 bg-orange-600 hover:bg-orange-500 text-black font-bold uppercase tracking-widest text-xs px-6 py-3 rounded-none transition-colors border-l-4 border-orange-400"
          >
            <GitCompare size={16} />
            <span>Comparar ({compareList.length})</span>
          </button>
        )}
      </div>

      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {filteredTerms.map(term => (
          <div key={term.id} className="group tech-border p-6 transition-all duration-300 relative overflow-hidden flex flex-col h-full hover:border-cyan-500/40 hover:shadow-[0_0_15px_rgba(8,145,178,0.1)]">

            {/* Top Decoration */}
            <div className="absolute top-0 right-0 p-1 flex items-center gap-1">
               <div className="w-1 h-1 bg-slate-600 rounded-full"></div>
               <div className="w-1 h-1 bg-slate-600 rounded-full"></div>
               <div className="w-16 h-0.5 bg-slate-800"></div>
            </div>

            {/* Action Buttons (Edit + Compare) */}
            <div className="absolute top-4 right-4 z-10 flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-950/80 p-1 border border-slate-700">
              <button 
                onClick={() => handleEditClick(term)}
                className="p-1.5 hover:bg-cyan-500 hover:text-black text-slate-400 transition-colors"
                title="Editar Radical"
              >
                <Edit2 size={14} />
              </button>
              <input 
